window.HS_LOAD(5,{"intro":[[["نبی کریمؐ اور آپؐ کے صحابہ کرامؓ کس طرح دعا میں ",""],["ٱللَّٰه","a"],[" کے سامنے گڑگڑایا کرتے تھے اور کن کاموں کے لیے دعا کیا کرتے تھے اور کس وقت دعا کیا کرتے تھے اور ان کی دعائیں کیسی ہوا کرتی تھیں",""]]],"topics":{"118":{"lead":[],"stories":[{"b":[["n",[["حضرت معاذ بن جبلؓ","b"],[" فرماتے ہیں حضورؐ ایک آدمی کے پاس سے گزرے وہ یہ دعا کر رہا تھا اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے صبر کی توفیق مانگتا ہوں۔ آپؐ نے فرمایا تو نے تو ",""],["ٱللَّٰه","a"],[" سے مصیبت کو مانگ لیا (کیونکہ پہلے کوئی مصیبت آئے گی پھر اس کے بعد صبر ہوگا) تو ",""],["ٱللَّٰه","a"],[" سے عافیت کو مانگ (کوئی مصیبت آ جائے تو پھر صبر مانگنا چاہیے)۔ اور آپؐ کا گزر ایک اور آدمی پر ہوا جو یہ دعا مانگ رہا تھا اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے پوری نعمت مانگتا ہوں۔ حضورؐ نے فرمایا اے آدم کے بیٹے! تم جانتے ہو کہ پوری نعمت کیا ہے؟ اس نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! یہ تو میں نے خیر کی امید میں دعا مانگ لی ہے (مجھے نہیں پتہ کہ پوری نعمت کیا ہوتی ہے)۔ آپؐ نے فرمایا پوری نعمت یہ ہے کہ آدمی جہنم کی آگ سے بچ جائے اور جنت میں چلا جائے۔ حضورؐ ایک اور آدمی کے پاس سے گزرے وہ کہہ رہا تھا",""]]],["q",[["يَا ذَا ٱلْجَلَالِ وَٱلْإِكْرَامِ","a"]]],["p",[["ترجمہ: \"اے بزرگی اور عزت والے!\" آپؐ نے فرمایا ان الفاظ سے پکارنے کی وجہ سے تیرے لیے قبولیت کا دروازہ کھل گیا ہے، اب تو مانگ۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.292)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں حضورؐ ایک آدمی کے پاس گئے، وہ کمزوری اور بیماری کی وجہ سے پرندے کے اس بچے کی طرح نظر آ رہا تھا جس کے پر کسی نے نوچ لیے ہوں۔ حضورؐ نے اس سے پوچھا کیا تو کوئی خاص دعا مانگا کرتا تھا؟ اس نے کہا میں یہ دعا مانگا کرتا تھا کہ اے ",""],["ٱللَّٰه","a"],["! تو نے مجھے جو سزا آخرت میں دینی ہے وہ دنیا ہی میں جلد دے دے۔ حضورؐ نے فرمایا تم نے یہ دعا کیوں نہیں مانگی کہ اے ",""],["ٱللَّٰه","a"],["! ہمیں دنیا میں بھی خیر و خوبی عطا فرما اور آخرت میں بھی خیر و خوبی عطا فرما اور ہمیں آگ کے عذاب سے بچا لے! چنانچہ اس نے ",""],["ٱللَّٰه","a"],[" سے یہ دعا مانگی تو ",""],["ٱللَّٰه","a"],[" نے اسے شفا دے دی۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abi Shaybah and Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.1 Pg.290)."]]},{"b":[["n",[["حضرت بشیر بن خصاصیہؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جو تمہیں ربیعہ قبیلہ سے یہاں لایا اور پھر تمہیں ",""],["ٱللَّٰه","a"],[" کے رسول کے ہاتھ پر مسلمان ہونے کی توفیق دی۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپ ",""],["ٱللَّٰه","a"],[" سے دعا کریں کہ وہ مجھے آپ سے پہلے موت دے دے۔ حضورؐ نے فرمایا یہ دعا میں کسی کے لیے نہیں کر سکتا۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.147)."]]},{"b":[["n",[["حضرت ابی بن کعبؓ","b"],[" فرماتے ہیں حضورؐ جب کسی کے لیے دعا فرماتے تو دعا کی ابتداء اپنے سے فرماتے۔ چنانچہ ایک مرتبہ حضرت موسیٰ علیہ السلام کا ذکر فرمایا تو ارشاد فرمایا ",""],["ٱللَّٰه","a"],[" کی رحمت ہم پر ہو اور حضرت موسیٰ پر ہو، اگر وہ صبر کرتے تو وہ اپنے استاد (حضرت خضر علیہ السلام) کی طرف سے اور بہت سی عجیب عجیب باتیں دیکھتے لیکن انہوں نے یہ کہہ دیا",""]]],["q",[["إِن سَأَلْتُكَ عَن شَىْءٍۭ بَعْدَهَا فَلَا تُصَٰحِبْنِىٓ ۖ قَدْ بَلَغْتَ مِن لَّدُنِّىٓ عُذْرًا","a"]]],["p",[["ترجمہ: \"اگر اس مرتبہ کے بعد آپ سے کسی امر کے متعلق کچھ پوچھوں تو آپ مجھ کو اپنے ساتھ نہ رکھئے، بے شک میری طرف سے آپ عذر (کی انتہا) کو پہنچ چکے ہیں۔\" (سورت کہف آیت ۷۶)",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abi Shaybah, Ahmad, Abu Dawood, Nasa'ee and others, as quoted in Kanzul Ummaal (Vol.1 Pg.290). Tirmidhi has reported a similar narration, as quoted in Kanzul Ummaal (Vol.1 Pg.290)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" نے حضرت ابن ابی السائبؒ سے جو کہ مدینہ والوں کے واعظ تھے فرمایا دعا میں بتکلف ایک جیسی عبارت لانے سے بچو کیونکہ میں نے حضورؐ اور صحابہؓ کا زمانہ پایا ہے، وہ ایسا نہیں کیا کرتے تھے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.292)."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" نے ایک آدمی کو سنا کہ فتنہ سے پناہ مانگ رہا تھا۔ حضرت عمرؓ نے فرمایا اے ",""],["ٱللَّٰه","a"],["! اس کی دعا کے الفاظ سے تیری پناہ چاہتا ہوں۔ پھر اس آدمی سے فرمایا کیا تم ",""],["ٱللَّٰه","a"],[" سے یہ مانگ رہے ہو کہ وہ تمہیں بیوی بچے اور مال نہ دے؟ (کیونکہ قرآن میں مال اور اولاد کو فتنہ کہا گیا ہے) تم میں سے جو بھی فتنہ سے پناہ مانگنا چاہتا ہے اسے چاہیے کہ وہ گمراہ کرنے والے فتنوں سے پناہ مانگے۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abi Shaybah and Abu Ubayd, as quoted in Kanzul Ummaal (Vol.1 Pg.289)."]]},{"b":[["n",[["حضرت محارب بن دثارؒ","b"],[" کے چچا کہتے ہیں میں آخر شب میں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ کے گھر کے پاس سے گزرا کرتا تھا، انہیں میں یہ دعا فرماتے ہوئے سنتا تھا اے ",""],["ٱللَّٰه","a"],["! تو نے مجھے بلایا میں نے اس پر لبیک کہا، تو نے مجھے حکم دیا میں نے تیری اطاعت کی اور یہ سحری کا وقت ہے لہٰذا تو میری مغفرت کر دے۔ پھر میری حضرت ابن مسعودؓ سے ملاقات ہوئی میں نے ان سے کہا کہ میں نے آپ کو آخر شب میں چند کلمات کہتے ہوئے سنا ہے، پھر میں نے وہ کلمات انہیں بتائے تو انہوں نے فرمایا حضرت یعقوب علیہ السلام نے اپنے بیٹوں سے وعدہ فرمایا تھا کہ میں تمہارے لیے اپنے رب سے استغفار کروں گا تو انہوں نے آخر شب میں ان کے لیے دعائے مغفرت کی تھی۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani. Haythami (Vol.10 Pg.155) has commented on the chain of narrators."]]}]},"119":{"lead":[],"stories":[{"b":[["n",[["حضرت عمرؓ","b"],[" فرماتے ہیں حضورؐ جب دعا فرماتے تھے تو اپنے دونوں ہاتھ اٹھاتے تھے اور جب دعا سے فارغ ہو جاتے تو دونوں ہاتھ اپنے چہرے پر پھیر لیتے۔",""],[" (1)","s"]]]],"f":[["(1)","Haakim."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" فرماتے ہیں حضورؐ جب دعا میں ہاتھ اٹھا لیتے تھے تو جب تک انہیں اپنے چہرے پر نہ پھیر لیتے اس وقت تک نیچے نہ کرتے۔",""],[" (2)","s"]]]],"f":[["(2)","Tirmidhi."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" فرماتے ہیں میں نے نبی کریمؐ کو احجار الزیت (مسجد نبوی کے مغرب میں ایک جگہ کا نام ہے) کے پاس دیکھا کہ آپؐ دعا مانگ رہے تھے اور آپؐ کی ہتھیلیاں منہ کی طرف تھیں۔ جب آپؐ دعا سے فارغ ہو گئے تو آپؐ نے ہتھیلیاں اپنے منہ پر پھیر لیں۔",""],[" (3)","s"]]]],"f":[["(3)","Abdul Ghani in his Idaahul Ashkaal, as quoted in Kanzul Ummaal (Vol.1 Pg.289)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ دعا میں اتنی دیر ہاتھ اٹھائے رکھتے تھے کہ میں تھک جاتی تھی۔ عبدالرزاق میں حضرت عائشہؓ سے اس جیسی روایت منقول ہے، اس میں یہ بھی ہے کہ حضورؐ نے یہ دعا مانگی",""]]],["q",[["ٱللَّهُمَّ إِنَّمَا أَنَا بَشَرٌ فَلَا تُعَذِّبْنِي بِشَتْمِ رَجُلٍ شَتَمْتُهُ أَوْ أَذَيْتُهُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں بشر ہی تو ہوں، میں نے کسی کو برا بھلا کہا ہو یا کسی کو تکلیف پہنچائی ہو تو اس وجہ سے مجھے عذاب نہ دینا۔\"",""],[" (4)","s"],[" (5)","s"]]]],"f":[["(4)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.168)."],["(5)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.1 Pg.291)."]]},{"b":[["n",[["ایک مرتبہ ",""],["حضرت عائشہؓ","b"],[" نے دیکھا کہ حضورؐ دونوں ہاتھ اٹھا کر یہ دعا کر رہے ہیں کہ میں بشر ہی تو ہوں اس لیے مجھے سزا نہ دے، اگر میں نے کسی مومن کو تکلیف دی ہو یا اسے برا بھلا کہا ہو تو اس وجہ سے مجھے سزا نہ دینا۔",""],[" (6)","s"]]]],"f":[["(6)","Bukhaari in his Adab (Pg.90)."]]},{"b":[["n",[["حضرت عروہؓ","b"],[" فرماتے ہیں کہ حضورؐ کا دیہاتیوں کی ایک قوم کے پاس سے گزر ہوا۔ یہ مسلمان ہو چکے تھے اور کافروں کے لشکروں نے ان کے علاقے کو تباہ و برباد کر دیا تھا۔ حضورؐ نے ان کے لیے دعا کرنے کے لیے ہاتھ اپنے چہرے کی طرف اٹھائے تو ایک دیہاتی نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! میرے ماں باپ آپ پر قربان ہوں، ہاتھ اور لمبے فرما دیں تو آپؐ نے اپنے چہرے کے آگے اور بڑھا دیے، آسمان کی طرف اور اوپر نہ اٹھائے۔",""],[" (7)","s"]]]],"f":[["(7)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.1 Pg.291)."]]},{"b":[["n",[["حضرت ابونعیم وہبؒ","b"],[" کہتے ہیں میں نے دیکھا کہ حضرت ابن عمرؓ اور حضرت ابن زبیرؓ دعا کر رہے تھے اور دعا کے بعد انہوں نے اپنی ہتھیلیاں اپنے چہرے پر پھیریں۔",""],[" (8)","s"]]]],"f":[["(8)","Bukhaari in his Adab (Pg.90)."]]}]},"120":{"lead":[],"stories":[{"b":[["n",[["حضرت قیس مدنیؒ","b"],[" کہتے ہیں کہ ایک آدمی نے حضرت زید بن ثابتؓ کی خدمت میں حاضر ہو کر کسی چیز کے بارے میں پوچھا۔ انہوں نے فرمایا تم جا کر یہ بات حضرت ابوہریرہؓ سے پوچھو کیونکہ ایک مرتبہ میں، حضرت ابوہریرہؓ اور فلاں آدمی ہم تینوں مسجد میں دعا کر رہے تھے اور اپنے رب کا ذکر کر رہے تھے کہ اتنے میں حضورؐ ہمارے پاس تشریف لائے اور ہمارے پاس بیٹھ گئے تو ہم خاموش ہو گئے۔ پھر فرمایا جو تم کر رہے تھے اسے کرتے رہو۔ چنانچہ میں اور میرے ساتھی نے حضرت ابوہریرہؓ سے پہلے دعا کی اور حضورؐ ہماری دعا پر آمین کہتے رہے۔ پھر حضرت ابوہریرہؓ نے یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! میرے ان دو ساتھیوں نے جو کچھ تجھ سے مانگا ہے وہ بھی تجھ سے مانگتا ہوں اور ایسا علم بھی مانگتا ہوں جو کبھی نہ بھولے۔ حضورؐ نے فرمایا آمین۔ ہم نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہم بھی ",""],["ٱللَّٰه","a"],[" سے وہ علم مانگتے ہیں جو کبھی نہ بھولے۔ حضورؐ نے فرمایا یہ دوسی نوجوان (یعنی حضرت ابوہریرہؓ) تم دونوں سے آگے نکل گئے۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani in his Awsat, as quoted in Majma'uz Zawaa'id (Vol.9 Pg.321)."]]},{"b":[["n",[["حضرت جامع بن شدادؒ","b"],[" کے ایک رشتہ دار کہتے ہیں کہ میں نے حضرت عمر بن خطابؓ کو فرماتے ہوئے سنا کہ تین دعائیں ایسی ہیں کہ جب وہ مانگوں تو تم ان پر آمین کہنا اے ",""],["ٱللَّٰه","a"],["! میں کمزور ہوں مجھے قوت عطا فرما، اے ",""],["ٱللَّٰه","a"],["! میں سخت ہوں مجھے نرم کر دے، اے ",""],["ٱللَّٰه","a"],["! میں کنجوس ہوں مجھے سخی بنا دے۔",""]]]],"f":[]},{"b":[["n",[["حضرت سائب بن یزیدؒ","b"],[" کہتے ہیں میں نے رمادہ قحط سالی کے زمانے میں حضرت عمر بن خطابؓ کو دیکھا کہ وہ صبح کے وقت عام سادہ سے کپڑے پہنے ہوئے عاجز اور مسکین بن کر جا رہے ہیں اور ان کے جسم پر ایک چھوٹی سی چادر پڑی ہوئی ہے جو گھٹنوں تک مشکل سے پہنچ رہی ہے۔ اونچی آواز سے ",""],["ٱللَّٰه","a"],[" سے معافی مانگ رہے ہیں اور ان کی آنکھوں سے رخسار پر آنسو بہہ رہے ہیں اور ان کے دائیں طرف حضرت عباس بن عبدالمطلبؓ ہیں۔ اس دن انہوں نے قبلہ کی طرف منہ کر کے ہاتھ آسمان کی طرف اٹھا کر بہت گڑگڑا کر دعا مانگی۔ لوگ بھی ان کی طرح دعا مانگ رہے تھے۔ پھر حضرت عمرؓ نے حضرت عباسؓ کے ہاتھ کو پکڑ کر کہا اے ",""],["ٱللَّٰه","a"],["! ہم تیرے رسولؐ کے چچا کو تیرے سامنے سفارشی بناتے ہیں۔ پھر حضرت عباسؓ بہت دیر تک حضرت عمرؓ کے پہلو میں کھڑے ہو کر دعا مانگتے رہے۔ ان کی آنکھوں سے بھی آنسو بہہ رہے تھے۔",""],[" (2)","s"],[" (3)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.3 Pg.275)."],["(3)","Ibn Sa'd (Vol.3 Pg.321)."]]},{"b":[["n",[["حضرت ابواسیدؓ","b"],[" کے آزاد کردہ غلام ",""],["حضرت ابوسعیدؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ عشاء کے بعد مسجد کا چکر لگاتے اور اس میں جو آدمی بھی نظر آتا اسے مسجد سے نکال دیتے، جسے کھڑا ہوا نماز پڑھتے ہوئے دیکھتے اسے رہنے دیتے۔ ایک رات ان کا حضورؐ کے چند صحابہؓ پر گزر ہوا جن میں حضرت ابی بن کعبؓ بھی تھے۔ حضرت عمرؓ نے پوچھا یہ لوگ کون ہیں؟ حضرت ابیؓ نے کہا اے امیر المومنین! آپ کے گھر کے چند آدمی ہیں۔ فرمایا نماز کے بعد تم لوگ اب تک یہاں کیوں بیٹھے ہوئے ہیں؟ حضرت ابیؓ نے فرمایا ہم بیٹھ کر ",""],["ٱللَّٰه","a"],[" کا ذکر کر رہے ہیں۔ اس پر حضرت عمرؓ بھی ان کے پاس بیٹھ گئے اور ان میں سے جو ان کے سب سے قریب تھا اس سے فرمایا تم دعا کراؤ۔ اس نے دعا کرائی، اس طرح ان سب سے ایک ایک سے دعا کروائی۔ چنانچہ سب نے دعا کرائی یہاں تک کہ میری باری آ گئی۔ میں آپؓ کے پہلو میں بیٹھا ہوا تھا۔ فرمایا اب تم دعا کراؤ تو میری زبان بند ہو گئی اور مجھ پر کپکپی طاری ہو گئی جس کا انہیں بھی اندازہ ہو گیا تو فرمایا تو کچھ نہیں تو اتنی ہی دعا کرا دو",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لَنَا ٱللَّهُمَّ ٱرْحَمْنَا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ہماری مغفرت فرما، اے ",""],["ٱللَّٰه","a"],["! ہم پر رحم فرما۔\" پھر حضرت عمرؓ نے دعا شروع کی تو ان لوگوں میں سب سے زیادہ آنسوؤں والا اور سب سے زیادہ رونے والا ان کے علاوہ کوئی نہیں تھا۔ پھر حضرت عمرؓ نے فرمایا اب آپ سب لوگ بھی خاموش ہو جائیں اور بکھر جائیں۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Sa'd (Vol.3 Pg.294)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" کہتے ہیں حضرت حبیب بن مسلمہ فہریؓ مستجاب الدعوات صحابی تھے، انہیں ایک لشکر کا امیر بنایا گیا۔ انہوں نے ملک روم جانے کے راستے تیار کرائے۔ جب دشمن کا سامنا ہوا تو انہوں نے لوگوں سے کہا میں نے حضورؐ کو فرماتے ہوئے سنا کہ جو جماعت ایک جگہ جمع ہو اور ان میں سے ایک دعا کرائے اور باقی سب آمین کہیں تو ",""],["ٱللَّٰه","a"],[" تعالیٰ ان کی دعا ضرور قبول فرمائیں گے۔ پھر حضرت حبیبؓ نے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی اور یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! ہمارے خون کی حفاظت فرما اور شہداء والا اجر ہمیں عطا فرما۔ ابھی دعا مانگی ہی تھی کہ اتنے میں دشمن کا سپہ سالار جسے رومی زبان میں بناط کہا جاتا ہے وہ آ گیا اور حضرت حبیبؓ کے پاس ان کے خیمے کے اندر چلا گیا گویا اس نے اپنی شکست مان لی۔ شہادت کی تمنا اور شہادت کی دعا کے باب میں حضرت معقل بن یسارؓ کی لمبی حدیث گزر چکی ہے جس میں یہ بھی ہے کہ حضرت نعمان بن مقرنؓ نے فرمایا کہ اب میں ",""],["ٱللَّٰه","a"],[" تعالیٰ سے دعا کروں گا، تم میں سے ہر آدمی اس پر ضرور آمین کہے، اس کی میری طرف سے پوری تاکید ہے۔ پھر یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! آج نعمان کو شہادت کی موت نصیب فرما اور مسلمانوں کی مدد فرما اور انہیں فتح نصیب فرما۔",""],[" (5)","s"],[" (6)","s"]]]],"f":[["(5)","Tabraani. Haythami (Vol.10 Pg.170) has commented on the chain of narrators."],["(6)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.216). Haakim (Vol.3 Pg.293) has reported a similar narration."]]},{"b":[["n",[["حضرت عقبہ بن عامرؓ","b"],[" فرماتے ہیں ایک صحابی کو ذوالبجادین کہا جاتا تھا ان کے بارے میں نبی کریمؐ نے فرمایا کہ یہ آہیں بھر کر رونے والا ہے اور یہ اس وجہ سے فرمایا کہ یہ صحابی بہت زیادہ تلاوت اور ",""],["ٱللَّٰه","a"],[" کا ذکر کرنے والے تھے اور اونچی آواز سے دعا کیا کرتے تھے۔",""],[" (7)","s"]]]],"f":[["(7)","Ahmad and Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.369). Ibn Jareer has reported a similar narration, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.395)."]]}]},"121":{"lead":[],"stories":[{"b":[["n",[["حضرت عمرؓ","b"],[" فرماتے ہیں میں نے نبی کریمؐ سے عمرہ کی اجازت مانگی۔ آپؐ نے اجازت مرحمت فرما دی اور فرمایا اے میرے چھوٹے بھائی! اپنی دعاؤں میں ہمیں نہ بھولنا۔ حضرت عمرؓ فرماتے ہیں حضورؐ نے یہ جو مجھے اپنا بھائی فرمایا یہ ایسا کلمہ ہے کہ اگر اس کے بدلے مجھے ساری دنیا بھی مل جائے تو مجھے ہرگز خوشی نہ ہو۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Dawood and Tirmidhi. Ibn Sa'd (Vol.3 Pg.273) has reported a similar narration."]]},{"b":[["n",[["حضرت ابوامامہ باہلیؓ","b"],[" فرماتے ہیں ایک مرتبہ نبی کریمؐ باہر تشریف لائے، آپؐ نے محسوس کیا کہ ہم چاہتے ہیں کہ آپؐ ہمارے لیے دعا فرمائیں تو آپؐ نے یہ دعا فرمائی",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لَنَا وَٱرْحَمْنَا وَٱرْضَ عَنَّا وَتَقَبَّلْ مِنَّا وَأَدْخِلْنَا ٱلْجَنَّةَ وَنَجِّنَا مِنَ ٱلنَّارِ وَأَصْلِحْ لَنَا شَأْنَنَا كُلَّهُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ہماری مغفرت فرما، ہم پر رحم فرما، ہم سے راضی ہو جا اور ہمارے اعمال قبول فرما، ہمیں جنت میں داخل فرما اور ہمیں آگ سے نجات نصیب فرما اور ہمارے تمام احوال کو درست فرما۔\" پھر آپؐ نے محسوس فرمایا کہ ہم چاہتے ہیں کہ آپؐ ہمارے لیے اور دعا فرمائیں تو آپؐ نے فرمایا ان دعاؤں میں میں نے تمہارے تمام کاموں کی دعا کر دی ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.291)."]]},{"b":[["n",[["حضرت طلحہ بن عبید","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں ایک آدمی ایک دن باہر نکل گیا اور کپڑے اتار کر گرم زمین پر لوٹ پوٹ ہونے لگا اور اپنے نفس سے کہنے لگا جہنم کی آگ کا مزہ چکھ لے، تو رات کو مردار پڑا رہتا ہے اور دن کو بیکار۔ اتنے میں اس نے دیکھا کہ نبی کریمؐ ایک درخت کے سایہ میں تشریف فرما ہیں، اس نے حضورؐ کی خدمت میں آ کر عرض کیا کہ میرا نفس مجھ پر غالب آ گیا۔ حضورؐ نے اس سے فرمایا غور سے سنو (تمہاری تواضع کی اور اپنے نفس کو سزا دینے کی کیفیت ",""],["ٱللَّٰه","a"],[" کو بہت پسند آئی ہے) اس وجہ سے تمہارے لیے آسمان کے دروازے کھول دیے گئے ہیں اور ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہاری وجہ سے فرشتوں پر فخر فرما رہے ہیں۔ پھر حضورؐ نے صحابہ سے فرمایا اپنے اس بھائی سے دعا کا توشہ لے لو (اس کی اس کیفیت کی وجہ سے اس کی دعا ",""],["ٱللَّٰه","a"],[" کے ہاں قبول ہو رہی ہے، اس سے دعا کرواؤ)۔ چنانچہ ایک آدمی نے کہا اے فلانے! میرے لیے دعا کر دو۔ حضورؐ نے اس سے فرمایا نہیں، صرف ایک کے لیے نہیں بلکہ سب کے لیے دعا کرو۔ اس نے یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! تقویٰ کو ان کا توشہ بنا دے اور تمام کاموں میں ان کی پوری رہبری فرما۔ اس دوران حضورؐ نے اس کے لیے یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! اسے صحیح دعا کرنے کی توفیق عطا فرما تو اس نے کہا اے ",""],["ٱللَّٰه","a"],["! جنت کو ان کا ٹھکانہ بنا دے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abi Dunya, as quoted in Kanzul Ummaal (Vol.1 Pg.290)."]]},{"b":[["n",[["حضرت بریدہؓ","b"],[" فرماتے ہیں حضورؐ ایک سفر میں جا رہے تھے کہ اتنے میں آپؐ کا گزر ایک آدمی پر ہوا جو گرم زمین پر لیٹ کر الٹ پلٹ ہو رہا تھا اور کہہ رہا تھا اے میرے نفس! رات بھر تو سوتا رہتا ہے اور دن کو بیکار رہتا ہے اور جنت کی امید رکھتا ہے۔ جب وہ اپنے نفس کی سزا پوری کر چکا تو حضورؐ نے ہماری طرف متوجہ ہو کر فرمایا اپنے اس بھائی کو پکڑ لو (یعنی اس سے دعا کراؤ)۔ ہم نے کہا ",""],["ٱللَّٰه","a"],[" آپ پر رحم فرمائے، آپ ہمارے لیے دعا کریں۔ اس پر اس نے یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! تمام کاموں میں ان کی پوری رہبری فرما۔ ہم نے کہا ہمارے لیے اور دعا کریں۔ اس نے کہا اے ",""],["ٱللَّٰه","a"],["! تقویٰ کو ان کا توشہ بنا دے۔ ہم نے کہا اور دعا کر دیں۔ حضورؐ نے بھی فرمایا ان کے لیے اور دعا کر دو اور حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اسے (جامع دعا کرنے کی) توفیق عطا فرما۔ چنانچہ اس نے کہا اے ",""],["ٱللَّٰه","a"],["! جنت کو ان کا ٹھکانہ بنا دے۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani. Haythami (Vol.10 Pg.185) has commented on the chain of narrators. Abu Nu'aym has reported a similar narration, as quoted in Kanzul Ummaal (Vol.1 Pg.308)."]]},{"b":[["n",[["حضرت اسیر بن جابرؒ","b"],[" کہتے ہیں حضرت عمرؓ نے حضرت اویسؒ سے فرمایا تم میرے لیے دعائے مغفرت کرو۔ حضرت اویسؒ نے کہا میں آپ کے لیے دعائے مغفرت کیسے کروں، آپ تو حضورؐ کے صحابی ہیں؟ فرمایا میں نے حضورؐ کو فرماتے ہوئے سنا ہے کہ تمام تابعین میں سب سے بہترین آدمی وہ ہے جسے اویس کہا جائے گا۔ مسلم کی روایت میں یہ بھی ہے کہ حضورؐ نے فرمایا لہٰذا تم میں سے جو بھی اویس سے ملے وہ ان سے کہے کہ وہ اس کے لیے استغفار کریں۔",""],[" (5)","s"],[" (6)","s"]]]],"f":[["(5)","Ibn Sa'd (Vol.6 Pg.163)."],["(6)","Muslim, as quoted in Isaabah (Vol.1 Pg.115)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" رومیؒ","b"],[" کہتے ہیں حضرت انس بن مالکؓ زاویہ بستی میں ٹھہرے ہوئے تھے، کسی نے ان سے کہا بصرہ سے آپ کے بھائی آپ کے پاس اس لیے آئے ہیں تاکہ آپ ان کے لیے دعا کریں تو انہوں نے یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! ہماری مغفرت فرما اور ہم پر رحم فرما اور ہمیں دنیا میں بھی بہتری عطا فرما اور آخرت میں بھی خیر و بھلائی عطا فرما اور ہمیں جہنم کی آگ کے عذاب سے بچا۔ ان لوگوں نے مزید دعا کی درخواست کی تو انہوں نے وہی دعا پھر کر دی اور فرمایا اگر تمہیں یہ چیزیں دے دی گئیں تو دنیا اور آخرت کی خیر تمہیں دے دی جائے گی۔",""],[" (7)","s"]]]],"f":[["(7)","Bukhaari in his Adab (Pg.93)."]]}]},"122":{"lead":[],"stories":[{"b":[["n",[["حضرت یزید بن اصمؒ","b"],[" کہتے ہیں شام کا ایک آدمی بہت طاقتور اور خوب لڑائی کرنے والا تھا، وہ حضرت عمرؓ کی خدمت میں آیا کرتا تھا۔ وہ کئی دن حضرت عمرؓ کو نظر نہ آیا تو فرمایا فلاں ابن فلاں کا کیا ہوا؟ لوگوں نے کہا اے امیر المومنین! اس نے شراب پینی شروع کر دی ہے اور مسلسل پی رہا ہے۔ حضرت عمرؓ نے اپنے منشی کو بلا کر فرمایا خط لکھو، یہ خط عمر بن خطاب کی طرف سے فلاں بن فلاں کے نام۔ سلام علیک! میں تمہارے سامنے اس ",""],["ٱللَّٰه","a"],[" کی تعریف کرتا ہوں جس کے سوا کوئی معبود نہیں، جو گناہوں کو معاف کرنے والا، توبہ کو قبول کرنے والا، سخت سزا دینے والا اور بڑا انعام و احسان کرنے والا ہے۔ اس کے سوا کوئی معبود نہیں، اسی کی طرف لوٹ کر جانا ہے۔ پھر حضرت عمرؓ نے اپنے ساتھیوں سے فرمایا تم لوگ اپنے بھائی کے لیے دعا کرو کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے دل کو اپنی طرف متوجہ فرما دے اور اسے توبہ کی توفیق عطا فرما دے۔ جب اس کے پاس حضرت عمرؓ کا خط پہنچا تو وہ اسے بار بار پڑھنے لگا اور کہنے لگا وہ گناہوں کو معاف کرنے والا، توبہ کو قبول کرنے والا اور سخت سزا دینے والا ہے (اس آیت میں) ",""],["ٱللَّٰه","a"],[" نے مجھے اپنی سزا سے ڈرایا ہے اور معاف کرنے کا وعدہ بھی فرمایا ہے۔ ابونعیم کی روایت میں مزید یہ بھی ہے کہ وہ اسے بار بار پڑھتا رہا پھر رونے لگ گیا، پھر اس نے شراب پینی چھوڑ دی اور مکمل طور سے چھوڑ دی۔ جب حضرت عمرؓ کو اس کی یہ خبر پہنچی تو فرمایا ایسے کیا کرو، جب تم دیکھو کہ تمہارا بھائی پھسل گیا ہے تو اسے راہ راست پر لاؤ اور اسے ",""],["ٱللَّٰه","a"],[" کی معافی کا یقین دلاؤ اور ",""],["ٱللَّٰه","a"],[" سے دعا کرو کہ اسے توبہ کی توفیق عطا فرمائے اور تم اس کے خلاف شیطان کے مددگار نہ بنو (اور اسے ",""],["ٱللَّٰه","a"],[" کی رحمت سے ناامید نہ کرو)۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Ibn Abi Haatim."],["(2)","Abu Nu'aym, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.70)."]]}]},"123":{"lead":[],"stories":[{"b":[["n",[["حضرت بریدہؓ","b"],[" فرماتے ہیں حضورؐ نے ایک آدمی کو یہ کہتے ہوئے سنا",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ أَنْتَ ٱللَّهُ لَا إِلَٰهَ إِلَّا أَنْتَ ٱلْأَحَدُ ٱلصَّمَدُ ٱلَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے اس وسیلہ سے مانگتا ہوں کہ میں اس بات کی گواہی دیتا ہوں کہ بیشک تو ہی ",""],["ٱللَّٰه","a"],[" ہے، تیرے سوا کوئی معبود نہیں، تو اکیلا ہے، بے نیاز ہے جس سے نہ کوئی پیدا ہوا اور نہ وہ کسی سے پیدا ہوا اور نہ کوئی اس کے برابر کا ہے۔\" آپؐ نے فرمایا تم نے ",""],["ٱللَّٰه","a"],[" کے اس اسم اعظم کے ساتھ مانگا ہے، جب بھی اس کے ساتھ مانگا جاتا ہے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ ضرور دیتے ہیں اور جب اس کے ساتھ اسے پکارا جاتا ہے تو وہ ضرور قبول کرتے ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Dawood, Tirmidhi, Ibn Maajah, Ibn Hibbaan and Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.145). Nasa'ee has reported a similar narration, as quoted in Nawawi's Adhkaar (Pg.501)."]]},{"b":[["n",[["حضرت معاذ بن جبلؓ","b"],[" فرماتے ہیں نبی کریمؐ نے ایک آدمی کو یہ کہتے ہوئے سنا",""]]],["q",[["يَا ذَا ٱلْجَلَالِ وَٱلْإِكْرَامِ","a"]]],["p",[["ترجمہ: \"اے بزرگی اور عزت والے!\" حضورؐ نے فرمایا تیرے لیے قبولیت کا دروازہ کھل گیا ہے، اب تو مانگ۔",""],[" (2)","s"]]]],"f":[["(2)","Tirmidhi, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.145)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں حضورؐ کا حضرت ابوعیاش زید بن صامت زرقیؓ کے پاس سے گزر ہوا، وہ نماز پڑھ رہے تھے اور یہ کہہ رہے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ ٱلْحَمْدَ لَا إِلَٰهَ إِلَّا أَنْتَ يَا حَنَّانُ يَا مَنَّانُ يَا بَدِيعَ ٱلسَّمَاوَاتِ وَٱلْأَرْضِ يَا ذَا ٱلْجَلَالِ وَٱلْإِكْرَامِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے اس وسیلہ سے مانگتا ہوں کہ تمام تعریفیں تیرے لیے ہیں، تیرے سوا کوئی معبود نہیں۔ اے بڑے مہربان! اے بہت دینے والے! اے آسمانوں اور زمین کو کسی نمونے کے بغیر بنانے والے! اے بزرگی اور بخشش والے!\" حضورؐ نے فرمایا تم نے ",""],["ٱللَّٰه","a"],[" سے اس کے اسم اعظم کے وسیلہ سے مانگا ہے کہ جب اس کے ذریعے سے دعا کی جائے تو ",""],["ٱللَّٰه","a"],[" ضرور قبول فرماتے ہیں اور جب اس کے وسیلہ سے مانگا جائے تو ضرور عطا فرماتے ہیں۔ ایک روایت میں یہ الفاظ بھی ہیں",""]]],["q",[["يَا حَيُّ يَا قَيُّومُ","a"]]],["p",[["ترجمہ: \"اے سدا زندہ رہنے والے! اے سب کو قائم رکھنے والے!\" حاکم کی روایت میں اس کے بعد یہ الفاظ بھی ہیں",""]]],["q",[["أَسْأَلُكَ ٱلْجَنَّةَ وَأَعُوذُ بِكَ مِنَ ٱلنَّارِ","a"]]],["p",[["ترجمہ: \"میں تجھ سے جنت مانگتا ہوں اور آگ سے تیری پناہ چاہتا ہوں۔\"",""],[" (3)","s"],[" (4)","s"],[" (5)","s"]]]],"f":[["(3)","Ahmad and Ibn Maajah."],["(4)","Abu Dawood, Nasa'ee, Haakim and Ibn Hibbaan."],["(5)","Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.146)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں حضورؐ ایک دیہاتی کے پاس سے گزرے، وہ اپنی نماز میں دعا مانگ رہا تھا اور یہ کہہ رہا تھا",""]]],["q",[["يَا مَنْ لَا تَرَاهُ ٱلْعُيُونُ وَلَا تُخَالِطُهُ ٱلظُّنُونُ وَلَا يَصِفُهُ ٱلْوَاصِفُونَ وَلَا تُغَيِّرُهُ ٱلْحَوَادِثُ وَلَا يَخْشَى ٱلدَّوَائِرَ يَعْلَمُ مَثَاقِيلَ ٱلْجِبَالِ وَمَكَايِيلَ ٱلْبِحَارِ وَعَدَدَ قَطْرِ ٱلْأَمْطَارِ وَعَدَدَ وَرَقِ ٱلْأَشْجَارِ وَعَدَدَ مَا أَظْلَمَ عَلَيْهِ ٱللَّيْلُ وَأَشْرَقَ عَلَيْهِ ٱلنَّهَارُ وَمَا تُوَارِي مِنْهُ سَمَاءٌ سَمَاءً وَلَا أَرْضٌ أَرْضًا وَلَا بَحْرٌ مَا فِي قَعْرِهِ وَلَا جَبَلٌ مَا فِي وَعْرِهِ، ٱجْعَلْ خَيْرَ عُمُرِي آخِرَهُ وَخَيْرَ عَمَلِي خَوَاتِيمَهُ وَخَيْرَ أَيَّامِي يَوْمَ أَلْقَاكَ فِيهِ","a"]]],["p",[["ترجمہ: \"اے وہ ذات جس کو آنکھیں نہیں دیکھ سکتیں اور کسی کا خیال و گمان اس تک نہیں پہنچ سکتا اور نہ اوصاف بیان کرنے والے اس کے اوصاف بیان کر سکتے ہیں اور نہ حوادث زمانہ اس پر اثر انداز ہو سکتے ہیں اور نہ اسے گردش زمانہ سے کوئی اندیشہ ہے، جو پہاڑوں کے وزن اور سمندروں کے پیمانے اور بارش کے قطروں کی تعداد اور درختوں کے پتوں کی تعداد کو جانتا ہے اور وہ ان تمام چیزوں کو جانتا ہے جن پر رات کی تاریکی چھائی ہے اور جن پر دن روشنی ڈالتا ہے اور نہ اس سے ایک آسمان دوسرے آسمان کو چھپا سکتا ہے اور نہ ایک زمین دوسری زمین کو اور نہ سمندر ان چیزوں کو چھپا سکتا ہے جو اس کی تہ میں ہیں اور نہ کوئی پہاڑ ان چیزوں کو چھپا سکتا ہے جو اس کی سخت چٹانوں میں ہیں۔ تو میری عمر کے آخری حصے کو سب سے بہترین حصہ بنا دے اور میرے آخری عمل کو سب سے بہترین عمل بنا دے اور میرا بہترین دن وہ بنا دے جس دن میری تجھ سے ملاقات ہو۔\" آپؐ نے ایک آدمی کے ذمہ لگایا کہ جب یہ دیہاتی نماز سے فارغ ہو جائے تو اسے میرے پاس لے آنا۔ چنانچہ وہ نماز کے بعد حضورؐ کی خدمت میں حاضر ہوا۔ حضورؐ کے پاس ایک کان سے کچھ سونا ہدیہ میں آیا ہوا تھا، حضورؐ نے اسے وہ سونا ہدیہ میں دیا پھر اس سے پوچھا کہ اے اعرابی! تم کونسے قبیلہ میں سے ہو؟ اس نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! بنی عامر بن صعصعہ قبیلہ میں سے ہوں۔ حضورؐ نے فرمایا کیا تم جانتے ہو میں نے تم کو یہ سونا کیوں ہدیہ کیا ہے؟ اس نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! ہماری رشتہ داری ہے اس وجہ سے کیا ہے۔ آپؐ نے فرمایا رشتہ داری کا بھی حق ہوتا ہے لیکن میں نے تمہیں سونا اس وجہ سے ہدیہ کیا ہے کہ تم نے بہت عمدہ طریقہ سے ",""],["ٱللَّٰه","a"],[" کی ثنا بیان کی ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.158)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں میں نے حضورؐ کو یہ دعا مانگتے ہوئے سنا",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ بِاسْمِكَ ٱلْمُبَارَكِ ٱلطَّيِّبِ ٱلطَّاهِرِ ٱلْأَحَبِّ إِلَيْكَ ٱلَّذِي إِذَا دُعِيتَ بِهِ أَجَبْتَ وَإِذَا سُئِلْتَ بِهِ أَعْطَيْتَ وَإِذَا ٱسْتُرْحِمْتَ بِهِ رَحِمْتَ وَإِذَا ٱسْتُفْرِجْتَ بِهِ فَرَّجْتَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے تیرے اس نام کے وسیلہ سے سوال کرتا ہوں جو پاک، عمدہ، مبارک اور تجھے سب سے زیادہ محبوب ہے، جب تجھے اس کے ذریعے پکارا جاتا ہے تو تو ضرور متوجہ ہوتا ہے اور جب تجھ سے اس کے وسیلہ سے مانگا جاتا ہے تو تو ضرور دیتا ہے اور جب تجھ سے اس کے ذریعہ رحم طلب کیا جاتا ہے تو تو ضرور رحم فرماتا ہے اور جب اس کے وسیلہ سے تجھ سے کشادگی مانگی جاتی ہے تو تو ضرور کشادگی دیتا ہے۔\"",""]]]],"f":[]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں ایک دن حضورؐ نے فرمایا اے عائشہ! کیا تمہیں پتہ چلا کہ ",""],["ٱللَّٰه","a"],[" نے مجھے وہ نام بتا دیا ہے کہ جب اس نام کے وسیلہ سے دعا کی جاتی ہے تو وہ ضرور قبول فرماتا ہے؟ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرے ماں باپ آپ پر قربان ہوں، وہ نام مجھے بھی سکھا دیں۔ آپؐ نے فرمایا اے عائشہ! تجھے سکھانا مناسب نہیں۔ وہ فرماتی ہیں میں ایک طرف ہو کر بیٹھ گئی، پھر میں کھڑی ہوئی اور حضورؐ کے سر کا بوسہ لیا، پھر میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مجھے وہ نام سکھا دیں۔ حضورؐ نے فرمایا اے عائشہ! تمہارے لیے مناسب نہیں کہ میں تمہیں سکھاؤں کیونکہ تمہارے لیے مناسب نہیں کہ تم اس کے ذریعہ دنیا کی کوئی چیز مانگو۔ میں وہاں سے اٹھی اور وضو کر کے دو رکعت نماز پڑھی پھر یہ دعا مانگی",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَدْعُوكَ ٱللَّهَ وَأَدْعُوكَ ٱلرَّحْمَٰنَ وَأَدْعُوكَ ٱلْبَرَّ ٱلرَّحِيمَ وَأَدْعُوكَ بِأَسْمَائِكَ ٱلْحُسْنَىٰ كُلِّهَا مَا عَلِمْتُ مِنْهَا وَمَا لَمْ أَعْلَمْ أَنْ تَغْفِرَ لِي وَتَرْحَمَنِي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھے ",""],["ٱللَّٰه","a"],[" کہہ کر پکارتی ہوں، تجھے رحمٰن کہہ کر پکارتی ہوں، تجھے نیکو کار رحیم کہہ کر پکارتی ہوں اور تجھے تیرے ان تمام اچھے ناموں سے پکارتی ہوں جن کو میں جانتی ہوں اور جن کو میں نہیں جانتی ہوں اور یہ سوال کرتی ہوں کہ تو میری مغفرت فرما دے اور مجھ پر رحم فرما دے۔\" حضرت عائشہؓ فرماتی ہیں حضورؐ میری یہ دعا سن کر بہت ہنسے اور فرمایا تم نے جن ناموں سے ",""],["ٱللَّٰه","a"],[" کو پکارا ہے ان میں وہ خاص نام بھی شامل ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Maajah (Pg.698)."]]},{"b":[["n",[["حضرت سلمہ بن اکوع اسلمیؓ","b"],[" فرماتے ہیں میں نے حضورؐ کو کبھی ایسی دعا مانگتے ہوئے نہیں سنا کہ جس کے شروع میں آپؐ نے یہ الفاظ نہ کہے ہوں",""]]],["q",[["سُبْحَانَ رَبِّيَ ٱلْعَلِيِّ ٱلْأَعْلَىٰ ٱلْوَهَّابِ","a"]]],["p",[["ترجمہ: \"میں اپنے رب کی پاکی بیان کرتا ہوں جو کہ بلند، بہت بلند اور بہت دینے والا ہے۔\"",""],[" (8)","s"]]]],"f":[["(8)","Ahmad and Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.156). Ibn Abi Shaybah has reported a similar narration, as quoted in Kanzul Ummaal (Vol.1 Pg.290)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں اگر حضورؐ سو دعائیں بھی مانگتے تو ان کے شروع میں، درمیان میں اور آخر میں یہ دعا ضرور مانگتے",""]]],["q",[["رَبَّنَا آتِنَا فِي ٱلدُّنْيَا حَسَنَةً وَفِي ٱلْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ ٱلنَّارِ","a"]]],["p",[["ترجمہ: \"اے ہمارے پروردگار! ہم کو دنیا میں بھی بہتری عنایت کیجئے اور آخرت میں بھی بہتری دیجئے اور ہم کو عذاب دوزخ سے بچائیے۔\"",""],[" (9)","s"]]]],"f":[["(9)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.1 Pg.290)."]]},{"b":[["n",[["حضرت فضالہ بن عبیدؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ تشریف فرما تھے، اتنے میں ایک آدمی نے اندر آ کر نماز پڑھی اور پھر اس نے یہ دعا مانگی",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لِي وَٱرْحَمْنِي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میری مغفرت فرما اور مجھ پر رحم فرما۔\" حضورؐ نے فرمایا اے نمازی! تم نے دعا مانگنے میں جلدی کی۔ جب تم نماز پڑھ کر بیٹھ جاؤ تو پہلے ",""],["ٱللَّٰه","a"],[" کی شایان شان تعریف کرو اور مجھ پر درود بھیجو پھر دعا مانگو۔ پھر ایک اور آدمی نے نماز پڑھی پھر اس نے ",""],["ٱللَّٰه","a"],[" کی حمد و ثنا بیان کی اور نبی کریمؐ پر درود بھیجا تو حضورؐ نے اس سے فرمایا اے نمازی! اب دعا کر، ضرور قبول کی جائے گی۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Dawood, Tirmidhi, Nasa'ee, Ibn Hibbaan and Ibn Khuzaymah, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.147). Tabraani has reported a similar narration, as quoted in Majma'uz Zawaa'id (Vol.10 Pg.155)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" نے فرمایا جب تم میں سے کوئی ",""],["ٱللَّٰه","a"],[" سے مانگنا چاہے تو اسے چاہیے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ کی شایان شان حمد و ثنا سے ابتداء کرے، پھر نبی کریمؐ پر درود پڑھے، پھر ",""],["ٱللَّٰه","a"],[" سے مانگے تو اس طرح مقصد میں کامیابی کی زیادہ امید ہے۔",""],[" (11)","s"]]]],"f":[["(11)","Tabraani. Haythami (Vol.10 Pg.155) has commented on the chain of narrators."]]}]},"124":{"lead":[],"stories":[{"b":[["n",[["حضرت عباس بن مرداسؓ","b"],[" فرماتے ہیں نبی کریمؐ نے عرفات (یعنی حج کے دن نو ذی الحجہ) کی شام کو اپنی امت کے لیے مغفرت اور رحمت کی دعا مانگی اور بہت دیر تک یہ دعا مانگتے رہے۔ آخر ",""],["ٱللَّٰه","a"],[" نے وحی بھیجی کہ میں نے تمہاری دعا منظور کر لی اور ان کے جن گناہوں کا تعلق مجھ سے تھا وہ میں نے معاف کر دیے لیکن انہوں نے ایک دوسرے پر جو ظلم کر رکھا ہے اس کی معافی نہیں ہو سکتی۔ اس پر حضورؐ نے غایت شفقت کی وجہ سے عرض کیا اے رب! تو یہ کر سکتا ہے کہ مظلوم کو اس ظلم سے بہتر بدلہ اپنے پاس سے دے دے اور ظالم کو معاف فرما دے۔ اس شام کو تو ",""],["ٱللَّٰه","a"],[" نے یہ دعا قبول نہ فرمائی البتہ مزدلفہ کی صبح کو حضورؐ نے یہ دعا پھر مانگنی شروع کی تو ",""],["ٱللَّٰه","a"],[" نے قبول فرما لی اور فرمایا چلو ظالموں کو بھی معاف کر دیا۔ اس پر حضورؐ مسکرانے لگے تو بعض صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! (تہجد کا وقت ہے) آپ اس وقت تو مسکرایا نہیں کرتے تھے، کیوں مسکرا رہے ہیں؟ فرمایا میں اس وجہ سے مسکرا رہا ہوں کہ جب ",""],["ٱللَّٰه","a"],[" کے دشمن ابلیس کو پتہ چلا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ظالم امتیوں کے بارے میں بھی میری یہ دعا قبول کر لی ہے تو وہ ہلاکت اور بربادی پکارنے لگا اور سر پر مٹی ڈالنے لگا (اسے دیکھ کر میں مسکرا رہا تھا)۔",""],[" (1)","s"]]]],"f":[["(1)","Bayhaqi."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں حضورؐ نے حضرت ابراہیمؑ کے اس قول کی تلاوت فرمائی",""]]],["q",[["رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِّنَ ٱلنَّاسِ فَمَن تَبِعَنِي فَإِنَّهُۥ مِنِّي وَمَنْ عَصَانِي فَإِنَّكَ غَفُورٌ رَّحِيمٌ","a"]]],["p",[["ترجمہ: \"اے میرے پروردگار! ان بتوں نے بہتیرے آدمیوں کو گمراہ کر دیا، پھر جو شخص میری راہ پر چلے گا وہ تو میرا ہے اور جو شخص (اس باب میں) میرا کہنا نہ مانے تو آپ تو کثیر المغفرت اور کثیر الرحمت ہیں۔\" (سورت ابراہیم آیت ۳۶) اور حضرت عیسیٰ علیہ السلام کے اس قول کی تلاوت فرمائی",""]]],["q",[["إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ","a"]]],["p",[["ترجمہ: \"اگر آپ ان کو سزا دیں تو یہ آپ کے بندے ہیں اور اگر آپ ان کو معاف فرما دیں تو آپ زبردست ہیں، حکمت والے ہیں۔\" (سورت مائدہ آیت ۱۱۸) پھر آپؐ نے دونوں ہاتھ اٹھا کر امت کے لیے یہ دعا شروع کر دی اے ",""],["ٱللَّٰه","a"],["! میری امت، اے ",""],["ٱللَّٰه","a"],["! میری امت، اے ",""],["ٱللَّٰه","a"],["! میری امت، اور آپؐ رونے لگے۔ اس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ارشاد فرمایا اے جبرئیل! تمہارا رب سب کچھ اچھی طرح جانتا ہے لیکن تم محمدؐ کے پاس جاؤ اور ان سے پوچھو کہ وہ کیوں رو رہے ہیں؟ چنانچہ حضرت جبرئیلؑ نے حاضر ہو کر پوچھا، حضورؐ نے رونے کی وجہ بتائی (کہ امت کے غم میں رو رہا ہوں)۔ حضرت جبرئیلؑ نے واپس آ کر ",""],["ٱللَّٰه","a"],[" کو وجہ بتائی۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا محمدؐ کے پاس جاؤ اور ان سے کہو ہم تم کو تمہاری امت کے بارے میں راضی کریں گے اور تمہیں رنجیدہ اور غمگین نہ ہونے دیں گے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Wahab, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.540)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں حضورؐ نے اپنی امت کے لیے یہ دعا مانگی",""]]],["q",[["ٱللَّهُمَّ أَقْبِلْ بِقُلُوبِهِمْ عَلَىٰ طَاعَتِكَ وَحُطْ مِنْ وَرَائِهِمْ بِرَحْمَتِكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ان کے دلوں کو اپنی اطاعت کی طرف متوجہ فرما اور ان کے پیچھے سے اپنی رحمت سے ان کی حفاظت فرما۔\"",""],[" (3)","s"]]]],"f":[["(3)","Tabraani. Haythami (Vol.10 Pg.69) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں ایک دن میں نے دیکھا کہ حضورؐ بہت خوش ہیں۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرے لیے ",""],["ٱللَّٰه","a"],[" سے دعا فرما دیں۔ آپؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! عائشہ کے اگلے پچھلے تمام گناہ معاف فرما اور جو اس نے چھپ کر کیے اور علی الاعلان کیے وہ بھی سب معاف فرما۔ اس دعا سے خوش ہو کر میں خوشی کے مارے لوٹ پوٹ ہو گئی جس سے میرا سر میری گود میں چلا گیا۔ حضورؐ نے فرمایا کیا تمہیں میری دعا سے بہت خوشی ہو رہی ہے؟ میں نے کہا مجھے آپ کی دعا سے خوشی کیوں نہ ہو؟ آپؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! یہ دعا تو میں اپنی امت کے لیے ہر نماز میں مانگتا ہوں۔",""],[" (4)","s"]]]],"f":[["(4)","Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.244)."]]}]},"125":{"lead":[],"stories":[{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں حضورؐ نے یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! ابوبکرؓ کو قیامت کے دن میرے ساتھ میرے درجہ میں رکھنا۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilya, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.345)."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" اور ",""],["حضرت خبابؓ","b"],[" فرماتے ہیں کہ حضورؐ نے یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! عمر بن خطاب اور ابوجہل بن ہشام میں سے جو تجھے زیادہ محبوب ہے اس کے ذریعہ اسلام کو عزت عطا فرما۔",""],[" (2)","s"]]]],"f":[["(2)","Nasa'ee. Ahmad, Tirmidhi, Ibn Sa'd and others have reported a similar narration from Hadhrat Umar."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ نے یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! اسلام کو خاص طور سے عمر بن خطاب کے ذریعہ عزت عطا فرما۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Maajah, Haakim and Bayhaqi."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں حضورؐ نے یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! اسلام کو عمر کے ذریعہ قوت عطا فرما۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani and Ahmad, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.370)."]]},{"b":[["n",[["حضرت زید بن اسلمؓ","b"],[" فرماتے ہیں حضرت عثمانؓ نے ایک بھورے رنگ کی اونٹنی حضورؐ کی خدمت میں بھیجی، حضورؐ نے ان کے لیے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! انہیں پل صراط (آسانی سے اور جلدی سے) پار کرا دینا۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Asaakir."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" اور ",""],["حضرت ابوسعیدؓ","b"],[" فرماتے ہیں حضورؐ نے یہ دعا تین مرتبہ فرمائی اے ",""],["ٱللَّٰه","a"],["! میں عثمانؓ سے راضی ہوں تو بھی ان سے راضی ہو جا۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym. Ibn Asaakir has also reported it from Hadhrat Aa'isha and Hadhrat Abu Sa'eed."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! عثمانؓ کے اگلے پچھلے گناہ اور جو گناہ چھپ کر کیے اور جو علی الاعلان کیے اور جو پوشیدہ طور سے کیے اور جو سب کے سامنے کیے سارے معاف فرما۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani, Abu Nu'aym in his Hilya and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.6)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں ایک دفعہ میں بیمار ہوا، میں نبی کریمؐ کی خدمت میں حاضر ہوا۔ آپؐ نے مجھے اپنی جگہ بٹھایا اور خود کھڑے ہو کر نماز شروع فرما دی اور اپنے کپڑے کا ایک کنارہ مجھ پر ڈال دیا، پھر نماز کے بعد فرمایا اے ابن ابی طالب! اب تم ٹھیک ہو گئے ہو، کوئی فکر نہ کرو، میں نے جو چیز ",""],["ٱللَّٰه","a"],[" سے اپنے لیے مانگی اس جیسی میں نے تمہارے لیے بھی مانگی اور میں نے جو چیز بھی ",""],["ٱللَّٰه","a"],[" سے مانگی وہ ",""],["ٱللَّٰه","a"],[" نے مجھے ضرور دے دی، بس اتنی بات ہے کہ مجھ سے یوں کہا گیا کہ آپ کے بعد کوئی نبی نہیں ہوگا۔ چنانچہ میں وہاں سے اٹھا تو میں بالکل ٹھیک ہو چکا تھا اور ایسے لگ رہا تھا کہ جیسے میں بیمار ہی نہیں ہوا تھا۔",""]]]],"f":[]},{"b":[["n",[["حضرت زید بن یثیعؒ","b"],["، ",""],["حضرت سعید بن وہبؒ","b"],[" اور ",""],["حضرت عمرو بن ذی مرؒ","b"],[" کہتے ہیں ہم نے حضرت علیؓ کو فرماتے ہوئے سنا کہ میں ہر اس آدمی کو ",""],["ٱللَّٰه","a"],[" کا واسطہ دے کر کہتا ہوں جس نے حضورؐ کو (حجۃ الوداع سے واپسی پر) غدیر خم کے دن کچھ فرماتے ہوئے سنا ہے کہ وہ ضرور کھڑا ہو جائے۔ چنانچہ تیرہ آدمی کھڑے ہو گئے اور انہوں نے اس بات کی گواہی دی کہ اس دن حضورؐ نے فرمایا کیا میں مومنوں کے ساتھ خود ان کی جان سے بھی زیادہ تعلق نہیں رکھتا؟ صحابہؓ نے عرض کیا بالکل رکھتے ہیں یا رسول ",""],["ٱللَّٰه","a"],["! پھر حضورؐ نے حضرت علیؓ کا ہاتھ پکڑ کر فرمایا میں جس کا دوست ہوں یہ (حضرت علیؓ) اس کے دوست ہیں۔ اے ",""],["ٱللَّٰه","a"],["! جو ان سے دوستی کرے تو اس سے دوستی کر اور جو ان سے دشمنی کرے تو اس سے دشمنی کر اور جو ان سے محبت کرے تو ان سے محبت کر اور جو ان سے بغض رکھے تو ان سے بغض رکھ اور جو ان کی مدد کرے تو اس کی مدد کر اور جو ان کی مدد چھوڑے تو اس کی مدد چھوڑ دے۔",""],[" (8)","s"],[" (9)","s"]]]],"f":[["(8)","Ibn Abi Aasim, Ibn Jareer (who authenticated it), Tabraani and Ibn Shaaheen in his Sunnah, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.43)."],["(9)","Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.105)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" نے حضورؐ سے حضرت علیؓ کے لیے یہ دعا نقل کی ہے اے ",""],["ٱللَّٰه","a"],["! علیؓ کی اعانت فرما اور ان کے ذریعہ سے اعانت فرما اور ان پر رحم فرما اور ان کے ذریعہ سے دوسروں پر رحم فرما اور ان کی مدد فرما اور ان کے ذریعہ سے مدد فرما۔ اے ",""],["ٱللَّٰه","a"],["! جو ان سے دوستی کرے تو اس سے دوستی کر اور جو ان سے دشمنی کرے تو اس سے دشمنی کر۔",""],[" (10)","s"]]]],"f":[["(10)","Tabraani, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.32)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں حضورؐ نے میرے لیے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اس کی زبان کو (حق پر) جما دے اور اس کے دل کو ہدایت نصیب فرما۔ حضرت ابن عباسؓ سے یہ الفاظ منقول ہیں اے ",""],["ٱللَّٰه","a"],["! اس کو فیصلہ کرنے کا صحیح راستہ دکھلا۔",""],[" (11)","s"],[" (12)","s"]]]],"f":[["(11)","Haakim."],["(12)","Haakim, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.35)."]]}]},"126":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوبکرؓ","b"],[" فرماتے ہیں میں نے حضورؐ کو حضرت سعدؓ کے لیے یہ دعا کرتے ہوئے سنا اے ",""],["ٱللَّٰه","a"],["! اس کے تیر کو سیدھا نشانہ پر لگا اور اس کی دعا کو قبول فرما اور اسے اپنا محبوب بنا لے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Asaakir and Ibn Najjaar."]]},{"b":[["n",[["حضرت سعدؓ","b"],[" فرماتے ہیں حضورؐ نے میرے لیے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! جب سعد تجھ سے دعا کرے تو اس کی دعا قبول فرما۔",""],[" (2)","s"]]]],"f":[["(2)","Tirmidhi, Ibn Hibbaan and Haakim, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.70)."]]},{"b":[["n",[["حضرت زبیر بن عوامؓ","b"],[" فرماتے ہیں حضورؐ نے میرے لیے اور میری اولاد کے لیے دعا فرمائی۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Ya'la and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.70)."]]}]},"127":{"lead":[],"stories":[{"b":[["n",[["حضورؐ کی زوجہ محترمہ ",""],["حضرت ام سلمہؓ","b"],[" فرماتی ہیں حضورؐ نے حضرت فاطمہؓ سے فرمایا اپنے خاوند اور دونوں بیٹوں کو میرے پاس لے آؤ۔ چنانچہ وہ ان تینوں کو لے آئیں تو آپؐ نے خیبر والی چادر جو ہمیں خیبر میں ملی تھی اور میں اپنے نیچے بچھاتی تھی ان پر ڈالی اور پھر ان کے لیے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! یہ محمدؐ (علیہ السلام) کی آل ہے، تو محمدؐ کی آل پر اپنی رحمتیں اور برکتیں ایسے نازل فرما جیسے تو نے حضرت ابراہیم علیہ السلام کی آل پر نازل فرمائی تھیں۔ بے شک تو بہت تعریف والا اور بزرگی والا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Ya'la. Haythami (Vol.9 Pg.166) has commented on the chain of narrators. Tirmidhi has reported a similar narration."]]},{"b":[["n",[["حضرت ابوعمارؒ","b"],[" کہتے ہیں میں حضرت واثلہ بن اسقعؓ کے پاس بیٹھا ہوا تھا کہ اتنے میں کچھ لوگوں نے حضرت علیؓ کا تذکرہ کیا اور انہیں کچھ برا بھلا کہہ دیا۔ جب وہ لوگ کھڑے ہو کر چلے گئے تو مجھ سے فرمایا تم ذرا بیٹھے رہو، میں اس ہستی کے بارے میں بتاتا ہوں جسے انہوں نے برا بھلا کہا ہے۔ ایک دن میں حضورؐ کے پاس بیٹھا ہوا تھا کہ اتنے میں حضرت علیؓ، حضرت فاطمہؓ، حضرت حسنؓ، حضرت حسینؓ آئے۔ آپؐ نے ان پر اپنی پرانی چادر ڈال کر یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! یہ میرے گھر والے ہیں، ان سے ناپاکی کو دور کر اور انہیں اچھی طرح پاک فرما۔ میں نے عرض کیا میں بھی؟ حضورؐ نے فرمایا تم بھی۔ حضرت واثلہؓ فرماتے ہیں ",""],["ٱللَّٰه","a"],[" کی قسم! میرے دل کو حضورؐ کے اس فرمان پر تمام اعمال سے زیادہ اعتماد ہے۔ اور ایک روایت میں یہ ہے مجھے حضورؐ کے اس فرمان سے سب سے زیادہ امید ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani. Haythami (Vol.9 Pg.167) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں میں نبی کریمؐ کی خدمت میں حاضر ہوا، حضورؐ نے ایک چادر بچھا رکھی تھی، اس پر حضورؐ، میں، حضرت فاطمہؓ، حضرت حسنؓ اور حضرت حسینؓ سب بیٹھ گئے۔ پھر حضورؐ نے چادر کے چاروں کونے پکڑ کر ہم پر گرہ لگا دی، پھر یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! جیسے میں ان سے راضی ہوں تو بھی ان سے راضی ہو جا۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.169)."]]}]},"128":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" ابن مسعودؓ","b"],[" فرماتے ہیں حضورؐ نے حضرت حسنؓ اور حضرت حسینؓ کے لیے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! میں ان دونوں سے محبت کرتا ہوں تو بھی ان سے محبت فرما اور جس نے ان دونوں سے محبت کی اس نے حقیقت میں مجھ سے محبت کی۔",""],[" (1)","s"]]]],"f":[["(1)","Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.180)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" سے اس دعا کے یہ الفاظ منقول ہیں اے ",""],["ٱللَّٰه","a"],["! میں ان دونوں سے محبت کرتا ہوں تو بھی ان دونوں سے محبت فرما۔ نسائی اور ابن حبان میں یہ دعا حضرت اسامہؓ سے منقول ہے، اس کے آخر میں یہ ہے کہ جو ان دونوں سے محبت کرے تو اس سے بھی محبت فرما اور اس کے شروع میں یہ ہے کہ یہ دونوں میرے بیٹے ہیں اور میری بیٹی کے بیٹے ہیں۔ ابن ابی شیبہ اور طیالسی میں یہ دعا حضرت ابوہریرہؓ سے منقول ہے، اس میں مزید یہ بھی ہے کہ جو ان سے بغض رکھے تو اس سے بغض رکھ۔",""],[" (2)","s"],[" (3)","s"],[" (4)","s"]]]],"f":[["(2)","Bazzaar."],["(3)","Nasa'ee and Ibn Hibbaan, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.105)."],["(4)","Ibn Abi Shaybah and Tayaalisi, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.106)."]]},{"b":[["n",[["بخاری و مسلم وغیرہ میں ",""],["حضرت ابوہریرہؓ","b"],[" سے اور طبرانی میں ",""],["حضرت سعید بن زیدؓ","b"],[" اور ",""],["حضرت عائشہؓ","b"],[" سے منقول ہے کہ حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! مجھے حسن سے محبت ہے تو بھی اس سے محبت فرما اور جو اس سے محبت کرے اس سے بھی محبت فرما۔ ابن عساکر میں ",""],["حضرت محمد بن سیرینؒ","b"],[" سے یہ بھی منقول ہے کہ اے ",""],["ٱللَّٰه","a"],["! اسے بچا اور اس کے ذریعہ (دوسروں کو) بچا۔",""],[" (5)","s"],[" (6)","s"]]]],"f":[["(5)","Bukhaari, Muslim and others, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.106)."],["(6)","Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.106)."]]},{"b":[["n",[["حضرت براءؓ","b"],[" فرماتے ہیں کہ میں نے دیکھا کہ نبی کریمؐ نے حضرت حسینؓ کو کندھے پر اٹھا رکھا ہے اور یہ دعا فرما رہے ہیں اے ",""],["ٱللَّٰه","a"],["! مجھے اس سے محبت ہے تو بھی اس سے محبت فرما۔",""],[" (7)","s"]]]],"f":[["(7)","Bukhaari, Muslim, Tirmidhi, Ibn Maajah and Nasa'ee, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.105)."]]}]},"129":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! عباس کی اور اس کی اولاد کی ظاہری باطنی ہر طرح کی مغفرت فرما اور ان کی اولاد میں تو ان کا خلیفہ بن جا۔",""],[" (1)","s"]]]],"f":[["(1)","Tirmidhi and Abu Ya'la."]]},{"b":[["n",[["ابن عساکر میں ",""],["حضرت ابوہریرہؓ","b"],[" کی یہ روایت ہے کہ حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! عباس کے وہ گناہ جو چھپ کر کیے یا علی الاعلان کیے یا سب کے سامنے کیے یا پردے میں کیے سب معاف فرما اور آئندہ ان سے یا ان کی اولاد سے قیامت تک جو گناہ ہوں وہ سب معاف فرما۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Asaakir."]]},{"b":[["n",[["ابن عساکر اور خطیب میں ",""],["حضرت ابوہریرہؓ","b"],[" کی یہ روایت ہے کہ حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! عباس کی، عباس کی اولاد کی اور جو ان سے محبت کرے اس کی مغفرت فرما۔",""]]]],"f":[]},{"b":[["n",[["ابن عساکر میں ",""],["حضرت عاصمؒ","b"],[" کے والد رحمۃ ",""],["ٱللَّٰه","a"],[" علیہ کی روایت ہے کہ حضورؐ نے فرمایا کہ عباس میرے چچا اور میرے والد جیسے ہیں اور میرے آباء و اجداد میں سے اب یہی باقی ہیں۔ اے ",""],["ٱللَّٰه","a"],["! ان کے گناہوں کو معاف فرما اور ان کے اچھے عملوں کو قبول فرما اور برے عملوں سے درگزر فرما اور ان کے فائدے کے لیے ان کی اولاد کی اصلاح فرما۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.207)."]]},{"b":[["n",[["حضرت ابواسید ساعدیؓ","b"],[" فرماتے ہیں حضورؐ نے حضرت عباس بن عبدالمطلبؓ سے فرمایا جب تک کل آپ کے گھر نہ آ جاؤں اس وقت تک آپ اور آپ کے بیٹے گھر سے کہیں نہ جائیں، مجھے آپ لوگوں سے ایک کام ہے۔ چنانچہ اگلے دن یہ سب لوگ گھر میں حضورؐ کا انتظار کرتے رہے۔ آپؐ چاشت کے بعد ان کے پاس تشریف لائے اور فرمایا السلام علیکم۔ جواب میں ان حضرات نے کہا و علیکم السلام و رحمۃ ",""],["ٱللَّٰه","a"],[" و برکاتہ۔ پھر حضورؐ نے فرمایا آپ لوگوں نے کس حال میں صبح کی؟ ان لوگوں نے کہا ہم ",""],["ٱللَّٰه","a"],[" کی تعریف کرتے ہیں (اچھے حال میں صبح کی)۔ آپؐ نے فرمایا آپ لوگ سمٹ جائیں اور مل کر بیٹھیں۔ چنانچہ جب وہ اس طرح بیٹھ گئے تو آپؐ نے ان سب پر اپنی پرانی ایک چادر ڈال دی، پھر یہ دعا فرمائی اے میرے رب! یہ میرے چچا اور میرے والد جیسے ہیں اور یہ سب میرے گھر والے ہیں، لہٰذا جیسے میں نے ان کو اپنی اس چادر میں چھپا رکھا ہے تو بھی ان کو ایسے ہی آگ سے چھپا لے۔ اس پر دروازے کی چوکھٹ اور کمرے کی دیواروں نے تین دفعہ آمین کہا۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.270). Bayhaqi and Ibn Maajah have reported a similar narration, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.133). Abu Nu'aym has reported a similar narration in his Dalaa'il (Pg.154)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں میں (اپنی خالہ) حضرت میمونہؓ کے گھر میں تھا، میں نے حضورؐ کے لیے وضو کا پانی رکھا، آپؐ نے پوچھا یہ پانی میرے لیے کس نے رکھا؟ حضرت میمونہؓ نے عرض کیا عبد",""],["ٱللَّٰه","a"],[" نے۔ آپؐ نے خوش ہو کر فرمایا اے ",""],["ٱللَّٰه","a"],["! اسے دین کی سمجھ عطا فرما اور اسے قرآن کی تفسیر سکھا دے۔ ابن نجار میں حضرت ابن عباسؓ سے یہ دعا اس طرح منقول ہے اے ",""],["ٱللَّٰه","a"],["! اسے کتاب سکھا دے اور اسے دین کی سمجھ عطا فرما دے۔ ابن ماجہ، ابن سعد اور طبرانی میں حضرت ابن عباسؓ سے یہ دعا اس طرح منقول ہے اے ",""],["ٱللَّٰه","a"],["! اسے حکمت اور کتاب کی تفسیر سکھا دے۔",""],[" (5)","s"],[" (6)","s"],[" (7)","s"]]]],"f":[["(5)","Ibn Abi Shaybah."],["(6)","Ibn Najjaar, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.231)."],["(7)","Ibn Maajah, Ibn Sa'd and Tabraani."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" سے یہ دعا اس طرح منقول ہے اے ",""],["ٱللَّٰه","a"],["! اس میں برکت عطا فرما، اس کے ذریعہ کتاب کو پھیلا۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Hilya, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.228)."]]}]},"130":{"lead":[],"stories":[{"b":[["n",[["طبرانی اور ابن عساکر میں ",""],["حضرت ابن عباسؓ","b"],[" سے اور احمد و ابن عساکر میں ",""],["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن جعفرؓ","b"],[" سے روایت ہے کہ حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! جعفر کی اولاد میں تو اس کا خلیفہ بن جا۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad and Ibn Asaakir. Tabraani and Ibn Asaakir have also reported the narration from Hadhrat Abdullaah bin Abbaas."]]},{"b":[["n",[["طیالسی، ابن سعد اور احمد وغیرہ میں ",""],["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن جعفرؓ","b"],[" سے روایت ہے کہ حضورؐ نے تین مرتبہ یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! تو جعفر کے اہل و عیال میں اس کا خلیفہ بن جا اور (ان کے بیٹے) عبد",""],["ٱللَّٰه","a"],[" کی خرید و فروخت میں برکت عطا فرما۔",""],[" (2)","s"]]]],"f":[["(2)","Tayaalisi, Ibn Sa'd, Ahmad and others."]]},{"b":[["n",[["ابن ابی شیبہ میں ",""],["حضرت شعبیؒ","b"],[" سے منقول ہے بلقاء علاقہ کے غزوہ موتہ میں حضرت جعفر بن ابی طالبؓ جب شہید ہو گئے تو حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اب تک تو اپنے جتنے نیک بندوں کا خلیفہ بنا ہے ان سب سے زیادہ اچھی طرح تو جعفر کے اہل و عیال میں اس کا خلیفہ بن جا۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abi Shaybah, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.155). Ibn Sa'd (Vol.4 Pg.39) has reported a similar narration."]]},{"b":[["n",[["حضرت ابومیسرہؒ","b"],[" کہتے ہیں جب حضرت زید بن حارثہؓ، حضرت جعفرؓ اور حضرت ابن رواحہؓ کی شہادت کی خبر پہنچی تو حضورؐ نے کھڑے ہو کر ان تینوں کے حالات بیان کیے اور ابتداء حضرت زیدؓ سے فرمائی، پھر یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! زید کی مغفرت فرما، اے ",""],["ٱللَّٰه","a"],["! زید کی مغفرت فرما، اے ",""],["ٱللَّٰه","a"],["! جعفر اور عبد",""],["ٱللَّٰه","a"],[" بن رواحہ کی مغفرت فرما۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Sa'd (Vol.3 Pg.46)."]]}]},"131":{"lead":[],"stories":[{"b":[["n",[["احمد اور ابن سعد میں ",""],["حضرت عثمان بن عفانؓ","b"],[" کی روایت ہے کہ حضورؐ نے دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! تو آل یاسر کی مغفرت فرما اور تو نے ان کی مغفرت فرما دی ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad and Ibn Sa'd."]]},{"b":[["n",[["ابن عساکر میں ",""],["حضرت عائشہؓ","b"],[" کی روایت ہے کہ حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! عمار میں برکت عطا فرما۔ آگے باقی حدیث ذکر کی ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.235)."]]},{"b":[["n",[["حضرت ام سلمہؓ","b"],[" فرماتی ہیں حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! ابوسلمہ کی مغفرت فرما اور مقربین میں ان کے درجے کو بلند فرما اور ان کے پیچھے رہ جانے والوں میں تو ان کا خلیفہ بن جا اور اے رب العالمین! ہماری اور ان کی مغفرت فرما اور ان کی قبر کو کشادہ اور منور فرما۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad, Muslim and Abu Dawood, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.219)."]]},{"b":[["n",[["حضرت اسامہ بن زیدؓ","b"],[" فرماتے ہیں حضورؐ مجھے پکڑ کر اپنی ران پر بٹھا لیا کرتے تھے اور حضرت حسن بن علیؓ کو بائیں ران پر بٹھا لیا کرتے، پھر ہم دونوں کو اپنے ساتھ چمٹا کر یوں فرماتے اے ",""],["ٱللَّٰه","a"],["! میں ان دونوں پر رحم کرتا ہوں تو بھی ان دونوں پر رحم فرما۔ ایک روایت میں یہ ہے کہ اے ",""],["ٱللَّٰه","a"],["! مجھے ان دونوں سے محبت ہے تو بھی ان دونوں سے محبت فرما۔",""],[" (4)","s"],[" (5)","s"]]]],"f":[["(4)","Ahmad, Abu Ya'la, Nasa'ee and Ibn Hibbaan."],["(5)","Ibn Sa'd (Vol.4 Pg.62)."]]},{"b":[["n",[["حضرت اسامہ بن زیدؓ","b"],[" فرماتے ہیں (میں لشکر کی تیاری کے لیے مدینہ سے باہر جرف میں ٹھہرا ہوا تھا) جب حضورؐ کی بیماری بڑھ گئی تو میں مدینہ واپس آیا اور میرے ساتھ جو لوگ تھے وہ بھی مدینہ آ گئے۔ میں آپؐ کی خدمت میں حاضر ہوا۔ آپؐ خاموش تھے اور بالکل بات نہیں کر رہے تھے۔ حضورؐ میرے اوپر اپنے دونوں ہاتھ رکھ کر پھر اوپر کو اٹھاتے، حضورؐ نے بار بار ایسا کیا جس سے میں سمجھا کہ آپؐ میرے لیے دعا فرما رہے ہیں۔",""],[" (6)","s"]]]],"f":[["(6)","Ahmad, Tirmidhi, Tabraani and others, as quoted in Kanzul Ummaal (Vol.7 Pg.5) and Muntakhab Kanzul Ummaal (Vol.5 Pg.136)."]]}]},"132":{"lead":[],"stories":[{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں حضورؐ نے یہ دعا تین مرتبہ فرمائی اے ",""],["ٱللَّٰه","a"],["! عمرو بن عاص کی مغفرت فرما کیونکہ جب بھی میں نے انہیں صدقہ دینے کے لیے بلایا وہ ہمیشہ میرے پاس صدقہ لے کر آئے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Adi, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.250)."]]},{"b":[["n",[["حضرت حکیم بن حزامؓ","b"],[" فرماتے ہیں حضورؐ نے میرے لیے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! تو اس کے ہاتھ کے کاروبار میں برکت عطا فرما۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani."]]},{"b":[["n",[["حضرت حکیم بن حزامؓ","b"],[" فرماتے ہیں حضورؐ نے مجھے ایک دینار دے کر قربانی کا جانور خریدنے کے لیے بھیجا۔ میں نے ایک دینار میں جانور خرید کر دو دینار میں بیچ دیا اور پھر ایک دینار کی بکری خریدی اور ایک دینار لا کر حضورؐ کی خدمت میں پیش کر دیا۔ حضورؐ نے میرے لیے برکت کی دعا فرمائی اور فرمایا جو دینار تم لائے ہو اسے صدقہ کر دو۔",""],[" (3)","s"]]]],"f":[["(3)","Abdur Razzaaq and Ibn Abi Shaybah, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.152)."]]},{"b":[["n",[["حضرت جریرؓ","b"],[" فرماتے ہیں میں گھوڑے پر جم کر بیٹھ نہیں سکتا تھا چنانچہ گر جایا کرتا تھا۔ میں نے حضورؐ سے اس کا تذکرہ کیا، آپؐ نے اپنا ہاتھ میرے سینے پر مارا اور آپؐ کے ہاتھ (کی برکت) کا اثر میں نے اپنے سینے میں محسوس کیا۔ آپؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اسے (گھوڑے پر) جما دے اور دوسروں کو ہدایت پر لانے والا اور خود ہدایت یافتہ بنا دے۔ چنانچہ میں اس دعا کے بعد کبھی گھوڑے سے نہیں گرا۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani."]]},{"b":[["n",[["حضرت جریرؓ","b"],[" فرماتے ہیں حضورؐ نے مجھ سے فرمایا کیا تم خلصہ بت والا گھر گرا کر مجھے راحت نہیں پہنچاتے؟ یہ زمانہ جاہلیت میں قبیلہ خثعم کا ایک گھر تھا جسے یمنی کعبہ کہا جاتا تھا۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! (میں گھوڑے سے) گر جاتا ہوں۔ پھر پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abi Shaybah, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.152)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن بسرؓ","b"],[" فرماتے ہیں میں اور میرے والد ہم دونوں اپنے گھر کے دروازے پر بیٹھے ہوئے تھے کہ اتنے میں سامنے سے حضورؐ اپنے خچر پر تشریف لائے۔ میرے والد نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کیا آپ ہمارے گھر نہیں آتے اور کھانا کھا کر ہمارے لیے برکت کی دعا نہیں کرتے؟ چنانچہ آپؐ ہمارے گھر تشریف لے گئے اور کھانا کھا کر یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! ان پر رحم فرما، ان کی مغفرت فرما اور ان کے رزق میں برکت فرما۔ طبرانی کی روایت میں اس کے بعد یہ بھی ہے کہ پھر ہم ہمیشہ ",""],["ٱللَّٰه","a"],[" کی طرف سے رزق میں وسعت ہی دیکھتے رہے۔",""],[" (6)","s"],[" (7)","s"]]]],"f":[["(6)","Ibn Asaakir."],["(7)","Tabraani, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.220)."]]}]},"133":{"lead":[],"stories":[{"b":[["n",[["حضرت نضلہ بن عمرو غفاریؓ","b"],[" فرماتے ہیں قبیلہ غفار کا ایک آدمی نبی کریمؐ کی خدمت میں آیا۔ حضورؐ نے پوچھا تمہارا نام کیا ہے؟ اس نے کہا مہان (جس کا لفظی ترجمہ قابل اہانت ہے)۔ حضورؐ نے فرمایا نہیں بلکہ تم مکرم یعنی قابل اکرام ہو۔ حضورؐ نے مدینہ آنے کے بعد حضرت براء بن معرورؓ کے لیے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! براء بن معرور پر رحمت نازل فرما اور قیامت کے دن اسے اپنے سے پردہ میں نہ رکھ اور اسے جنت میں داخل فرما، اور تو نے واقعی ایسے کر دیا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Mandah and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.144)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن ابی قتادہؒ","b"],[" فرماتے ہیں حضورؐ جب مدینہ تشریف لائے تو آپؐ نے سب سے پہلے حضرت براء بن معرورؓ کے لیے دعائے رحمت فرمائی۔ حضورؐ صحابہؓ کو لے کر وہاں گئے، صحابہؓ ان کے سامنے صف بنا کر کھڑے ہو گئے۔ حضورؐ نے ان کے لیے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! ان کی مغفرت فرما، ان پر رحم فرما، ان سے راضی ہو جا، اور تو نے واقعی ایسے کر دیا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.3 Pg.620)."]]},{"b":[["n",[["حضرت قیس بن سعدؓ","b"],[" فرماتے ہیں حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اپنی خاص رحمت اور اپنی عام رحمت سعد بن عبادہ کے خاندان پر نازل فرما۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Dawood, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.190)."]]},{"b":[["n",[["حضرت ابوقتادہؓ","b"],[" فرماتے ہیں ہم لوگ ایک سفر میں حضورؐ کے ساتھ تھے، آپؐ (نیند کی وجہ سے) سواری سے ایک طرف کو جھک گئے۔ میں نے آپؐ کو سہارا دیا یہاں تک کہ آپؐ کی آنکھ کھل گئی تو آپؐ نے مجھے یہ دعا دی اے ",""],["ٱللَّٰه","a"],["! ابوقتادہ کی ایسے حفاظت فرما جیسے اس نے آج رات میری حفاظت کی۔ اور پھر مجھے فرمایا میرا خیال یہ ہے کہ ہماری وجہ سے تمہیں بڑی مشقت اٹھانی پڑی ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym and Tabraani, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.161)."]]}]},"134":{"lead":[],"stories":[{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں (میری والدہ) حضرت ام سلیمؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! انس کے لیے دعا فرما دیں۔ آپؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اس کے مال اور اولاد کو زیادہ فرما دے اور اس کے مال اور اولاد میں برکت عطا فرما۔ آگے اور حدیث ذکر کی ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.142)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" فرماتے ہیں ایک آدمی کو حرملہ کہا جاتا تھا، اس نے نبی کریمؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ایمان تو بس یہاں ہے اور زبان کی طرف اشارہ کیا اور نفاق یہاں ہے اور دل کی طرف اشارہ کیا اور میں ",""],["ٱللَّٰه","a"],[" کا ذکر بس تھوڑا سا کیا کرتا ہوں۔ حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اسے ذکر کرنے والی زبان اور شکر کرنے والا دل عطا فرما اور اسے اس بات کی توفیق عطا فرما کہ یہ اس سے محبت کرے جو مجھ سے محبت کرتا ہے اور ہر کام میں اس کے انجام کو خیر فرما۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani. Haythami (Vol.9 Pg.402) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت تلبؓ","b"],[" فرماتے ہیں میں نے نبی کریمؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرے لیے دعائے مغفرت فرما دیں۔ حضورؐ نے فرمایا جب تمہارے لیے دعا کرنے کی ",""],["ٱللَّٰه","a"],[" کی طرف سے اجازت ملے گی تب کروں گا۔ حضورؐ کچھ دیر ٹھہرے پھر میرے لیے یہ دعا تین مرتبہ فرمائی اے ",""],["ٱللَّٰه","a"],["! تلب کی مغفرت فرما اور اس پر رحم فرما۔ پھر آپؐ نے اپنے چہرے پر ہاتھ پھیرے۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani. Haythami (Vol.9 Pg.402) has commented on the chain of narrators. Ibn Sa'd has reported a similar narration."]]},{"b":[["n",[["حضرت ابوموسیؓ","b"],[" فرماتے ہیں حضورؐ نے یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اس چھوٹے سے بندے ابوعامر کو درجہ میں قیامت کے دن اکثر لوگوں سے اوپر کر دینا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Sa'd and Tabraani, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.239)."]]},{"b":[["n",[["حضرت حسان بن شدادؒ","b"],[" فرماتے ہیں میری والدہ نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں آپ کی خدمت میں اس لیے حاضر ہوئی ہوں تاکہ آپ میرے اس بیٹے کے لیے دعا کر دیں اور اسے بڑا اور اچھا بنا دیں۔ آپؐ نے وضو کیا اور وضو کے بچے ہوئے پانی کو میرے چہرے پر پھیرا اور یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! اس عورت کے لیے اس کے بیٹے میں برکت عطا فرما اور اسے بڑا اور عمدہ بنا۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.167)."]]}]},"135":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ نے نماز سے سلام پھیرا اور ابھی آپؐ کا چہرہ قبلہ کی طرف تھا کہ آپؐ نے سر اٹھا کر یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! سلمہ بن ہشام، عیاش بن ابی ربیعہ، ولید بن ولید اور تمام کمزور مسلمانوں کو (ظالم کافروں کے ہاتھ سے) چھڑا دے جو کوئی تدبیر نہیں کر سکتے اور جنہیں کوئی راستہ سجھائی نہیں دیتا۔ ابن سعد کی دوسری روایت میں یہ ہے کہ حضرت ابوہریرہؓ فرماتے ہیں کہ جب حضورؐ نے فجر کے رکوع سے سر اٹھایا تو یہ دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! ولید بن ولید، سلمہ بن ہشام، عیاش بن ابی ربیعہ اور مکہ کے تمام کمزور مسلمانوں کو (کافروں سے) نجات نصیب فرما۔ اے ",""],["ٱللَّٰه","a"],["! قبیلہ مضر کی سخت پکڑ فرما اور انہیں قحط سالی میں ایسے مبتلا فرما جیسے تو نے حضرت یوسفؑ کے زمانہ میں سات سال کا قحط بھیجا تھا۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Bazzaar. Haythami (Vol.10 Pg.152) has commented on the chain of narrators. Ibn Sa'd (Vol.4 Pg.130) has reported a similar narration."],["(2)","Ibn Sa'd (Vol.4 Pg.130)."]]}]},"136":{"lead":[],"stories":[{"b":[["n",[["حضرت معاذ بن جبلؓ","b"],[" فرماتے ہیں کہ حضورؐ نے میرا ہاتھ پکڑ کر فرمایا اے معاذ! ",""],["ٱللَّٰه","a"],[" کی قسم! میں تم سے محبت کرتا ہوں۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرے ماں باپ آپ پر قربان ہوں، ",""],["ٱللَّٰه","a"],[" کی قسم! مجھے بھی آپ سے محبت ہے۔ حضورؐ نے فرمایا اے معاذ! میں تمہیں یہ وصیت کرتا ہوں کہ تم نماز کے بعد یہ دعا کبھی نہ چھوڑنا، ہمیشہ مانگنا",""]]],["q",[["ٱللَّهُمَّ أَعِنِّي عَلَىٰ ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اپنے ذکر میں، اپنا شکر ادا کرنے میں اور اپنی اچھی طرح عبادت کرنے میں میری مدد فرما۔\" راوی کہتے ہیں حضرت معاذؓ نے اپنے شاگرد صنابحیؒ کو اور صنابحیؒ نے ابوعبدالرحمٰنؒ کو اور ابوعبدالرحمٰنؒ نے عقبہ بن مسلمؒ کو اس دعا کی وصیت فرمائی۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Dawood, Nasa'ee, Ibn Khuzaymah and Ibn Hibbaan in their Saheehs, and Haakim who declared it authentic on the conditions of Bukhaari and Muslim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.113)."]]},{"b":[["n",[["حضرت عون بن عبد","b"],["ٱللَّٰه","a"],[" بن عتبہؒ","b"],[" کہتے ہیں ایک آدمی نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرو بن عاصؓ کے پہلو میں نماز پڑھی، اس نے سنا کہ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ سلام کے بعد یہ دعا پڑھ رہے ہیں",""]]],["q",[["ٱللَّهُمَّ أَنْتَ ٱلسَّلَامُ وَمِنْكَ ٱلسَّلَامُ تَبَارَكْتَ يَا ذَا ٱلْجَلَالِ وَٱلْإِكْرَامِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تو ہی سلامتی دینے والا ہے، تیری ہی جانب سے سلامتی نصیب ہوتی ہے، تو بہت برکت والا ہے، اے عظمت و جلال والے اور اکرام و احسان والے!\" پھر اس آدمی نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرؓ کے پہلو میں نماز پڑھی تو اس نے انہیں بھی سلام کے بعد یہی دعا پڑھتے ہوئے سنا تو وہ ہنس پڑا۔ حضرت ابن عمرؓ نے اس سے پوچھا میاں کیوں ہنس رہے ہو؟ اس نے کہا میں نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمروؓ کے پہلو میں نماز پڑھی تھی تو ان کو بھی یہ دعا پڑھتے ہوئے سنا تھا۔ حضرت ابن عمرؓ نے فرمایا خود حضورؐ بھی یہ دعا پڑھتے تھے۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani, whose narrators are those of authentic Ahaadeeth as confirmed by Haythami (Vol.10 Pg.102). Ibn Abi Shaybah has reported it from Silah bin Zufar who heard Ibn Umar say it after salaah, as quoted in Kanzul Ummaal (Vol.1 Pg.295). Abu Dawood (Vol.2 Pg.359) has reported a similar narration from Hadhrat Aa'isha."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں نبی کریمؐ جب نماز سے فارغ ہوتے تو دایاں ہاتھ اپنے سر پر پھیرتے اور فرماتے",""]]],["q",[["بِسْمِ ٱللَّهِ ٱلَّذِي لَا إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ، ٱللَّهُمَّ أَذْهِبْ عَنِّي ٱلْهَمَّ وَٱلْحَزَنَ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے نام سے (شروع کرتا ہوں) جس کے سوا اور کوئی معبود نہیں، وہ بڑا مہربان اور بہت رحم کرنے والا ہے۔ اے ",""],["ٱللَّٰه","a"],["! تو ہر فکر اور پریشانی مجھ سے دور فرما دے۔\" ایک روایت میں یہ ہے کہ اپنا دایاں ہاتھ اپنی پیشانی پر پھیرتے اور فرماتے",""]]],["q",[["ٱللَّهُمَّ أَذْهِبْ عَنِّي ٱلْغَمَّ وَٱلْحَزَنَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تو غم اور پریشانی مجھ سے دور فرما دے۔\"",""],[" (3)","s"]]]],"f":[["(3)","Tabraani. Haythami (Vol.10 Pg.110) has commented that Tabraani in his Awsat and Bazzaar have reported a similar narration through several chains. Zayd Al Ammi in it was declared reliable by many scholars but weak by the majority, while the remaining narrators of one of Tabraani's chains are reliable although some differ."]]},{"b":[["n",[["حضرت ابوایوبؓ","b"],[" فرماتے ہیں جب بھی میں نے تمہارے نبیؐ کے پیچھے نماز پڑھی تو میں نے انہیں نماز سے فارغ ہو کر یہی کہتے ہوئے سنا",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ خَطَايَايَ وَذُنُوبِي كُلَّهَا، ٱللَّهُمَّ وَأَنْعِشْنِي وَٱجْبُرْنِي وَٱهْدِنِي لِصَالِحِ ٱلْأَعْمَالِ وَٱلْأَخْلَاقِ لَا يَهْدِي لِصَالِحِهَا وَلَا يَصْرِفُ سَيِّئَهَا إِلَّا أَنْتَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میری تمام خطائیں اور گناہ معاف فرما۔ اے ",""],["ٱللَّٰه","a"],["! مجھے بلندی عطا فرما اور میری کمیوں کو دور فرما اور مجھے نیک اعمال اور اچھے اخلاق کی ہدایت نصیب فرما (اس لیے کہ) اچھے کاموں اور اچھے اخلاق کی ہدایت تیرے سوا اور کوئی نہیں دے سکتا اور برے کاموں اور برے اخلاق سے تیرے سوا اور کوئی ہم سے دور نہیں کر سکتا۔\"",""],[" (4)","s"]]]],"f":[["(4)","Tabraani in his Sagheer and Awsat, with a sound chain as confirmed by Haythami (Vol.10 Pg.111)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں جب بھی میں نے تمہارے نبیؐ کے پیچھے نماز پڑھی تو نماز سے فارغ ہوتے ہی حضورؐ کو یہی کہتے ہوئے سنا",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لِي خَطَايَايَ وَعَمْدِي، ٱللَّهُمَّ ٱهْدِنِي لِصَالِحِ ٱلْأَعْمَالِ وَٱلْأَخْلَاقِ، إِنَّهُ لَا يَهْدِي لِصَالِحِهَا وَلَا يَصْرِفُ سَيِّئَهَا إِلَّا أَنْتَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں نے جو گناہ بھولے سے کیے اور جو جان کر کیے وہ سب معاف فرما۔\" (باقی ترجمہ گزر چکا۔)",""],[" (5)","s"]]]],"f":[["(5)","Tabraani in his Sagheer, whose narrators are reliable as confirmed by Haythami."]]},{"b":[["n",[["حضرت ام سلمہؓ","b"],[" فرماتی ہیں حضورؐ فجر کی نماز کے بعد یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ رِزْقًا طَيِّبًا وَعِلْمًا نَافِعًا وَعَمَلًا مُتَقَبَّلًا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے پاکیزہ روزی، نفع دینے والے علم اور مقبول عمل کی توفیق مانگتا ہوں۔\"",""],[" (6)","s"]]]],"f":[["(6)","Tabraani in his Sagheer, whose narrators are reliable as confirmed by Haythami (Vol.10 Pg.111)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ ہر نماز کے بعد یہ دعا پڑھا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ رَبَّ جِبْرِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ أَعِذْنِي مِنْ حَرِّ ٱلنَّارِ وَعَذَابِ ٱلْقَبْرِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اے جبرائیل، میکائیل اور اسرافیل کے رب! مجھے جہنم کی گرمی سے اور قبر کے عذاب سے پناہ عطا فرما۔\"",""],[" (7)","s"]]]],"f":[["(7)","Tabraani in his Awsat from his teacher Ali bin Sa'eed Raazi. Haythami (Vol.10 Pg.110) has remarked that there is some criticism of him which does not harm, and that the remaining narrators are reliable."]]},{"b":[["n",[["حضرت ابوبکرؓ","b"],[" فرماتے ہیں نبی کریمؐ نماز کے بعد یہ دعا پڑھا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلْكُفْرِ وَٱلْفَقْرِ وَعَذَابِ ٱلْقَبْرِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں کفر، فقر اور عذاب قبر سے تیری پناہ چاہتا ہوں۔\"",""],[" (8)","s"]]]],"f":[["(8)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.296)."]]},{"b":[["n",[["حضرت معاویہؓ","b"],[" فرماتے ہیں میں نے سنا کہ جب حضورؐ نماز سے فارغ ہوتے تو یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا ٱلْجَدِّ مِنْكَ ٱلْجَدُّ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! جو تو دے اسے کوئی روکنے والا نہیں اور جسے تو روک لے اسے کوئی دینے والا نہیں اور کسی دولتمند کو اس کی دولت تیری پکڑ سے بچا نہیں سکتی۔\"",""],[" (9)","s"]]]],"f":[["(9)","Nasa'ee, as quoted in Kanzul Ummaal (Vol.1 Pg.296)."]]},{"b":[["n",[["حضرت ابوموسیٰ اشعریؓ","b"],[" فرماتے ہیں میں حضورؐ کی خدمت میں وضو کا پانی لے کر آیا، آپؐ نے وضو فرما کر نماز پڑھی پھر یہ دعا پڑھی",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لِي ذَنْبِي وَوَسِّعْ لِي فِي دَارِي وَبَارِكْ لِي فِي رِزْقِي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میرے گناہ معاف فرما اور میرے گھر میں وسعت عطا فرما اور میرے رزق میں برکت عطا فرما۔\"",""],[" (10)","s"]]]],"f":[["(10)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.306)."]]},{"b":[["n",[["حضرت زید بن ارقمؓ","b"],[" فرماتے ہیں حضورؐ نماز کے بعد یہ کلمات کہا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَىْءٍ أَنَا شَهِيدٌ أَنَّكَ أَنْتَ ٱلرَّبُّ وَحْدَكَ لَا شَرِيكَ لَكَ، ٱللَّهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَىْءٍ أَنَا شَهِيدٌ أَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ، ٱللَّهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَىْءٍ أَنَا شَهِيدٌ أَنَّ ٱلْعِبَادَ كُلَّهُمْ إِخْوَةٌ، ٱللَّهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَىْءٍ ٱجْعَلْنِي مُخْلِصًا لَكَ وَأَهْلِي فِي كُلِّ سَاعَةٍ فِي ٱلدُّنْيَا وَٱلْآخِرَةِ، يَا ذَا ٱلْجَلَالِ وَٱلْإِكْرَامِ ٱسْمَعْ وَٱسْتَجِبْ، ٱللَّهُ أَكْبَرُ ٱلْأَكْبَرُ، ٱللَّهُمَّ نُورَ ٱلسَّمَوَاتِ وَٱلْأَرْضِ ٱللَّهُ أَكْبَرُ ٱلْأَكْبَرُ، حَسْبِيَ ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ، ٱللَّهُ أَكْبَرُ ٱلْأَكْبَرُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اے ہمارے اور ہر چیز کے رب! میں اس بات پر گواہ ہوں کہ تو اکیلا ہے، تیرا کوئی شریک نہیں۔ اے ",""],["ٱللَّٰه","a"],["! اے ہمارے اور ہر چیز کے رب! میں اس بات پر گواہ ہوں کہ حضرت محمد (علیہ السلام) تیرے بندے اور رسول ہیں۔ اے ",""],["ٱللَّٰه","a"],["! اے ہمارے اور ہر چیز کے رب! میں اس بات پر گواہ ہوں کہ تمام بندے بھائی ہیں۔ اے ",""],["ٱللَّٰه","a"],["! اے ہمارے اور ہر چیز کے رب! دنیا اور آخرت کے تمام کاموں میں ہر گھڑی مجھے اور میرے گھر والوں کو مخلص بنا دے۔ اے بزرگی اور عظمت والے! اے اکرام و احسان والے! سن لے اور قبول فرما لے۔ ",""],["ٱللَّٰه","a"],[" سب سے بڑا اور سب سے ہی بڑا ہے۔ اے ",""],["ٱللَّٰه","a"],["! اے آسمانوں اور زمین کے نور! ",""],["ٱللَّٰه","a"],[" سب سے بڑا اور سب سے ہی بڑا ہے۔ ",""],["ٱللَّٰه","a"],[" مجھے کافی ہے اور بہترین کارساز ہے، ",""],["ٱللَّٰه","a"],[" سب سے بڑا اور سب سے ہی بڑا ہے۔\"",""],[" (11)","s"]]]],"f":[["(11)","Abu Dawood (Vol.2 Pg.358)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں حضورؐ جب نماز سے سلام پھیرتے تو یہ دعا فرماتے",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ ٱلْمُقَدِّمُ وَأَنْتَ ٱلْمُؤَخِّرُ لَا إِلَٰهَ إِلَّا أَنْتَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میرے اگلے پچھلے گناہ معاف فرما اور وہ گناہ بھی معاف فرما جو میں نے چھپ کر کیے اور جو میں نے علی الاعلان کیے اور میں نے جو بے اعتدالیاں کی ہیں اور میرے جن گناہوں کو تو مجھ سے زیادہ جانتا ہے ان سب کو معاف فرما، تو ہی آگے اور پیچھے کرنے والا ہے، تیرے سوا کوئی معبود نہیں۔\"",""],[" (12)","s"]]]],"f":[["(12)","Abu Dawood."]]}]},"137":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن قاسمؒ","b"],[" کہتے ہیں نبی کریمؐ کی ایک پڑوسن نے مجھے بتایا کہ وہ حضورؐ کو فجر طلوع ہوتے وقت یہ دعا پڑھتے ہوئے سنا کرتی تھی",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ ٱلْقَبْرِ وَمِنْ فِتْنَةِ ٱلْقَبْرِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں قبر کے عذاب سے اور قبر کی آزمائش (منکر نکیر کے سوال) سے تیری پناہ چاہتا ہوں۔\"",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, whose narrators are reliable as confirmed by Haythami (Vol.10 Pg.115)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں جب صبح ہوتی تو حضورؐ یہ پڑھا کرتے",""]]],["q",[["أَصْبَحْنَا وَأَصْبَحَ ٱلْمُلْكُ لِلَّهِ وَٱلْحَمْدُ لِلَّهِ لَا شَرِيكَ لَهُ لَا إِلَٰهَ إِلَّا هُوَ وَإِلَيْهِ ٱلنُّشُورُ","a"]]],["p",[["ترجمہ: \"ہم نے اور تمام ملک نے ",""],["ٱللَّٰه","a"],[" (کی عبادت اور اطاعت) کے لیے صبح کی اور تمام تعریفیں ",""],["ٱللَّٰه","a"],[" کے لیے ہیں، اس کا کوئی شریک نہیں، اس کے سوا کوئی معبود نہیں، اسی کے پاس موت کے بعد اٹھایا جانا ہے۔\" اور جب شام ہوتی تو یہ پڑھا کرتے",""]]],["q",[["أَمْسَيْنَا وَأَمْسَى ٱلْمُلْكُ لِلَّهِ وَٱلْحَمْدُ لِلَّهِ لَا شَرِيكَ لَهُ لَا إِلَٰهَ إِلَّا هُوَ وَإِلَيْهِ ٱلْمَصِيرُ","a"]]],["p",[["ترجمہ: \"ہم نے اور تمام دنیا نے ",""],["ٱللَّٰه","a"],[" (کی عبادت و اطاعت) کے لیے شام کی۔\" آگے ترجمہ صبح والی دعا کی طرح ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Bazzaar, with a sound chain as confirmed by Haythami (Vol.10 Pg.113)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں جب شام ہوتی تو حضورؐ یہ کلمات کہتے",""]]],["q",[["أَمْسَيْنَا وَأَمْسَى ٱلْمُلْكُ لِلَّهِ وَٱلْحَمْدُ لِلَّهِ لَا إِلَٰهَ إِلَّا ٱللَّهُ وَحْدَهُۥ لَا شَرِيكَ لَهُۥ، لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَٰذِهِ ٱللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَٰذِهِ ٱللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُ بِكَ مِنَ ٱلْكَسَلِ وَسُوءِ ٱلْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي ٱلنَّارِ وَعَذَابٍ فِي ٱلْقَبْرِ","a"]]],["p",[["ترجمہ: \"ہم نے اور تمام دنیا نے ",""],["ٱللَّٰه","a"],[" (کی عبادت و اطاعت) کے لیے شام کی اور تمام تعریفیں ",""],["ٱللَّٰه","a"],[" کے لیے ہیں، ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اسی کے لیے ساری بادشاہت اور ساری تعریفیں ہیں اور وہ ہر چیز پر قادر ہے۔ اے میرے رب! میں تجھ سے اس چیز کی خیر مانگتا ہوں جو اس رات میں ہے اور جو اس کے بعد ہے اور اس چیز کے شر سے تیری پناہ مانگتا ہوں جو اس رات میں ہے اور جو اس کے بعد ہے۔ اے میرے رب! میں سستی سے اور برے بڑھاپے سے تیری پناہ چاہتا ہوں۔ اے میرے رب! میں جہنم کے عذاب سے اور قبر کے عذاب سے تیری پناہ مانگتا ہوں۔\" اور جب صبح ہوتی تو یہی کلمات کہتے، البتہ شروع میں \"امسینا وامسی الملک للہ\" کی جگہ \"اصبحنا واصبح الملک للہ\" کہتے۔",""],[" (3)","s"]]]],"f":[["(3)","Muslim, Tirmidhi and Abu Dawood, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.258)."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن ابزیؓ","b"],[" فرماتے ہیں نبی کریمؐ صبح و شام یہ پڑھا کرتے",""]]],["q",[["أَصْبَحْنَا عَلَىٰ مِلَّةِ ٱلْإِسْلَامِ أَوْ أَمْسَيْنَا عَلَىٰ فِطْرَةِ ٱلْإِسْلَامِ وَعَلَىٰ كَلِمَةِ ٱلْإِخْلَاصِ وَعَلَىٰ دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى ٱللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَىٰ مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ","a"]]],["p",[["ترجمہ: \"ہم نے ملت اسلام پر، اسلامی فطرت پر، کلمہ اخلاص پر اور اپنے نبی حضرت محمدؐ کے دین پر اور اپنے باپ حضرت ابراہیم علیہ السلام کی ملت پر صبح (اور شام) کی، حضرت ابراہیمؑ سب سے یکسو ہو کر ایک ",""],["ٱللَّٰه","a"],[" کے ہو گئے تھے اور وہ مسلمان تھے اور مشرکوں میں سے نہیں تھے۔\"",""],[" (4)","s"]]]],"f":[["(4)","Ahmad and Tabraani, whose narrators are those of authentic Ahaadeeth as confirmed by Haythami (Vol.10 Pg.116)."]]},{"b":[["n",[["حضرت ابوسلامؒ","b"],[" کہتے ہیں ایک صاحب حمص کی مسجد میں سے گزرے، لوگوں نے کہا انہوں نے نبی کریمؐ کی خدمت میں حاضری دی ہے۔ میں اٹھ کر ان کے پاس گیا اور ان سے عرض کیا کہ مجھے کوئی ایسی حدیث بیان کریں جو حضورؐ سے آپ نے براہ راست سنی ہو اور آپ کے اور حضورؐ کے درمیان کوئی واسطہ نہ ہو۔ انہوں نے کہا حضورؐ نے فرمایا کہ جو بھی صبح اور شام تین مرتبہ یہ کلمات کہے گا تو اس پر ",""],["ٱللَّٰه","a"],[" کا یہ حق (",""],["ٱللَّٰه","a"],[" کے فضل سے) ہوگا کہ ",""],["ٱللَّٰه","a"],[" اسے قیامت کے دن راضی کرے",""]]],["q",[["رَضِيتُ بِٱللَّهِ رَبًّا وَبِٱلْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ صَلَّى ٱللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا","a"]]],["p",[["ترجمہ: \"میں نے ",""],["ٱللَّٰه","a"],[" کو رب، اسلام کو دین اور حضرت محمدؐ کو نبی مان لیا اور میں اس پر راضی ہوں۔\"",""],[" (5)","s"]]]],"f":[["(5)","Ahmad. Tabraani has reported a similar narration, and the narrators of both are reliable as confirmed by Haythami (Vol.10 Pg.116). Abu Dawood and Nasa'ee have also reported it."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" ابن عمرؓ","b"],[" فرماتے ہیں میں نے حضورؐ کو صبح اور شام کی دعاؤں میں یہ دعا ہمیشہ پڑھتے ہوئے سنا اور آپؐ نے اپنے انتقال تک اس دعا کو کبھی نہیں چھوڑا",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ ٱلْعَافِيَةَ فِي ٱلدُّنْيَا وَٱلْآخِرَةِ، ٱللَّهُمَّ إِنِّي أَسْأَلُكَ ٱلْعَفْوَ وَٱلْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي، ٱللَّهُمَّ ٱسْتُرْ عَوْرَاتِي وَآمِنْ رَوْعَاتِي، ٱللَّهُمَّ ٱحْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے دنیا اور آخرت میں عافیت مانگتا ہوں اور میں تجھ سے معافی مانگتا ہوں اور اپنے دین اور دنیا میں اور اپنے اہل و عیال اور مال میں عافیت و سلامتی چاہتا ہوں۔ اے ",""],["ٱللَّٰه","a"],["! میرے عیوب کی پردہ پوشی فرما اور میرے خوف اور پریشانی کو امن و امان سے بدل دے۔ اے ",""],["ٱللَّٰه","a"],["! آگے سے، پیچھے سے، دائیں سے، بائیں سے اور اوپر سے میری حفاظت فرما اور میں اس بات سے تیری عظمت کی پناہ چاہتا ہوں کہ مجھے اچانک نیچے سے (زمین میں دھنسا کر) ہلاک کر دیا جائے۔\"",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.293). Jubayr bin Sulayman explained \"Al Ightiyaal\" as being swallowed into the ground, adding that he does not know whether this was the statement of Rasulullaah or his own."]]},{"b":[["n",[["حضرت ابوبکرؓ","b"],[" فرماتے ہیں حضورؐ نے مجھے اس بات کا حکم دیا کہ میں صبح اور شام اور رات کو بستر پر لیٹتے وقت یہ کلمات کہا کروں",""]]],["q",[["ٱللَّهُمَّ فَاطِرَ ٱلسَّمَوَاتِ وَٱلْأَرْضِ عَالِمَ ٱلْغَيْبِ وَٱلشَّهَادَةِ، أَنْتَ رَبُّ كُلِّ شَىْءٍ وَمَلِيكُهُ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ، وَأَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ ٱلشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَىٰ نَفْسِي سُوءًا أَوْ أَجُرَّهُ إِلَىٰ مُسْلِمٍ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اے آسمانوں اور زمین کے پیدا فرمانے والے! ہر پوشیدہ اور ظاہر کے جاننے والے! تو ہر چیز کا پروردگار اور مالک ہے۔ میں اس بات کی گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں، تو اکیلا ہے، تیرا کوئی شریک نہیں اور حضرت محمد (علیہ السلام) تیرے بندے اور رسول ہیں اور میں اپنے نفس کے شر سے اور شیطان کے شر اور پھندے سے اور اس بات سے تیری پناہ چاہتا ہوں کہ میں اپنے نفس پر کسی برائی کا ارتکاب کروں یا کسی مسلمان پر کسی برائی کی تہمت لگاؤں۔\"",""],[" (7)","s"]]]],"f":[["(7)","Ahmad, Ibn Muneeh, Abu Ya'la and Ibn Sunni in Amalul Yawm wal Laylah, as quoted in Kanzul Ummaal (Vol.1 Pg.294). Abu Dawood and Tirmidhi have reported it with slight differences in wording from Hadhrat Abu Hurayrah."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں نبی کریمؐ کے پاس ایک آدمی آیا اور اس نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" کی قسم! مجھے اپنی جان، اپنے اہل و عیال اور مال کے بارے میں بہت ڈر رہتا ہے۔ حضورؐ نے فرمایا صبح اور شام یہ کلمات کہا کرو",""]]],["q",[["بِسْمِ ٱللَّهِ عَلَىٰ دِينِي وَنَفْسِي وَوَلَدِي وَأَهْلِي وَمَالِي","a"]]],["p",[["ترجمہ: \"میں اپنے دین پر، اپنی جان پر، اپنی اولاد پر، اپنے گھر والوں پر اور اپنے مال پر ",""],["ٱللَّٰه","a"],[" کا نام لیتا ہوں۔\" اس آدمی نے یہ کلمات کہنے شروع کر دیے اور پھر حضورؐ کی خدمت میں آیا۔ حضورؐ نے اس سے پوچھا تمہیں جو ڈر لگتا تھا اس کا کیا ہوا؟ اس نے کہا اس ذات کی قسم جس نے آپ کو حق دے کر بھیجا ہے وہ ڈر بالکل جاتا رہا ہے۔",""]]]],"f":[]}]},"138":{"lead":[],"stories":[{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں نبی کریمؐ جب بستر پر تشریف لے جاتے تو یہ دعا پڑھتے",""]]],["q",[["ٱلْحَمْدُ لِلَّهِ ٱلَّذِي أَطْعَمَنَا وَسَقَانَا وَكَفَانَا وَآوَانَا فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ","a"]]],["p",[["ترجمہ: \"اس ",""],["ٱللَّٰه","a"],[" کا لاکھ لاکھ شکر ہے جس نے ہمیں کھلایا پلایا اور ہماری تمام ضرورتوں کو پورا کیا اور ہمیں (رات گزارنے کے لیے) ٹھکانہ دیا، اس لیے کہ کتنے لوگ ایسے ہیں جن کا نہ کوئی ضرورت پوری کرنے والا ہے اور نہ کوئی ٹھکانہ دینے والا۔\"",""],[" (1)","s"]]]],"f":[["(1)","Muslim, Tirmidhi and Abu Dawood."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں نبی کریمؐ جب بستر پر لیٹتے تو یہ دعا پڑھتے",""]]],["q",[["ٱلْحَمْدُ لِلَّهِ ٱلَّذِي كَفَانِي وَآوَانِي وَأَطْعَمَنِي وَسَقَانِي وَٱلَّذِي مَنَّ عَلَيَّ فَأَفْضَلَ وَٱلَّذِي أَعْطَانِي فَأَجْزَلَ، ٱلْحَمْدُ لِلَّهِ عَلَىٰ كُلِّ حَالٍ، ٱللَّهُمَّ رَبَّ كُلِّ شَىْءٍ وَمَلِيكَهُ أَعُوذُ بِكَ مِنَ ٱلنَّارِ","a"]]],["p",[["ترجمہ: \"اس ",""],["ٱللَّٰه","a"],[" کا لاکھ لاکھ شکر ہے جس نے میری تمام ضرورتیں پوری کیں اور مجھے ٹھکانہ دیا اور مجھے کھلایا پلایا اور جس نے مجھ پر خوب احسانات کیے اور بہت زیادہ نعمتیں دیں، ہر حال میں ",""],["ٱللَّٰه","a"],[" کا شکر ہے۔ اے ",""],["ٱللَّٰه","a"],["! اے ہر چیز کے رب اور مالک! میں آگ سے ",""],["ٱللَّٰه","a"],[" کی پناہ چاہتا ہوں۔\"",""],[" (2)","s"]]]],"f":[["(2)","Abu Dawood, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.259)."]]},{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرماتے ہیں نبی کریمؐ جب سونے کا ارادہ فرماتے تو اپنا ہاتھ سر کے نیچے رکھ لیتے پھر یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَجْمَعُ (يَبْعَثُ) عِبَادَكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! جس دن تو اپنے بندوں کو جمع کرے گا (اٹھائے گا) اس دن تو مجھے اپنے عذاب سے بچا لے۔\"",""],[" (3)","s"]]]],"f":[["(3)","Tirmidhi, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.260). Bazzaar has reported a similar narration from Hadhrat Anas with the words \"On the day You resurrect\", with a sound chain as confirmed by Haythami (Vol.10 Pg.123). Ibn Abi Shaybah and Ibn Jareer have reported it with both wordings and declared it authentic, as quoted in Kanzul Ummaal (Vol.8 Pg.67)."]]},{"b":[["n",[["حضرت ابوازہر انماریؓ","b"],[" فرماتے ہیں نبی کریمؐ جب رات کو بستر پر لیٹتے تو یہ دعا پڑھتے",""]]],["q",[["بِسْمِ ٱللَّهِ وَضَعْتُ جَنْبِي لِلَّهِ ٱللَّهُمَّ ٱغْفِرْ لِي ذَنْبِي وَأَخْسِئْ شَيْطَانِي وَفُكَّ رِهَانِي وَٱجْعَلْنِي فِي ٱلنَّدِيِّ ٱلْأَعْلَىٰ","a"]]],["p",[["ترجمہ: \"میں نے ",""],["ٱللَّٰه","a"],[" کے نام کے ساتھ اپنا پہلو (سونے کے لیے بستر پر) رکھا۔ اے ",""],["ٱللَّٰه","a"],["! تو میرے گناہ بخش دے اور میرے شیطان کو (مجھ سے) دور کر دے اور میری گردن کو (ہر ذمہ داری سے) آزاد کر دے اور مجھے اعلیٰ مجلس والوں میں شامل کر دے۔\"",""],[" (4)","s"]]]],"f":[["(4)","Abu Dawood, as quoted in Majma'uz Zawaa'id (Vol.2 Pg.260)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں نبی کریمؐ بستر پر لیٹتے وقت یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِوَجْهِكَ ٱلْكَرِيمِ وَبِكَلِمَاتِكَ ٱلتَّامَّاتِ مِنْ شَرِّ كُلِّ دَابَّةٍ أَنْتَ آخِذٌ بِنَاصِيَتِهَا، ٱللَّهُمَّ أَنْتَ تَكْشِفُ ٱلْمَغْرَمَ وَٱلْمَأْثَمَ، ٱللَّهُمَّ لَا يُهْزَمُ جُنْدُكَ وَلَا يُخْلَفُ وَعْدُكَ وَلَا يَنْفَعُ ذَا ٱلْجَدِّ مِنْكَ ٱلْجَدُّ، سُبْحَانَكَ ٱللَّهُمَّ وَبِحَمْدِكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں ہر اس جانور کے شر سے تیری کریم ذات کی اور تیرے پورے کلمات کی پناہ چاہتا ہوں جو تیرے قبضہ اور قدرت میں ہے۔ اے ",""],["ٱللَّٰه","a"],["! تو ہی (بندے کے) قرض اور گناہ کو دور کرتا ہے (لہٰذا میرا قرضہ اتار دے اور میرے گناہ معاف کر دے)۔ اے ",""],["ٱللَّٰه","a"],["! تیرے لشکر کو شکست نہیں ہو سکتی اور تیرے وعدے کے خلاف نہیں ہو سکتا اور کسی مالدار کو اس کی مالداری تیرے قہر و غضب سے نہیں بچا سکتی۔ اے ",""],["ٱللَّٰه","a"],["! میں تیری پاکی اور تعریف بیان کرتا ہوں۔\"",""],[" (5)","s"]]]],"f":[["(5)","Abu Dawood, as quoted in Nawawi's Adhkaar. Nasa'ee has also reported it, and Kanzul Ummaal (Vol.8 Pg.67) attributes similar narrations to Nasa'ee, Ibn Jareer and Ibn Abi Dunya."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں جب حضورؐ سونے کا ارادہ فرماتے تو یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ فَاطِرَ ٱلسَّمَوَاتِ وَٱلْأَرْضِ عَالِمَ ٱلْغَيْبِ وَٱلشَّهَادَةِ رَبَّ كُلِّ شَىْءٍ وَإِلَٰهَهُ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ وَٱلْمَلَائِكَةُ يَشْهَدُونَ، ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَىٰ نَفْسِي سُوءًا أَوْ أَجُرَّهُ إِلَىٰ مُسْلِمٍ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اے آسمانوں اور زمین کے ایجاد کرنے والے! پوشیدہ اور ظاہر کے جاننے والے! اے ہر چیز کے رب! اے ہر چیز کے معبود! میں اس بات کی گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں، تو اکیلا ہے، تیرا کوئی شریک نہیں اور حضرت محمد (علیہ السلام) تیرے بندے اور رسول ہیں اور فرشتے بھی ان ہی دو باتوں کی گواہی دیتے ہیں۔ اے ",""],["ٱللَّٰه","a"],["! میں شیطان سے اور اس کے (فریب کے) جال سے اور اس بات سے تیری پناہ چاہتا ہوں کہ میں خود کوئی برا عمل کروں یا کسی مسلمان پر برائی کی تہمت لگاؤں۔\" حضرت ابوعبدالرحمٰنؒ کہتے ہیں حضورؐ نے یہ دعا حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمروؓ کو سکھائی تھی اور خود بھی جب سونے کا ارادہ فرماتے تو یہ دعا پڑھا کرتے تھے۔ ایک روایت میں یہ ہے کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمروؓ نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن یزیدؒ سے فرمایا کیا میں تمہیں وہ کلمات نہ سکھا دوں جو حضورؐ نے حضرت ابوبکر صدیقؓ کو سوتے وقت پڑھنے کے لیے سکھائے تھے، پھر پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (6)","s"],[" (7)","s"]]]],"f":[["(6)","Ahmad, with a sound chain as confirmed by Haythami (Vol.10 Pg.122). Another narration of Ahmad has the word \"Iqtarafa\" in place of \"An Aqtarifa\"."],["(7)","Tabraani through two chains. Haythami (Vol.10 Pg.123) has commented that the narrators of the first are those of authentic Ahaadeeth except Hayy bin Abdullaah Ma'aafiri, whom a group declared reliable and others weak. The narration of Hadhrat Abu Bakr has already passed in this regard."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں نبی کریمؐ جب سونے کے لیے لیٹتے تو یہ دعا پڑھتے",""]]],["q",[["بِاسْمِكَ رَبِّي فَٱغْفِرْ لِي ذَنْبِي","a"]]],["p",[["ترجمہ: \"اے میرے رب! میں تیرے نام کے ساتھ لیٹتا ہوں، میرے تمام گناہوں کو معاف فرما۔\"",""],[" (8)","s"]]]],"f":[["(8)","Ahmad, with a sound chain, as quoted in Majma'uz Zawaa'id (Vol.10 Pg.123)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں میں نے حضورؐ کے پاس ایک رات گزاری، نماز سے فارغ ہو کر جب آپؐ بستر پر لیٹنے لگے تو میں نے آپؐ کو یہ دعا پڑھتے ہوئے سنا",""]]],["q",[["ٱللَّهُمَّ أَعُوذُ بِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ وَأَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ وَأَعُوذُ بِكَ مِنْكَ لَا أَسْتَطِيعُ ثَنَاءً عَلَيْكَ وَلَوْ حَرَصْتُ وَلَكِنْ أَنْتَ كَمَا أَثْنَيْتَ عَلَىٰ نَفْسِكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تیری سزا سے تیرے عفو و درگزر کی پناہ چاہتا ہوں اور تیرے غصہ سے تیری رضا کی پناہ چاہتا ہوں اور تجھ سے تیری ہی پناہ چاہتا ہوں اور مجھے کتنا شوق ہو اور میں کتنا زور لگاؤں تیری تعریف کا حق ادا نہیں کر سکتا۔ تو تو ویسا ہے جیسے تو نے اپنی تعریف کی ہے۔\"",""],[" (9)","s"]]]],"f":[["(9)","Tabraani in his Awsat, whose narrators are those of authentic Ahaadeeth except Ibraaheem bin Abdullaah bin Abdul Qaari who was declared reliable by Ibn Hibbaan, as confirmed by Haythami (Vol.10 Pg.124). Nasa'ee and Yusuf Qaadi in his Sunan have also reported it from Hadhrat Ali, as quoted in Kanzul Ummaal (Vol.1 Pg.304)."]]},{"b":[["n",[["حضرت براءؓ","b"],[" فرماتے ہیں جب حضورؐ بستر پر لیٹتے تو یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ وَوَجَّهْتُ وَجْهِي إِلَيْكَ وَفَوَّضْتُ أَمْرِي إِلَيْكَ وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ رَغْبَةً وَرَهْبَةً إِلَيْكَ لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ ٱلَّذِي أَنْزَلْتَ وَنَبِيِّكَ ٱلَّذِي أَرْسَلْتَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں نے اپنی جان تیرے سپرد کر دی اور اپنا چہرہ تیری طرف کر دیا اور اپنا معاملہ تیرے سپرد کر دیا اور میں نے تیری رحمت کے شوق میں اور تیرے عذاب کے ڈر سے تجھے اپنا پشت پناہ بنا لیا اور تیری پکڑ سے بچنے کا تیری رحمت کے سوا کوئی ٹھکانہ نہیں، میں تیری اس کتاب پر ایمان لایا جو تو نے نازل کی اور تیرے اس نبی پر ایمان لایا جو تو نے بھیجا۔\"",""],[" (10)","s"]]]],"f":[["(10)","Ibn Jareer, who declared it authentic, and Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.8 Pg.67)."]]},{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرماتے ہیں نبی کریمؐ جب بستر پر لیٹتے تو یہ دعا پڑھتے",""]]],["q",[["بِاسْمِكَ ٱللَّهُمَّ أَحْيَا وَأَمُوتُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تیرے نام پر جیتا ہوں اور اسی پر مروں گا۔\" اور جب صبح ہوتی تو یہ دعا پڑھتے",""]]],["q",[["ٱلْحَمْدُ لِلَّهِ ٱلَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ ٱلنُّشُورُ","a"]]],["p",[["ترجمہ: \"اس ",""],["ٱللَّٰه","a"],[" کا بہت بہت شکر ہے جس نے ہمیں مارنے کے بعد پھر زندہ کیا اور اسی کے پاس مر کر جانا ہے۔\"",""],[" (11)","s"]]]],"f":[["(11)","Bukhaari, Abu Dawood and Tirmidhi, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.259). Ibn Jareer, who declared it authentic, has reported a similar narration from Hadhrat Abu Dharr with the words \"Allaahumma bismika namutu wa nahyaa\", as quoted in Kanzul Ummaal (Vol.8 Pg.67)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں نبی کریمؐ جب رات کو بیدار ہوتے تو یہ دعا پڑھتے",""]]],["q",[["لَا إِلَٰهَ إِلَّا أَنْتَ سُبْحَانَكَ ٱللَّهُمَّ وَبِحَمْدِكَ أَسْتَغْفِرُكَ لِذَنْبِي وَأَسْأَلُكَ رَحْمَتَكَ، ٱللَّهُمَّ زِدْنِي عِلْمًا وَلَا تُزِغْ قَلْبِي بَعْدَ إِذْ هَدَيْتَنِي وَهَبْ لِي مِنْ لَدُنْكَ رَحْمَةً إِنَّكَ أَنْتَ ٱلْوَهَّابُ","a"]]],["p",[["ترجمہ: \"تیرے سوا کوئی معبود نہیں، اے ",""],["ٱللَّٰه","a"],["! میں تیری پاکی اور تیری تعریف بیان کرتا ہوں اور تجھ سے اپنے گناہوں کی معافی مانگتا ہوں اور تجھ سے تیری رحمت کا سوال کرتا ہوں۔ اے ",""],["ٱللَّٰه","a"],["! مجھے علم عطا فرما اور ہدایت دینے کے بعد میرے دل کو (گمراہ کر کے) ٹیڑھا نہ کر اور تو مجھے اپنی بارگاہ سے خاص رحمت عطا فرما، بے شک تو بہت بڑا عطا فرمانے والا ہے۔\"",""],[" (12)","s"]]]],"f":[["(12)","Abu Dawood, as quoted in Majma'uz Zawaa'id (Vol.2 Pg.260)."]]}]},"139":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں ایسا بہت کم ہوا کہ نبی کریمؐ مجلس سے اٹھے ہوں اور اپنے ساتھیوں کے لیے یہ دعائیں نہ مانگی ہوں (بلکہ اکثر مانگا کرتے تھے)",""]]],["q",[["ٱللَّهُمَّ ٱقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا تَحُولُ بِهِ بَيْنَنَا وَبَيْنَ مَعْصِيَتِكَ وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ وَمِنَ ٱلْيَقِينِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مَصِيبَاتِ ٱلدُّنْيَا، وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا، وَٱجْعَلْهُ ٱلْوَارِثَ مِنَّا، وَٱجْعَلْ ثَأْرَنَا عَلَىٰ مَنْ ظَلَمَنَا وَٱنْصُرْنَا عَلَىٰ مَنْ عَادَانَا، وَلَا تَجْعَلْ مُصِيبَتَنَا فِي دِينِنَا، وَلَا تَجْعَلِ ٱلدُّنْيَا أَكْبَرَ هَمِّنَا وَلَا مَبْلَغَ عِلْمِنَا، وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تو ہمیں اپنا اتنا ڈر نصیب فرما جو ہمارے اور تیری نافرمانی کے درمیان حائل ہو جائے اور ہمیں اپنی ایسی فرماں برداری نصیب فرما جس کے ذریعے تو ہمیں اپنی جنت میں پہنچا دے اور ایسا یقین نصیب فرما جس سے دنیا کی مصیبتوں کو جھیلنا ہمارے لیے آسان ہو جائے اور تو ہمیں جتنی زندگی نصیب فرمائے اس میں ہمیں اپنے کانوں، آنکھوں اور اپنی قوت سے فائدہ اٹھانے والا بنا اور ان تمام اعضاء کو ہماری زندگی تک باقی رکھ کر ہمارا وارث بنا اور ہمیں اس کی توفیق دے کہ ہم صرف ان لوگوں سے بدلہ لیں جو ہم پر ظلم کریں اور ان لوگوں کے مقابلہ میں ہماری مدد فرما جو ہم سے دشمنی رکھیں اور ہماری مصیبت ہمارے دین پر نہ ڈال اور دنیا کو ہمارا بڑا مقصد نہ بنا اور نہ اس کو ہمارے علم کی انتہا بنا اور جو ہمارے اوپر رحم نہ کھائے اس کو ہم پر مسلط نہ فرما۔\" اس باب سے متعلق کچھ دعائیں کفارہ مجلس کے باب میں گزر چکی ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Tirmidhi, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.261)."]]},{"b":[["n",[["حضرت ام سلمہؓ","b"],[" فرماتی ہیں نبی کریمؐ جب گھر سے باہر تشریف لے جاتے تو یہ دعا پڑھتے",""]]],["q",[["بِسْمِ ٱللَّهِ تَوَكَّلْتُ عَلَى ٱللَّهِ، ٱللَّهُمَّ إِنَّا نَعُوذُ بِكَ أَنْ نَزِلَّ أَوْ نَضِلَّ أَوْ نَظْلِمَ أَوْ نُظْلَمَ أَوْ نَجْهَلَ أَوْ يُجْهَلَ عَلَيْنَا","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے نام کے ساتھ میں گھر سے باہر نکل رہا ہوں اور میں نے ",""],["ٱللَّٰه","a"],[" پر بھروسہ کیا۔ اے ",""],["ٱللَّٰه","a"],["! ہم اس بات سے تیری پناہ چاہتے ہیں کہ ہم خود صحیح راستہ سے پھسل جائیں یا ہم دوسروں کو گمراہ کر دیں یا ہم کسی پر ظلم کریں یا کوئی ہم پر ظلم کرے یا ہم کسی کے ساتھ نادانی کا معاملہ کریں یا کوئی ہم سے نادانی کا معاملہ کرے۔\"",""],[" (2)","s"]]]],"f":[["(2)","Abu Dawood, Tirmidhi and Nasa'ee, as quoted in Majma'uz Zawaa'id (Vol.2 Pg.261)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمرو بن عاصؓ","b"],[" فرماتے ہیں جب نبی کریمؐ مسجد میں داخل ہوتے تو یہ کلمات کہتے",""]]],["q",[["أَعُوذُ بِٱللَّهِ ٱلْعَظِيمِ وَبِوَجْهِهِ ٱلْكَرِيمِ وَسُلْطَانِهِ ٱلْقَدِيمِ مِنَ ٱلشَّيْطَانِ ٱلرَّجِيمِ","a"]]],["p",[["ترجمہ: \"میں مردود شیطان سے عظمت والے ",""],["ٱللَّٰه","a"],["، اس کی کریم ذات کی اور اس کی قدیم سلطنت کی پناہ چاہتا ہوں۔\" آدمی جب یہ کلمات کہتا ہے تو شیطان کہتا ہے باقی سارے دن میں اس آدمی کی مجھ سے حفاظت ہو گئی۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Dawood."]]},{"b":[["n",[["حضرت فاطمہ بنت حسینؒ","b"],[" اپنی دادی حضرت فاطمۃ الکبریٰؓ سے نقل کرتی ہیں کہ جب حضورؐ مسجد میں داخل ہوتے تو پہلے اپنے اوپر درود و سلام بھیجتے پھر یہ دعا پڑھتے",""]]],["q",[["رَبِّ ٱغْفِرْ لِي ذُنُوبِي وَٱفْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","a"]]],["p",[["ترجمہ: \"اے میرے رب! میرے تمام گناہ معاف فرما اور اپنی رحمت کے دروازے میرے لیے کھول دے۔\" اور جب مسجد سے باہر نکلتے تو اپنے اوپر درود و سلام بھیجتے اور یہ دعا پڑھتے",""]]],["q",[["رَبِّ ٱغْفِرْ لِي ذُنُوبِي وَٱفْتَحْ لِي أَبْوَابَ فَضْلِكَ","a"]]],["p",[["ترجمہ: \"اے میرے رب! میرے تمام گناہ معاف فرما اور اپنے فضل کے دروازے میرے لیے کھول دے۔\"",""],[" (4)","s"]]]],"f":[["(4)","Tirmidhi. Ahmad and Ibn Maajah have also reported it, as quoted in Mishkaat (Pg.62), and in their narrations she says that when he entered the Masjid, and likewise when he left, he said \"Bismillaah was salaamu alaa Rasulillaah\" instead of sending salutations. Tirmidhi has remarked that the Hadith of Faatima is Hasan, but its chain is not unbroken since Faatima bint Husayn did not meet Faatima Al Kubra."]]}]},"140":{"lead":[],"stories":[{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں جب نبی کریمؐ سفر کا ارادہ فرماتے تو یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ بِكَ أَصُولُ وَبِكَ أَحُولُ وَبِكَ أَسِيرُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تیری مدد سے حملہ کروں گا اور تیری مدد سے تدبیر کروں گا اور تیری ہی مدد سے چلوں گا۔\"",""],[" (1)","s"]]]],"f":[["(1)","Ahmad and Bazzaar, whose narrators are reliable as confirmed by Haythami (Vol.10 Pg.130)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں جب حضورؐ باہر سفر پر تشریف لے جانے کے لیے اپنے اونٹ پر بیٹھ جاتے تو تین تین مرتبہ الحمد للہ، سبحان ",""],["ٱللَّٰه","a"],["، ",""],["ٱللَّٰه","a"],[" اکبر کہتے پھر یہ دعا پڑھتے",""]]],["q",[["سُبْحَانَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ وَإِنَّا إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ، ٱللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَٰذَا ٱلْبِرَّ وَٱلتَّقْوَىٰ وَمِنَ ٱلْعَمَلِ مَا تَرْضَىٰ، ٱللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَٰذَا وَٱطْوِ عَنَّا بُعْدَ ٱلْأَرْضِ، ٱللَّهُمَّ أَنْتَ ٱلصَّاحِبُ فِي ٱلسَّفَرِ وَٱلْخَلِيفَةُ فِي ٱلْأَهْلِ، ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ ٱلسَّفَرِ وَكَآبَةِ ٱلْمَنْظَرِ وَسُوءِ ٱلْمُنْقَلَبِ فِي ٱلْأَهْلِ وَٱلْمَالِ","a"]]],["p",[["ترجمہ: \"پاک ہے وہ ذات جس نے اس سواری کو ہمارے لیے مسخر کیا اور اس کی مدد کے بغیر اس پر قابو پانے والے نہیں تھے اور بلاشبہ ہم کو اپنے رب کی طرف جانا ہے۔ اے ",""],["ٱللَّٰه","a"],["! ہم تجھ سے اس سفر میں نیکی اور پرہیزگاری کا اور ان اعمال کا سوال کرتے ہیں جن سے تو راضی ہوتا ہے۔ اے ",""],["ٱللَّٰه","a"],["! ہمارے اس سفر کو ہمارے لیے آسان فرما اور اس کی مسافت کو جلدی طے کرا دے۔ اے ",""],["ٱللَّٰه","a"],["! تو سفر میں ہمارا ساتھی اور اہل و عیال میں ہمارا خلیفہ اور نائب ہے۔ اے ",""],["ٱللَّٰه","a"],["! میں سفر کی مشقت سے اور تکلیف دہ منظر اور اہل و عیال اور مال و دولت میں بری واپسی سے تیری پناہ چاہتا ہوں۔\" اور جب سفر سے واپس ہوتے تو بھی یہ دعا پڑھتے اور مزید یہ کلمات بھی کہتے",""]]],["q",[["آيِبُونَ تَائِبُونَ عَابِدُونَ لِرَبِّنَا سَاجِدُونَ","a"]]],["p",[["ترجمہ: \"ہم واپس لوٹنے والے ہیں، توبہ کرنے والے ہیں، (",""],["ٱللَّٰه","a"],[" کی) عبادت کرنے والے ہیں اور اپنے رب کے سامنے سجدہ کرنے والے ہیں۔\"",""],[" (2)","s"]]]],"f":[["(2)","Muslim, Abu Dawood and Tirmidhi, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.261)."]]},{"b":[["n",[["حضرت براءؓ","b"],[" فرماتے ہیں جب حضورؐ سفر میں تشریف لے جاتے تو یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ بَلِّغْنَا بَلَاغًا يُبَلِّغُ خَيْرًا مَغْفِرَةً مِنْكَ وَرِضْوَانًا، إِنَّكَ بِيَدِكَ ٱلْخَيْرُ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ، ٱللَّهُمَّ أَنْتَ ٱلصَّاحِبُ فِي ٱلسَّفَرِ وَٱلْخَلِيفَةُ فِي ٱلْأَهْلِ، ٱللَّهُمَّ هَوِّنْ عَلَيْنَا ٱلسَّفَرَ وَٱطْوِ لَنَا ٱلْأَرْضَ، ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ ٱلسَّفَرِ وَكَآبَةِ ٱلْمُنْقَلَبِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے ایسا ذریعہ مانگتا ہوں جو خیر تک پہنچائے اور تیری مغفرت اور رضامندی کا سوال کرتا ہوں۔ تمام بھلائیاں تیرے ہاتھ میں ہیں، بے شک تو ہر چیز پر قادر ہے۔ اے ",""],["ٱللَّٰه","a"],["! تو سفر میں ساتھی اور اہل و عیال میں خلیفہ ہے۔ اے ",""],["ٱللَّٰه","a"],["! سفر ہمارے لیے آسان فرما اور ہمارے لیے زمین لپیٹ دے یعنی تھوڑے وقت میں زیادہ مسافت طے کرا دے اور سفر کی مشقت سے اور تکلیف دہ واپسی سے تیری پناہ چاہتا ہوں۔\"",""],[" (3)","s"]]]],"f":[["(3)","Abu Ya'la, whose narrators are those of authentic Ahaadeeth except Fitr bin Khaleefa who is reliable, as confirmed by Haythami (Vol.10 Pg.130)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں جب نبی کریمؐ سفر میں ہوتے اور سحری کا وقت ہوتا تو یہ دعا پڑھتے",""]]],["q",[["سَمِعَ سَامِعٌ بِحَمْدِ ٱللَّهِ وَحُسْنِ بَلَائِهِ عَلَيْنَا، رَبَّنَا صَاحِبْنَا وَأَفْضِلْ عَلَيْنَا عَائِذًا بِٱللَّهِ مِنَ ٱلنَّارِ","a"]]],["p",[["ترجمہ: \"سننے والے نے ہم سے ",""],["ٱللَّٰه","a"],[" کی حمد و ثنا اور ",""],["ٱللَّٰه","a"],[" کے ہمیں اچھی طرح آزمانے کو سنا۔ اے ہمارے رب! تو ہمارا ساتھی ہو جا اور ہم پر فضل فرما، میں جہنم کی آگ سے ",""],["ٱللَّٰه","a"],[" کی پناہ لیتے ہوئے (یہ کہہ رہا ہوں)۔\"",""],[" (4)","s"]]]],"f":[["(4)","Muslim and Abu Dawood, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.262)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں ہم لوگ حضورؐ کے ساتھ سفر کرتے تھے۔ جب آپؐ کی نگاہ اس بستی پر پڑتی جس میں داخل ہونے کا ارادہ ہوتا تو یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ بَارِكْ لَنَا فِيهَا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تو ہمارے لیے اس بستی میں برکت نصیب فرما۔\" تین دفعہ کہتے اور یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ ٱرْزُقْنَا حَيَاهَا وَحَبِّبْنَا إِلَىٰ أَهْلِهَا وَحَبِّبْ صَالِحِي أَهْلِهَا إِلَيْنَا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تو ہمیں اسی بستی کی تر و تازگی نصیب فرما، بستی والوں کے دل میں ہماری محبت ڈال دے اور بستی کے نیک لوگوں کی محبت ہمیں نصیب فرما۔\"",""]]]],"f":[]},{"b":[["n",[["حضرت صہیبؓ","b"],[" فرماتے ہیں حضورؐ جب کسی بستی میں داخل ہونا چاہتے تو اسے دیکھتے ہی یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ رَبَّ ٱلسَّمَوَاتِ ٱلسَّبْعِ وَمَا أَظْلَلْنَ، وَرَبَّ ٱلرِّيَاحِ وَمَا ذَرَيْنَ، إِنَّا نَسْأَلُكَ خَيْرَ هَٰذِهِ ٱلْقَرْيَةِ وَخَيْرَ أَهْلِهَا وَنَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ أَهْلِهَا وَشَرِّ مَا فِيهَا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ساتوں آسمانوں اور اس تمام مخلوق کے رب جس پر یہ آسمان سایہ کر رہے ہیں اور ہواؤں کے اور ان چیزوں کے رب جن کو ہواؤں نے اڑایا! ہم تجھ سے اس بستی کی اور بستی والوں کی خیر مانگتے ہیں اور اس بستی کے شر سے اور بستی والوں کے شر سے اور جو کچھ اس بستی میں ہے اس کے شر سے تیری پناہ چاہتے ہیں۔\" جہاد فی سبیل ",""],["ٱللَّٰه","a"],[" کے دوران دعاؤں کے اہتمام کے باب میں حضورؐ کی سفر کی دعائیں گزر چکی ہیں۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani, whose narrators are those of authentic Ahaadeeth except Ataa bin Abi Marwaan and his father, both of whom are reliable, as confirmed by Haythami (Vol.10 Pg.135)."]]}]},"141":{"lead":[],"stories":[{"b":[["n",[["حضرت قزعہؒ","b"],[" کہتے ہیں مجھ سے حضرت ابن عمرؓ نے فرمایا آؤ میں تمہیں اس طرح رخصت کروں جس طرح حضورؐ نے مجھے رخصت کیا تھا اور پھر یہ کلمات کہے",""]]],["q",[["أَسْتَوْدِعُ ٱللَّهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ","a"]]],["p",[["ترجمہ: \"میں تمہارے دین کو اور تمہاری صفت امانت داری کو اور تمہارے ہر عمل کے آخری حصہ کو ",""],["ٱللَّٰه","a"],[" کے سپرد کرتا ہوں۔\"",""],[" (1)","s"]]]],"f":[["(1)","Abu Dawood (Vol.3 Pg.232)."]]},{"b":[["n",[["حضرت سالمؒ","b"],[" کہتے ہیں جب کوئی آدمی سفر میں جانے کا ارادہ کرتا تو حضرت ابن عمرؓ اس سے فرماتے میرے قریب آؤ میں تمہیں اس طرح رخصت کروں جس طرح حضورؐ ہمیں رخصت کیا کرتے تھے، پھر پچھلی حدیث جیسی دعا کر دی۔",""]]]],"f":[]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں ایک آدمی نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرا سفر میں جانے کا ارادہ ہے، آپ کچھ توشہ عنایت فرما دیں یعنی میرے لیے دعا فرما دیں۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" تمہیں تقویٰ کا توشہ دے۔ اس نے عرض کیا کچھ اور دعا فرما دیں۔ حضورؐ نے فرمایا اور ",""],["ٱللَّٰه","a"],[" تمہارے گناہ معاف کرے۔ اس نے پھر عرض کیا میرے ماں باپ آپ پر قربان ہوں کچھ اور دعا فرما دیں۔ حضورؐ نے فرمایا جہاں بھی تم ہو وہاں بھلائی کو تمہارے لیے آسان کر دے۔",""],[" (2)","s"]]]],"f":[["(2)","Tirmidhi (Vol.2 Pg.182)."]]},{"b":[["n",[["حضرت قتادہؓ","b"],[" فرماتے ہیں جب حضورؐ نے مجھے اپنی قوم کا امیر بنایا تو میں نے آپؐ کا ہاتھ پکڑ کر آپؐ کو رخصت کیا۔ آپؐ نے یہ دعا پڑھی",""]]],["q",[["جَعَلَ ٱللَّهُ ٱلتَّقْوَىٰ زَادَكَ وَغَفَرَ ذَنْبَكَ وَوَجَّهَكَ لِلْخَيْرِ حَيْثُمَا تَوَجَّهْتَ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" تعالیٰ تقویٰ کو تمہارا توشہ بنائے اور تمہارے گناہ معاف کرے اور جہاں بھی تم جاؤ وہاں تمہیں خیر کی توفیق عطا فرمائے۔\"",""],[" (3)","s"]]]],"f":[["(3)","Tabraani and Bazzaar from Hishaam bin Qataadah Ruhaawi; Haythami (Vol.10 Pg.131) has confirmed that their narrators are reliable."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں ایک آدمی نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرا سفر میں جانے کا ارادہ ہے، آپ مجھے کچھ وصیت فرما دیں۔ آپؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" کے ڈر کو اور ہر بلندی پر چڑھتے وقت تکبیر کہنے کو لازم پکڑے رکھو۔ جب وہ آدمی پشت پھیر کر چل دیا تو حضورؐ نے یہ دعا فرمائی",""]]],["q",[["ٱللَّهُمَّ ٱطْوِ لَهُ ٱلْبُعْدَ وَهَوِّنْ عَلَيْهِ ٱلسَّفَرَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اس کے سفر کی مسافت کو جلد طے کرا دے اور سفر اس پر آسان فرما دے۔\"",""],[" (4)","s"]]]],"f":[["(4)","Tirmidhi (Vol.2 Pg.182), who said that it is a hasan hadith."]]}]},"142":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوامامہؓ","b"],[" فرماتے ہیں جب حضورؐ کے سامنے سے دسترخوان اٹھا لیا جاتا تو آپؐ یہ دعا پڑھتے",""]]],["q",[["ٱلْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ غَيْرَ مُكْفًى وَلَا مُوَدَّعٍ وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا","a"]]],["p",[["ترجمہ: \"تمام تعریفیں ",""],["ٱللَّٰه","a"],[" کے لیے ہیں، ایسی تعریف جو بہت زیادہ ہو اور پاکیزہ اور بابرکت ہو، ہماری یہ تعریف کافی (اور تیرے شایان شان) نہیں ہو سکتی اور نہ ہم اسے کبھی چھوڑ سکتے ہیں اور نہ کبھی اس سے مستغنی ہو سکتے ہیں، اے ہمارے رب!\"",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari, Abu Dawood and Tirmidhi."]]},{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں حضورؐ جب کھاتے یا پیتے تو فرماتے",""]]],["q",[["ٱلْحَمْدُ لِلَّهِ ٱلَّذِي أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مِنَ ٱلْمُسْلِمِينَ","a"]]],["p",[["ترجمہ: \"تمام تعریفیں ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے ہمیں کھلایا پلایا اور ہمیں مسلمانوں میں سے بنایا۔\"",""],[" (2)","s"]]]],"f":[["(2)","Tirmidhi and Abu Dawood, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.264)."]]},{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں جب حضورؐ نیا کپڑا پہنتے تو یہ دعا فرماتے (ھذا کے بعد اس کپڑے کا نام لیتے، یعنی کرتا، عمامہ یا چادر وغیرہ)",""]]],["q",[["ٱللَّهُمَّ لَكَ ٱلْحَمْدُ أَنْتَ كَسَوْتَنِي هَٰذَا، أَسْأَلُكَ خَيْرَهُ وَخَيْرَ مَا صُنِعَ لَهُ وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تمام تعریفیں تیرے لیے ہیں، تو ہی نے مجھے یہ کپڑا پہنایا ہے، میں تجھ سے اس کپڑے کی خیر اور جس مقصد کے لیے اسے بنایا گیا ہے اس کی خیر مانگتا ہوں اور اس کے شر سے اور جس مقصد کے لیے اسے بنایا گیا ہے اس کے شر سے تیری پناہ چاہتا ہوں۔\"",""],[" (3)","s"]]]],"f":[["(3)","Tirmidhi and Abu Dawood, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.264)."]]}]},"143":{"lead":[],"stories":[{"b":[["n",[["حضرت طلحہؓ","b"],[" فرماتے ہیں جب نبی کریمؐ نیا چاند دیکھتے تو فرماتے",""]]],["q",[["ٱللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِٱلْيُمْنِ وَٱلْإِيمَانِ وَٱلسَّلَامَةِ وَٱلْإِسْلَامِ، رَبِّي وَرَبُّكَ ٱللَّهُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تو اس چاند کو ہم پر برکت اور ایمان کے ساتھ، سلامتی اور اسلام کے ساتھ نکال۔ (اے چاند!) میرا اور تیرا رب ",""],["ٱللَّٰه","a"],[" ہے۔\" حضرت ابن عمرؓ نے یہ الفاظ روایت کیے ہیں",""]]],["q",[["ٱللَّهُ أَكْبَرُ، ٱللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِٱلْأَمْنِ وَٱلْإِيمَانِ وَٱلسَّلَامَةِ وَٱلْإِسْلَامِ وَٱلتَّوْفِيقِ لِمَا تُحِبُّ وَتَرْضَىٰ، رَبُّنَا وَرَبُّكَ ٱللَّهُ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" سب سے بڑا ہے۔ اے ",""],["ٱللَّٰه","a"],["! اس چاند کو ہم پر امن و امان، سلامتی اور اسلام کے ساتھ اور اپنے محبوب اور پسندیدہ اعمال کی توفیق کے ساتھ نکال۔ (اے چاند!) ہمارا اور تیرا رب ",""],["ٱللَّٰه","a"],[" ہے۔\"",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Tirmidhi (Vol.2 Pg.183)."],["(2)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.4 Pg.326). Tabraani has also reported a similar narration from Ibn Umar, except that it does not mention 'Allahu Akbar' and has 'wal Imaan' in place of 'wal Amaan'. Haythami (Vol.10 Pg.139) has commented that Uthman bin Ibrahim Haatibi, who is weak, is in its chain."]]},{"b":[["n",[["حضرت رافع بن خدیجؓ","b"],[" فرماتے ہیں حضورؐ جب نیا چاند دیکھتے تو فرماتے",""]]],["q",[["هِلَالُ خَيْرٍ وَرُشْدٍ","a"]]],["p",[["ترجمہ: \"یہ خیر اور ہدایت کا چاند ہے۔\" پھر تین مرتبہ یہ کلمات کہتے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ هَٰذَا ٱلشَّهْرِ وَخَيْرِ ٱلْقَدَرِ وَأَعُوذُ بِكَ مِنْ شَرِّهِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے اس مہینے کی بھلائی اور تقدیر کی بھلائی مانگتا ہوں اور اس کے شر سے تیری پناہ چاہتا ہوں۔\"",""],[" (3)","s"]]]],"f":[["(3)","Tabraani, whose chain is hasan as confirmed by Haythami (Vol.10 Pg.139)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں نبی کریمؐ جب بادل گرجنے اور بجلی کڑکنے کی آواز سنتے تو فرماتے",""]]],["q",[["ٱللَّهُمَّ لَا تَقْتُلْنَا بِغَضَبِكَ وَلَا تُهْلِكْنَا بِعَذَابِكَ وَعَافِنَا قَبْلَ ذَلِكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ہمیں اپنے غضب سے قتل نہ فرما اور ہمیں اپنے عذاب سے ہلاک نہ فرما اور ہمیں اس سے پہلے ہی عافیت نصیب فرما۔\"",""],[" (4)","s"]]]],"f":[["(4)","Tirmidhi, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.264)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں جب تیز ہوا چلتی تو نبی کریمؐ یہ دعا مانگتے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا فِيهَا وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيهَا وَشَرِّ مَا أُرْسِلَتْ بِهِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے اس ہوا کی خیر اور جو کچھ اس میں ہے اس کی خیر اور جو کچھ دے کر یہ ہوا بھیجی گئی اس کی خیر مانگتا ہوں اور تجھ سے اس ہوا کے شر سے اور جو کچھ اس میں ہے اس کے شر سے اور جو کچھ دے کر یہ ہوا بھیجی گئی ہے اس کے شر سے پناہ مانگتا ہوں۔\"",""],[" (5)","s"]]]],"f":[["(5)","Bukhaari, Muslim and Tirmidhi."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں جب نبی کریمؐ آسمان کے کنارے میں اٹھتا ہوا بادل دیکھتے تو کام چھوڑ دیتے اور اگر نماز میں ہوتے تو اسے مختصر کر دیتے، پھر یہ کلمات فرماتے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّهَا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اس بادل کے شر سے تیری پناہ چاہتا ہوں۔\" اگر بارش ہو جاتی تو فرماتے",""]]],["q",[["ٱللَّهُمَّ صَيِّبًا هَنِيئًا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اسے بہت برسنے والا لیکن بابرکت اور نفع بخش بنا دے۔\"",""],[" (6)","s"]]]],"f":[["(6)","Abu Dawood, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.265)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ جب آسمان کے کسی کنارے پر گہرے بادل دیکھتے تو جس کام میں بھی ہوتے اسے چھوڑ دیتے چاہے وہ نماز ہی کیوں نہ ہو اور اس بادل کی طرف متوجہ ہو جاتے اور فرماتے",""]]],["q",[["ٱللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ شَرِّ مَا أُرْسِلَ بِهِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ہم اس چیز کے شر سے تیری پناہ چاہتے ہیں جسے دے کر اس بادل کو بھیجا گیا ہے۔\" پھر اگر بارش ہو جاتی تو دو تین دفعہ فرماتے",""]]],["q",[["ٱللَّهُمَّ صَيِّبًا نَافِعًا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اسے بہت برسنے والا اور نفع دینے والا بنا دے۔\" اگر ",""],["ٱللَّٰه","a"],[" تعالیٰ اس بادل کو ہٹا دیتے اور بارش نہ ہوتی تو اس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ کی حمد و ثنا بیان کرتے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.290)."]]},{"b":[["n",[["حضرت سلمہ بن اکوعؓ","b"],[" فرماتے ہیں جب ہوا تیز چلتی تو حضورؐ فرمایا کرتے",""]]],["q",[["ٱللَّهُمَّ لَقْحًا لَا عَقِيمًا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اسے ایسی ہوا بنا جس سے درختوں پر خوب پھل لگیں اور بانجھ نہ بنا (جس سے کوئی فائدہ نہ ہو)۔\"",""],[" (8)","s"]]]],"f":[["(8)","Tabraani in his Kabeer and Awsat; Haythami (Vol.10 Pg.135) has said that its narrators are those of authentic Ahaadeeth except Mugheerah bin Abdur Rahman who is reliable."]]}]},"144":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ نبی کریمؐ یہ دعا مانگا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ ٱلْهُدَىٰ وَٱلتُّقَىٰ وَٱلْعَفَافَ وَٱلْغِنَىٰ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے ہدایت، تقویٰ، پاک دامنی اور دل کا غنا مانگتا ہوں۔\"",""],[" (1)","s"]]]],"f":[["(1)","Muslim."]]},{"b":[["n",[["حضرت ابوموسیٰ اشعریؓ","b"],[" فرماتے ہیں نبی کریمؐ یہ دعا مانگا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لِي خَطِيئَتِي وَجَهْلِي وَإِسْرَافِي فِي أَمْرِي وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، ٱللَّهُمَّ ٱغْفِرْ لِي جِدِّي وَهَزْلِي وَخَطَئِي وَعَمْدِي وَكُلُّ ذَلِكَ عِنْدِي، ٱللَّهُمَّ ٱغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ ٱلْمُقَدِّمُ وَأَنْتَ ٱلْمُؤَخِّرُ وَأَنْتَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میری خطا اور میرے نادانی والے کام اور کاموں میں میرا اپنی حد سے بڑھ جانا اور وہ گناہ جنہیں تو مجھ سے زیادہ جانتا ہے سب معاف فرما۔ اور میرے وہ گناہ جو سچ مچ ارادے سے سرزد ہوئے یا ہنسی مذاق میں ہو گئے یا غلطی سے ہو گئے یا جان بوجھ کر قصداً کیے وہ سب معاف فرما اور یہ سب طرح کے گناہ میرے پاس ہیں، اے ",""],["ٱللَّٰه","a"],["! میرے اگلے پچھلے تمام گناہ معاف فرما اور جو گناہ چھپ کر کیے اور جو علی الاعلان کیے وہ بھی معاف فرما اور جن گناہوں کو تو مجھ سے زیادہ جانتا ہے وہ بھی معاف فرما۔ تو ہی آگے کرنے والا اور پیچھے کرنے والا ہے اور تو ہر چیز پر قدرت رکھنے والا ہے۔\"",""],[" (2)","s"]]]],"f":[["(2)","Muslim and Bukhaari."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ یہ دعا مانگا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ أَصْلِحْ لِي دِينِيَ ٱلَّذِي هُوَ عِصْمَةُ أَمْرِي وَأَصْلِحْ لِي دُنْيَايَ ٱلَّتِي فِيهَا مَعَاشِي وَأَصْلِحْ لِي آخِرَتِيَ ٱلَّتِي فِيهَا مَعَادِي وَٱجْعَلِ ٱلْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ وَٱجْعَلِ ٱلْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میرا وہ دین سنوار دے جس سے میرے تمام کاموں کی حفاظت ہوتی ہے اور میری وہ دنیا درست فرما دے جس سے میری معاش کا تعلق ہے اور میری آخرت کو بھی ٹھیک کر دے جہاں مجھے لوٹ کر جانا ہے اور زندگی کو میرے لیے ہر خیر میں بڑھنے کا ذریعہ بنا اور موت کو میرے لیے ہر شر سے راحت پانے کا ذریعہ بنا۔\"",""],[" (3)","s"]]]],"f":[["(3)","Muslim."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضورؐ یہ دعا مانگا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ لَكَ أَسْلَمْتُ وَبِكَ آمَنْتُ وَعَلَيْكَ تَوَكَّلْتُ وَإِلَيْكَ أَنَبْتُ وَبِكَ خَاصَمْتُ، ٱللَّهُمَّ إِنِّي أَعُوذُ بِعِزَّتِكَ لَا إِلَٰهَ إِلَّا أَنْتَ أَنْ تُضِلَّنِي، أَنْتَ ٱلْحَيُّ ٱلَّذِي لَا يَمُوتُ وَٱلْجِنُّ وَٱلْإِنْسُ يَمُوتُونَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تیرا فرماں بردار ہو گیا اور تجھ پر ایمان لایا اور تجھ پر ہی بھروسہ کیا اور تیری طرف ہی متوجہ ہوا اور تیری مدد سے ہی میں نے اہل باطل سے جھگڑا کیا۔ اے ",""],["ٱللَّٰه","a"],["! میں اس بات سے تیری عزت کی پناہ چاہتا ہوں کہ تو مجھے گمراہ کر دے۔ تیرے سوا کوئی معبود نہیں، تو ہی وہ ذات ہے جو ہمیشہ زندہ رہے گی اور اسے موت نہیں آئے گی، باقی تمام جنات اور انسان ایک دن مر جائیں گے۔\"",""],[" (4)","s"]]]],"f":[["(4)","Muslim and Bukhaari."]]},{"b":[["n",[["حضرت ام سلمہؓ","b"],[" فرماتی ہیں حضورؐ اکثر یہ دعا مانگا کرتے تھے",""]]],["q",[["يَا مُقَلِّبَ ٱلْقُلُوبِ ثَبِّتْ قَلْبِي عَلَىٰ دِينِكَ","a"]]],["p",[["ترجمہ: \"اے دلوں کو پلٹنے والے! میرے دل کو اپنے دین پر جمائے رکھ۔\"",""],[" (5)","s"]]]],"f":[["(5)","Muslim. Tirmidhi has also reported it and said that it is a hasan hadith."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ عَافِنِي فِي جَسَدِي وَعَافِنِي فِي بَصَرِي وَٱجْعَلْهُ ٱلْوَارِثَ مِنِّي، لَا إِلَٰهَ إِلَّا ٱللَّهُ ٱلْحَلِيمُ ٱلْكَرِيمُ، سُبْحَانَ ٱللَّهِ رَبِّ ٱلْعَرْشِ ٱلْعَظِيمِ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَالَمِينَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! مجھے جسم میں اور نگاہ میں عافیت نصیب فرما اور اس نگاہ کو موت تک باقی رکھ۔ تیرے سوا کوئی معبود نہیں، تو بردبار اور کریم ہے۔ میں ",""],["ٱللَّٰه","a"],[" کی پاکی بیان کرتا ہوں جو عرش عظیم کا رب ہے اور تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جو تمام جہانوں کا پالنے والا ہے۔\"",""],[" (6)","s"]]]],"f":[["(6)","Tirmidhi."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں نبی کریمؐ دعا میں یہ کہا کرتے تھے",""]]],["q",[["رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ وَٱنْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ وَٱمْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ وَٱهْدِنِي وَيَسِّرِ ٱلْهُدَىٰ لِي وَٱنْصُرْنِي عَلَىٰ مَنْ بَغَىٰ عَلَيَّ، رَبِّ ٱجْعَلْنِي لَكَ شَاكِرًا لَكَ ذَاكِرًا لَكَ رَاهِبًا لَكَ مِطْوَاعًا إِلَيْكَ مُخْبِتًا أَوْ مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي وَٱغْسِلْ حَوْبَتِي وَأَجِبْ دَعْوَتِي وَثَبِّتْ حُجَّتِي وَٱهْدِ قَلْبِي وَسَدِّدْ لِسَانِي وَٱسْلُلْ سَخِيمَةَ قَلْبِي","a"]]],["p",[["ترجمہ: \"اے میرے رب! میری اعانت فرما اور میرے خلاف کسی کی اعانت نہ فرما اور میری مدد فرما اور میرے خلاف کسی کی مدد نہ فرما اور میرے لیے تدبیر فرما اور میرے خلاف کوئی تدبیر نہ فرما اور مجھے ہدایت نصیب فرما اور ہدایت پر قائم رہنے کو میرے لیے آسان فرما اور جو مجھ پر زیادتی کرے اس کے خلاف میری مدد فرما۔ اے میرے رب! تو مجھے اپنا شکر کرنے والا، اپنا ذکر کرنے والا، اپنے سے ڈرنے والا، اپنا فرماں بردار اور اپنی طرف متوجہ ہونے والا بنا دے۔ اے میرے رب! میری توبہ قبول فرما، میرے گناہ دھو دے اور میری دعا قبول فرما اور میری دلیل کو مضبوط فرما اور میرے دل کو ہدایت نصیب فرما اور میری زبان کو ٹھیک رکھ اور میرے دل کے کینہ اور کھوٹ کو نکال دے۔\"",""],[" (7)","s"]]]],"f":[["(7)","Tirmidhi, Abu Dawood and Ibn Majah. Tirmidhi said that it is a hasan saheeh hadith."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں حضورؐ یہ دعا بھی مانگا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنَّا نَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ وَعَزَائِمَ مَغْفِرَتِكَ وَٱلسَّلَامَةَ مِنْ كُلِّ إِثْمٍ وَٱلْغَنِيمَةَ مِنْ كُلِّ بِرٍّ وَٱلْفَوْزَ بِٱلْجَنَّةِ وَٱلنَّجَاةَ مِنَ ٱلنَّارِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ہم تجھ سے تیری رحمت کو واجب کرنے والے اعمال اور تیری مغفرت کو ضروری بنانے والے اسباب اور ہر گناہ سے حفاظت اور ہر نیکی کی توفیق اور جنت میں داخلہ کی کامیابی اور دوزخ سے نجات مانگتے ہیں۔\"",""],[" (8)","s"]]]],"f":[["(8)","Haakim, who graded it authentic on the conditions of Muslim, as quoted in Al Adhkaar of Nawawi (Pg.398)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں حضورؐ یہ دعا مانگا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لَنَا ذُنُوبَنَا وَظُلْمَنَا وَهَزْلَنَا وَجِدَّنَا وَعَمْدَنَا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ہمارے تمام گناہوں کو معاف فرما۔ ہمارے ظلم اور ہنسی مذاق کے گناہوں کو اور شعوری گناہوں کو اور جو گناہ جان بوجھ کر کیے ان سب کو معاف فرما۔\"",""],[" (9)","s"]]]],"f":[["(9)","Ahmad and Tabraani; Haythami (Vol.10 Pg.172) has said that both chains are hasan. Ahmad and Tabraani, and also Bazzaar, have narrators who are those of authentic Ahaadeeth except Awn Uqayli who is reliable."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ أَحْسَنْتَ خَلْقِي فَأَحْسِنْ خُلُقِي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تو نے میری صورت بھی اچھی بنائی اب سیرت بھی اچھی بنا دے۔\"",""],[" (10)","s"]]]],"f":[["(10)","Ahmad, whose narrators are those of authentic Ahaadeeth as confirmed by Haythami (Vol.10 Pg.173). Abu Ya'la has also reported a similar narration from Ibn Mas'ood with a sound chain."]]},{"b":[["n",[["حضرت ام سلمہؓ","b"],[" فرماتی ہیں حضورؐ فرمایا کرتے تھے",""]]],["q",[["رَبِّ ٱغْفِرْ وَٱرْحَمْ وَٱهْدِنِي ٱلسَّبِيلَ ٱلْأَقْوَمَ","a"]]],["p",[["ترجمہ: \"اے میرے رب! مغفرت فرما اور رحم فرما اور مجھے سیدھے اور پختہ راستہ پر چلا۔\"",""],[" (11)","s"]]]],"f":[["(11)","Ahmad and Abu Ya'la with two hasan chains."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں حضورؐ فرمایا کرتے تھے",""]]],["q",[["يَا وَلِيَّ ٱلْإِسْلَامِ وَأَهْلِهِ ثَبِّتْنِي بِهِ حَتَّىٰ أَلْقَاكَ","a"]]],["p",[["ترجمہ: \"اے اسلام کے والی اور اسلام والوں کے مددگار! مجھے اپنی ملاقات کے وقت یعنی موت تک اسلام پر جمائے رکھ۔\"",""],[" (12)","s"]]]],"f":[["(12)","Tabraani in his Awsat, whose narrators are reliable as confirmed by Haythami (Vol.10 Pg.172 and 174)."]]},{"b":[["n",[["حضرت بسر بن ابی ارطاۃؓ","b"],[" فرماتے ہیں میں نے حضورؐ کو یہ دعا مانگتے ہوئے سنا",""]]],["q",[["ٱللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي ٱلْأُمُورِ كُلِّهَا وَأَجِرْنَا مِنْ خِزْيِ ٱلدُّنْيَا وَعَذَابِ ٱلْآخِرَةِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تمام کاموں میں ہمارا انجام اچھا فرما اور ہمیں دنیا کی رسوائی سے اور آخرت کے عذاب سے محفوظ فرما۔\" طبرانی کی روایت میں اس کے بعد یہ بھی ہے کہ حضورؐ نے فرمایا جو یہ دعا مانگتا رہے گا وہ آزمائش میں مبتلا ہونے سے پہلے ہی مر جائے گا۔",""],[" (13)","s"]]]],"f":[["(13)","Ahmad and Tabraani; Haythami (Vol.10 Pg.178) has said that the narrators of Ahmad's chain and one of Tabraani's chains are reliable."]]},{"b":[["n",[["حضرت ابوبصرہؓ","b"],[" فرماتے ہیں حضورؐ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ غِنَايَ وَغِنَىٰ مَوْلَايَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے اپنے غنا اور اپنے ہر تعلق والے کے غنا کا سوال کرتا ہوں۔\"",""],[" (14)","s"]]]],"f":[["(14)","Ahmad and Tabraani; Haythami (Vol.10 Pg.178) has said that the narrators of one of Ahmad's chains are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت ثوبانؓ","b"],[" فرماتے ہیں حضورؐ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ ٱلطَّيِّبَاتِ وَتَرْكَ ٱلْمُنْكَرَاتِ وَحُبَّ ٱلْمَسَاكِينِ وَأَنْ تَغْفِرَ لِي وَتَرْحَمَنِي وَأَنْ تَتُوبَ عَلَيَّ، وَإِذَا أَرَدْتَ بِعِبَادِكَ فِتْنَةً فَٱقْبِضْنِي غَيْرَ مَفْتُونٍ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے پاکیزہ چیزوں اور منکرات کے چھوڑنے کی ہمت اور مسکینوں کی محبت مانگتا ہوں اور یہ بھی مانگتا ہوں کہ تو میری مغفرت فرما دے اور مجھ پر رحم فرمائے اور میری توبہ قبول فرما لے اور یہ بھی کہ اگر کسی وقت تو اپنے بندوں کو آزمائش میں ڈالنا چاہے تو مجھے اس آزمائش میں ڈالے بغیر اپنے پاس بلا لے۔\"",""],[" (15)","s"]]]],"f":[["(15)","Bazzaar; Haythami (Vol.10 Pg.181) has said that its chain is hasan."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ ٱجْعَلْ أَوْسَعَ رِزْقِكَ عَلَيَّ عِنْدَ كِبَرِ سِنِّي وَٱنْقِطَاعِ عُمُرِي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! بڑھاپے میں اور اخیر عمر میں مجھے سب سے زیادہ فراخ روزی عطا فرما۔\"",""],[" (16)","s"]]]],"f":[["(16)","Tabraani, whose chain is hasan as confirmed by Haythami (Vol.10 Pg.182)."]]}]},"145":{"lead":[],"stories":[{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ جامع دعائیں پسند فرماتے تھے اور دوسری دعائیں چھوڑ دیتے تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.291)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں ایک مرتبہ حضرت ابوبکرؓ حضورؐ کے پاس آئے اور انہوں نے مجھ سے چھپا کر حضورؐ سے کوئی بات کرنی چاہی، میں نماز پڑھ رہی تھی۔ حضورؐ نے مجھ سے کہا اے عائشہ! کامل اور جامع دعائیں کیا کرو۔ نماز سے فارغ ہو کر میں نے ان دعاؤں کے بارے میں پوچھا، حضورؐ نے فرمایا یوں کہا کرو",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ ٱلْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوذُ بِكَ مِنَ ٱلشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَسْأَلُكَ ٱلْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوذُ بِكَ مِنَ ٱلنَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ مِنْهُ عَبْدُكَ وَرَسُولُكَ مُحَمَّدٌ صَلَّى ٱللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَسْتَعِيذُكَ مِمَّا ٱسْتَعَاذَكَ مِنْهُ عَبْدُكَ وَرَسُولُكَ مُحَمَّدٌ صَلَّى ٱللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَسْأَلُكَ مَا قَضَيْتَ لِي مِنْ أَمْرٍ أَنْ تَجْعَلَ عَاقِبَتَهُ رَشَدًا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے ہر قسم کی خیر، جلدی آنے والی بھی اور دیر سے آنے والی بھی، جو میں جانتا ہوں وہ بھی اور جو نہیں جانتا وہ بھی مانگتا ہوں اور ہر قسم کے شر سے تیری پناہ چاہتا ہوں چاہے وہ شر جلدی آنے والا ہو یا دیر سے آنے والا ہو، چاہے میں اس کو جانتا ہوں یا نہ جانتا ہوں اور میں تجھ سے جنت اور ہر اس قول و فعل کی توفیق مانگتا ہوں جو جنت کے قریب کرے اور دوزخ کی آگ سے اور ہر اس قول و فعل سے تیری پناہ چاہتا ہوں جو دوزخ کے قریب کرے اور میں تجھ سے ہر وہ خیر مانگتا ہوں جو تجھ سے تیرے بندے اور رسول حضرت محمدؐ نے مانگی ہے اور ہر اس چیز سے تیری پناہ چاہتا ہوں جس سے تیرے بندے اور رسول حضرت محمدؐ نے پناہ چاہی اور میں تجھ سے اس بات کا سوال کرتا ہوں کہ جس امر کا تو میرے لیے فیصلہ کرے اس کا انجام میرے لیے اچھا کر دے۔\"",""],[" (2)","s"]]]],"f":[["(2)","Haakim, as quoted in Kanzul Ummaal (Vol.1 Pg.306). Ahmad and Ibn Majah have reported a similar narration from Aa'isha. Haakim said that its chain is authentic, as quoted in Al Adhkaar of Nawawi (Pg.506)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ میرے پاس تشریف لائے، میں نماز پڑھ رہی تھی، آپ کو کچھ کام تھا، مجھے نماز میں دیر ہو گئی۔ آپؐ نے فرمایا اے عائشہ! مجمل اور جامع دعا کیا کرو۔ میں نے نماز سے فارغ ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مجمل اور جامع دعا کیا ہے؟ آپؐ نے فرمایا یہ کہا کرو، پھر پچھلی دعا ذکر کی۔",""],[" (3)","s"]]]],"f":[["(3)","Bukhaari in Adabul Mufrad (Pg.94)."]]},{"b":[["n",[["حضرت ابوامامہؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ نے بہت زیادہ دعا مانگی لیکن ہمیں اس میں سے کچھ یاد نہ رہا۔ ہم نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپ نے بہت زیادہ دعا مانگی لیکن ہمیں اس میں سے کچھ یاد نہ رہا۔ حضورؐ نے فرمایا کیا میں تمہیں کوئی ایسی جامع دعا نہ بتا دوں جس میں یہ سب کچھ آ جائے؟ تم یہ دعا مانگا کرو",""]]],["q",[["ٱللَّهُمَّ إِنَّا نَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ مِنْهُ نَبِيُّكَ مُحَمَّدٌ صَلَّى ٱللَّهُ عَلَيْهِ وَسَلَّمَ وَنَعُوذُ بِكَ مِنْ شَرِّ مَا ٱسْتَعَاذَ مِنْهُ نَبِيُّكَ مُحَمَّدٌ صَلَّى ٱللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَنْتَ ٱلْمُسْتَعَانُ وَعَلَيْكَ ٱلْبَلَاغُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِٱللَّهِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ہم تجھ سے وہ تمام بھلائیاں مانگتے ہیں جو تجھ سے تیرے نبی حضرت محمدؐ نے مانگی ہیں اور ان تمام چیزوں سے تیری پناہ مانگتے ہیں جن سے تیرے نبی حضرت محمدؐ نے پناہ مانگی ہے اور تو ہی وہ ذات ہے جس سے مدد مانگی جاتی ہے اور (ہمیں مقصود تک) پہنچانا (تیرے فضل سے) تیرے ہی ذمہ ہے، برائیوں سے بچنے کی طاقت اور نیکیاں کرنے کی قوت تیری توفیق سے ہی ملتی ہے۔\"",""],[" (4)","s"]]]],"f":[["(4)","Tirmidhi (Vol.2 Pg.190), who said that it is a hasan ghareeb hadith. Bukhaari has also reported a similar narration in Adabul Mufrad (Pg.99)."]]}]},"146":{"lead":[],"stories":[{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں حضورؐ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلْعَجْزِ وَٱلْكَسَلِ وَٱلْجُبْنِ وَٱلْهَرَمِ وَٱلْبُخْلِ وَأَعُوذُ بِكَ مِنْ عَذَابِ ٱلْقَبْرِ وَأَعُوذُ بِكَ مِنْ فِتْنَةِ ٱلْمَحْيَا وَٱلْمَمَاتِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں عاجز ہو جانے سے، کاہلی سے، بزدلی سے، زیادہ بوڑھا ہو جانے سے اور کنجوسی سے تیری پناہ چاہتا ہوں اور عذاب قبر سے تیری پناہ چاہتا ہوں اور زندگی اور موت کے فتنے سے تیری پناہ چاہتا ہوں۔\" اور ایک روایت میں ہے",""]]],["q",[["وَضَلَعِ ٱلدَّيْنِ وَغَلَبَةِ ٱلرِّجَالِ","a"]]],["p",[["ترجمہ: \"کہ قرض کے بوجھ سے اور لوگوں کے غلبہ اور دباؤ سے (تیری پناہ چاہتا ہوں)۔\"",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari and Muslim."]]},{"b":[["n",[["مسلم میں ",""],["حضرت عائشہؓ","b"],[" کی روایت ہے کہ نبی کریمؐ دعا میں فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں نے اب تک جو کیا اس کے شر سے بھی پناہ مانگتا ہوں اور جو نہیں کیا اس کے شر سے بھی پناہ مانگتا ہوں۔\"",""]]]],"f":[]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں حضورؐ کی ایک دعا یہ بھی تھی",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ وَتَحَوُّلِ عَافِيَتِكَ وَفُجَاءَةِ نِقْمَتِكَ وَجَمِيعِ سَخَطِكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تیری نعمت کے چلے جانے سے، تیری دی ہوئی عافیت کے ہٹ جانے سے اور تیری اچانک پکڑ سے اور تیری ہر طرح کی ناراضگی سے پناہ چاہتا ہوں۔\"",""]]]],"f":[]},{"b":[["n",[["حضرت زید بن ارقمؓ","b"],[" فرماتے ہیں میں تمہیں وہی دعا بتانے لگا ہوں جو حضورؐ مانگا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلْعَجْزِ وَٱلْكَسَلِ وَٱلْجُبْنِ وَٱلْبُخْلِ وَٱلْهَمِّ وَعَذَابِ ٱلْقَبْرِ، ٱللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا أَنْتَ وَلِيُّهَا وَمَوْلَاهَا، ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! عاجزی، کاہلی، بزدلی، کنجوسی، رنج و غم اور عذاب قبر سے تیری پناہ چاہتا ہوں۔ اے ",""],["ٱللَّٰه","a"],["! میرے نفس کو تقویٰ عطا فرما اور اسے پاک صاف کر دے، تو ہی بہترین پاک صاف کرنے والا ہے، تو ہی اس کا مالک اور آقا ہے۔ اے ",""],["ٱللَّٰه","a"],["! میں تیری پناہ چاہتا ہوں اس علم سے جو (دین و دنیا میں) نفع نہ دے اور اس دل سے جس میں خشوع نہ ہو اور حریص نفس سے جو کبھی سیر نہ ہو اور اس دعا سے جو قبول نہ ہو۔\"",""]]]],"f":[]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں نبی کریمؐ یہ دعا فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ ٱلنَّارِ وَعَذَابِ ٱلنَّارِ وَمِنْ شَرِّ ٱلْغِنَىٰ وَٱلْفَقْرِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! آگ کے فتنے سے، آگ کے عذاب سے اور مالداری اور فقیری کے شر سے تیری پناہ چاہتا ہوں۔\"",""],[" (2)","s"]]]],"f":[["(2)","Abu Dawood, Tirmidhi, Nasa'ee and Ibn Majah with authentic chains."]]},{"b":[["n",[["حضرت قطبہ بن مالکؓ","b"],[" فرماتے ہیں نبی کریمؐ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مُنْكَرَاتِ ٱلْأَخْلَاقِ وَٱلْأَعْمَالِ وَٱلْأَهْوَاءِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں برے اخلاق و اعمال اور بری نفسانی خواہشات سے تیری پناہ چاہتا ہوں۔\"",""],[" (3)","s"]]]],"f":[["(3)","Tirmidhi, who said that it is a hasan hadith."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں حضورؐ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلْبَرَصِ وَٱلْجُنُونِ وَٱلْجُذَامِ وَسَيِّئِ ٱلْأَسْقَامِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! برص (پھلبہری) سے، دیوانگی سے، کوڑھ پن سے اور تمام بری اور موذی بیماریوں سے تیری پناہ چاہتا ہوں۔\"",""],[" (4)","s"]]]],"f":[["(4)","Abu Dawood and Nasa'ee with two authentic chains."]]},{"b":[["n",[["حضرت ابوالیسر صحابیؓ","b"],[" فرماتے ہیں حضورؐ یہ دعا مانگا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلْهَدْمِ وَأَعُوذُ بِكَ مِنَ ٱلتَّرَدِّي وَأَعُوذُ بِكَ مِنَ ٱلْغَرَقِ وَٱلْحَرَقِ وَٱلْهَرَمِ، وَأَعُوذُ بِكَ أَنْ يَتَخَبَّطَنِي ٱلشَّيْطَانُ عِنْدَ ٱلْمَوْتِ، وَأَعُوذُ بِكَ أَنْ أَمُوتَ فِي سَبِيلِكَ مُدْبِرًا، وَأَعُوذُ بِكَ أَنْ أَمُوتَ لَدِيغًا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! کسی عمارت کے نیچے دب کر مرنے سے، کبھی اونچی جگہ سے گر کر مرنے سے اور ڈوب کر یا جل کر مرنے سے اور حد سے زیادہ بوڑھا ہونے سے تیری پناہ چاہتا ہوں اور اس بات سے تیری پناہ چاہتا ہوں کہ موت کے وقت شیطان مجھے خبطی بنا دے یعنی عقل خراب کر کے گمراہ کر دے اور تیرے راستہ میں میدان جنگ سے پیٹھ پھیر کر بھاگتے ہوئے مرنے سے تیری پناہ چاہتا ہوں اور سانپ وغیرہ کے ڈسنے سے مرنے سے تیری پناہ چاہتا ہوں۔\"",""],[" (5)","s"]]]],"f":[["(5)","Abu Dawood and Nasa'ee; this is the wording of Abu Dawood."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلْجُوعِ فَإِنَّهُ بِئْسَ ٱلضَّجِيعُ وَأَعُوذُ بِكَ مِنَ ٱلْخِيَانَةِ فَإِنَّهَا بِئْسَتِ ٱلْبِطَانَةُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں بھوک سے تیری پناہ چاہتا ہوں کیونکہ بھوک بہت بری ساتھی ہے اور خیانت سے تیری پناہ چاہتا ہوں اس لیے کہ یہ بدترین خصلت ہے۔\"",""],[" (6)","s"],[" (7)","s"]]]],"f":[["(6)","Abu Dawood and Nasa'ee with an authentic chain, as quoted in Al Adhkaar (Pg.399)."],["(7)","Abu Dawood and Nasa'ee, as quoted in Taysirul Wusool (Vol.2 Pg.83)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلشِّقَاقِ وَٱلنِّفَاقِ وَسُوءِ ٱلْأَخْلَاقِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں آپس کے جھگڑے، فساد، نفاق اور برے اخلاق سے تیری پناہ چاہتا ہوں۔\"",""]]]],"f":[]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں نبی کریمؐ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلْعَجْزِ وَٱلْكَسَلِ وَأَعُوذُ بِكَ مِنَ ٱلْقَسْوَةِ وَٱلْغَفْلَةِ وَٱلْعَيْلَةِ وَٱلذِّلَّةِ وَٱلْمَسْكَنَةِ، وَأَعُوذُ بِكَ مِنَ ٱلْفُسُوقِ وَٱلشِّقَاقِ وَٱلنِّفَاقِ وَٱلسُّمْعَةِ وَٱلرِّيَاءِ، وَأَعُوذُ بِكَ مِنَ ٱلصَّمَمِ وَٱلْبَكَمِ وَٱلْجُنُونِ وَٱلْجُذَامِ وَسَيِّئِ ٱلْأَسْقَامِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! عاجز ہو جانے اور سستی سے تیری پناہ چاہتا ہوں اور دل کی سختی، غفلت، فقیری، ذلت و مسکنت سے تیری پناہ چاہتا ہوں، فسق و فجور، آپس کی لڑائی جھگڑے، نفاق اور شہرت و ریا سے تیری پناہ چاہتا ہوں، بہرہ اور گونگا ہو جانے سے، پاگل پن، کوڑھ اور تمام بری بیماریوں سے تیری پناہ چاہتا ہوں۔\"",""],[" (8)","s"]]]],"f":[["(8)","Tabraani in his Sagheer; Haythami (Vol.10 Pg.133) has said that its narrators are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت عقبہ بن عامرؓ","b"],[" فرماتے ہیں نبی کریمؐ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ يَوْمِ ٱلسُّوءِ وَمِنْ لَيْلَةِ ٱلسُّوءِ وَمِنْ سَاعَةِ ٱلسُّوءِ وَمِنْ صَاحِبِ ٱلسُّوءِ وَمِنْ جَارِ ٱلسُّوءِ فِي دَارِ ٱلْمُقَامَةِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! برے دن سے، بری رات سے، بری گھڑی سے، برے ساتھی سے اور (مستقل رہائش والے) وطن کے برے پڑوسی سے میں تیری پناہ چاہتا ہوں۔\"",""],[" (9)","s"]]]],"f":[["(9)","Tabraani also; Haythami (Vol.10 Pg.144) has said that its narrators are those of authentic Ahaadeeth except Bishr bin Thaabit Bazzaar who is reliable."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" فرماتے ہیں حضورؐ پانچ چیزوں سے ",""],["ٱللَّٰه","a"],[" کی پناہ اس طرح مانگا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلْبُخْلِ وَٱلْجُبْنِ وَفِتْنَةِ ٱلصَّدْرِ وَعَذَابِ ٱلْقَبْرِ وَسُوءِ ٱلْعُمُرِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! کنجوسی سے، بزدلی سے، سینے کے فتنہ سے، عذاب قبر سے اور بری عمر یعنی زیادہ بوڑھا ہو جانے سے تیری پناہ چاہتا ہوں۔\"",""],[" (10)","s"]]]],"f":[["(10)","Ahmad, Ibn Abi Shaybah, Abu Dawood, Nasa'ee and others."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں نبی کریمؐ حضرت حسنؓ اور حضرت حسینؓ کو ان کلمات سے ",""],["ٱللَّٰه","a"],[" کی پناہ میں دیا کرتے تھے",""]]],["q",[["أُعِيذُكُمَا بِكَلِمَاتِ ٱللَّهِ ٱلتَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ","a"]]],["p",[["ترجمہ: \"میں تم دونوں کو ہر شیطان سے، موذی زہریلے جانوروں سے اور ہر لگنے والی بری نظر سے ",""],["ٱللَّٰه","a"],[" کے ان کلمات کی پناہ میں دیتا ہوں جو پورے ہیں۔\"",""],[" (11)","s"]]]],"f":[["(11)","Abu Nu'aym in his Hilyah, as quoted in Kanzul Ummaal (Vol.1 Pg.212)."]]}]},"147":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوالتیاحؒ","b"],[" کہتے ہیں حضرت عبدالرحمٰن بن خنبش تمیمیؓ عمر رسیدہ ہو چکے تھے، میں نے ان سے پوچھا کیا آپ نے حضورؐ کا زمانہ پایا ہے؟ انہوں نے کہا جی ہاں۔ میں نے کہا جس رات جنات نے حضورؐ کے ساتھ مکر و فریب کرنا چاہا تھا اس رات حضورؐ نے کیا کیا تھا؟ انہوں نے کہا اس رات شیاطین گھاٹیوں اور پہاڑی راستوں سے اتر کر حضورؐ کے پاس آنے لگے۔ ان میں سے ایک شیطان کے ہاتھ میں آگ کا ایک شعلہ تھا جس سے وہ حضورؐ کا چہرہ انور جلانا چاہتا تھا۔ اس پر حضرت جبرئیل علیہ السلام آسمان سے اتر کر حاضر خدمت ہوئے اور عرض کیا اے محمدؐ! پڑھیے۔ حضورؐ نے فرمایا کیا پڑھوں؟ انہوں نے کہا یہ دعا پڑھیے",""]]],["q",[["أَعُوذُ بِكَلِمَاتِ ٱللَّهِ ٱلتَّامَّةِ مِنْ شَرِّ مَا خَلَقَ وَذَرَأَ وَبَرَأَ وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ ٱلسَّمَاءِ وَمِنْ شَرِّ مَا يَعْرُجُ فِيهَا وَمِنْ شَرِّ فِتَنِ ٱللَّيْلِ وَٱلنَّهَارِ وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلَّا طَارِقًا يَطْرُقُ بِخَيْرٍ يَا رَحْمَٰنُ","a"]]],["p",[["ترجمہ: \"میں ",""],["ٱللَّٰه","a"],[" کے کامل کلمات کی پناہ لیتا ہوں ان تمام چیزوں کے شر سے جنہیں اس نے پیدا فرما کر پھیلا دیا اور جنہیں اس نے بے مثال بنایا اور ہر اس چیز کے شر سے جو آسمان سے اترتی ہے اور ہر اس چیز کے شر سے جو آسمان میں چڑھتی ہے اور رات اور دن کے فتنوں سے اور رات کو پیش آنے والے ہر حادثہ کے شر سے سوائے اس حادثہ کے جو خیر لے کر آئے۔ اے رحمٰن!\" (چنانچہ حضورؐ نے یہ کلمات کہے جس سے) ان شیاطین کی آگ بجھ گئی اور ",""],["ٱللَّٰه","a"],[" نے انہیں شکست دے دی۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad and Abu Ya'la, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.117). Mundhiri has said that both chains are sound. Maalik has also reported it in his Muwatta from Yahya bin Sa'eed as a mursal narration, and Nasa'ee has reported it from the narration of Ibn Mas'ood in a similar manner. Ibn Abi Shaybah has reported a similar narration from Makhool with a slight difference in the words of the ta'awwudh, as quoted in Kanzul Ummaal (Vol.1 Pg.212)."]]},{"b":[["n",[["حضرت ابی بن کعبؓ","b"],[" فرماتے ہیں میں نبی کریمؐ کے پاس تھا کہ اتنے میں آپؐ کے پاس ایک دیہاتی آیا اور اس نے عرض کیا اے ",""],["ٱللَّٰه","a"],[" کے نبی! میرا ایک بھائی ہے جسے تکلیف ہے۔ حضورؐ نے پوچھا اسے کیا تکلیف ہے؟ اس نے کہا اس پر جنات کا اثر ہے۔ آپؐ نے فرمایا اسے میرے پاس لاؤ۔ وہ دیہاتی اپنے بھائی کو لایا اور اسے حضورؐ کے سامنے بٹھا دیا۔ حضورؐ نے سورت فاتحہ اور مندرجہ ذیل آیتیں پڑھ کر اسے ",""],["ٱللَّٰه","a"],[" کی پناہ میں دیا۔ سورت بقرہ کی شروع کی چار آیتیں اور یہ دو آیتیں \"وَإِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ ۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ\" اور آیت الکرسی اور سورت بقرہ کی آخری تین آیتیں اور آل عمران کی ایک آیت \"شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ\" اور اعراف کی ایک آیت \"إِنَّ رَبَّكُمُ ٱللَّهُ\" اور سورت مؤمنین کی آخری آیت \"فَتَعَٰلَى ٱللَّهُ ٱلْمَلِكُ ٱلْحَقُّ\" اور سورت جن کی ایک آیت \"وَأَنَّهُۥ تَعَٰلَىٰ جَدُّ رَبِّنَا\" اور سورت صافات کی شروع کی دس آیتیں اور سورت حشر کی آخری تین آیتیں اور \"قُلْ هُوَ ٱللَّهُ أَحَدٌ\" اور معوذتین یعنی \"قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ\" اور \"قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ\" (حضورؐ کی اس پڑھنے کی برکت سے) وہ آدمی وہاں ٹھیک ہو کر اٹھا کہ جیسے اسے کوئی تکلیف ہی نہ تھی۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad, Haakim and Tirmidhi in the chapter on du'aas, as quoted in Kanzul Ummaal (Vol.1 Pg.212)."]]}]},"148":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوامامہؓ","b"],[" فرماتے ہیں حضرت خالد بن ولیدؓ نے حضورؐ کو بتایا کہ وہ رات کو کچھ ڈراؤنی چیزیں دیکھتے ہیں جن کی وجہ سے وہ رات کو تہجد کی نماز نہیں پڑھ سکتے۔ حضورؐ نے فرمایا اے خالد بن ولید! کیا میں تمہیں ایسے کلمات نہ سکھا دوں کہ جب تم ان کو تین مرتبہ پڑھ لو گے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہاری یہ تکلیف دور کر دیں گے۔ حضرت خالدؓ نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! میرے ماں باپ آپ پر قربان ہوں ضرور سکھائیں، میں نے آپ کو اپنی یہ تکلیف اسی لیے تو بتائی ہے۔ حضورؐ نے فرمایا یہ کلمات کہا کرو",""]]],["q",[["أَعُوذُ بِكَلِمَاتِ ٱللَّهِ ٱلتَّامَّةِ مِنْ غَضَبِهِ وَعِقَابِهِ وَشَرِّ عِبَادِهِ وَمِنْ هَمَزَاتِ ٱلشَّيَاطِينِ وَأَنْ يَحْضُرُونِ","a"]]],["p",[["ترجمہ: \"میں ",""],["ٱللَّٰه","a"],[" کے غصے اور اس کی سزا سے اور اس کے بندوں کے شر سے اور شیاطین کے وساوس سے اور شیاطین کے میرے پاس آنے سے اس کے کامل کلمات کی پناہ چاہتا ہوں۔\"",""],[" (1)","s"]]]],"f":[["(1)","Tabraani in his Awsat, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.116). Haythami (Vol.10 Pg.127) has said that in its chain is Hakam bin Abdullah Ayli who is matrook."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں ابھی چند راتیں ہی گزری تھیں کہ حضرت خالدؓ نے آ کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرے ماں باپ آپ پر قربان ہوں اس ذات کی قسم جس نے آپ کو حق دے کر بھیجا ہے جو کلمات آپ نے مجھے سکھائے تھے وہ میں نے تین مرتبہ پورے ہی کیے تھے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے میری وہ تکلیف دور کر دی اور اب تو میرا یہ حال ہے کہ شیر کے بن میں اس کے پاس اس رات کو بھی بلاخوف و خطر جا سکتا ہوں۔",""]]]],"f":[]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا جب تم میں سے کوئی نیند میں گھبرا جائے تو یہ دعا پڑھے",""]]],["q",[["أَعُوذُ بِكَلِمَاتِ ٱللَّهِ ٱلتَّامَّاتِ آگے پچھلی جیسی دعا ذکر کی۔ حضرت عبداللہ بن عمروؓ اپنے بچوں میں سے جو سمجھ دار ہوتا اسے یہ دعا سکھاتے اور جو ابھی ناسمجھ ہوتا تو یہ دعا کسی کاغذ پر لکھ کر اس کے گلے میں ڈال دیتے۔ نسائی کی روایت میں یہ ہے کہ حضرت خالد بن ولیدؓ نیند میں گھبرا جایا کرتے تھے۔ انہوں نے حضورؐ سے اس کا ذکر کیا۔ حضورؐ نے فرمایا جب لیٹا کرو تو یہ دعا پڑھ لیا کرو \"بسم اللہ\" آگے پچھلی جیسی دعا ذکر کی۔ امام مالکؒ نے موطا میں لکھا ہے کہ مجھے یہ بات پہنچی ہے کہ حضرت خالد بن ولیدؓ نے حضورؐ کی خدمت میں عرض کیا کہ میں سوتے ہوئے ڈر جاتا ہوں۔ حضورؐ نے فرمایا یہ دعا پڑھ لیا کرو اور پچھلی دعا ذکر کی۔ حضرت ولید بن ولیدؓ نے حضورؐ کی خدمت میں عرض کیا یا رسول اللہ! مجھے گھبراہٹ اور وحشت محسوس ہوتی ہے۔ حضورؐ نے فرمایا جب تم بستر پر لیٹا کرو تو یہ دعا پڑھا کرو، پھر پچھلی دعا ذکر کی۔","a"],[" (2)","s"],[" (3)","s"]]]],"f":[["(2)","Nasa'ee, Abu Dawood, Haakim who graded it authentic, and Tirmidhi who graded it hasan, with these words, from Amr bin Shu'ayb from his father from his grandfather as a marfoo' narration."],["(3)","Targheeb wat Tarheeb (Vol.3 Pg.116)."]]}]},"149":{"lead":[],"stories":[{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں حضورؐ نے مجھے یہ کلمات سکھائے اور فرمایا جب تمہیں کوئی پریشانی یا سختی پیش آیا کرے تو انہیں پڑھا کرو",""]]],["q",[["لَا إِلَٰهَ إِلَّا ٱللَّهُ ٱلْحَلِيمُ ٱلْكَرِيمُ سُبْحَانَ ٱللَّهِ وَتَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَالَمِينَ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں جو حلیم اور کریم ہے۔ ",""],["ٱللَّٰه","a"],[" پاک اور بابرکت ہے جو کہ عظیم عرش کا رب ہے۔ تمام تعریفیں ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جو تمام جہانوں کا رب ہے۔\"",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, Nasa'ee, Ibn Jareer and Ibn Hibbaan, who graded it authentic, and others, as quoted in Kanzul Ummaal (Vol.1 Pg.298). Ibn Hibbaan and Haakim have also reported it and graded it authentic on the conditions of Muslim, as quoted in Tuhfatuz Zaakireen (Pg.193). Another chain has already appeared in Ta'leemul Adhkaar (Vol.3 Pg.183)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں حضورؐ جب کسی بات کی وجہ سے پریشان اور بے چین ہوتے تو فرماتے",""]]],["q",[["يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ","a"]]],["p",[["ترجمہ: \"اے ہمیشہ زندہ رہنے والے! اے دوسروں کو قائم رکھنے والے! تیری رحمت کے واسطے سے فریاد کرتا ہوں۔\"",""],[" (2)","s"]]]],"f":[["(2)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.1 Pg.299)."]]},{"b":[["n",[["حضرت اسماء بنت عمیسؓ","b"],[" فرماتی ہیں جب حضورؐ کو غم یا پریشانی پیش آتی تو فرمایا کرتے",""]]],["q",[["ٱللَّهُ ٱللَّهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],["، ",""],["ٱللَّٰه","a"],[" میرا رب ہے، میں اس کے ساتھ کسی چیز کو شریک نہیں کرتا۔\" ابن جریر اور ابن ابی شیبہ میں حضرت اسماءؓ کی روایت اس طرح ہے کہ مجھے حضورؐ نے پریشانی کے وقت پڑھنے کے لیے یہ کلمات سکھائے اور پچھلے کلمات ذکر کیے۔",""],[" (3)","s"],[" (4)","s"]]]],"f":[["(3)","Ibn Jareer."],["(4)","As quoted in Kanzul Ummaal (Vol.1 Pg.300)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں ہم سب گھر میں تھے، حضورؐ نے اس کے دروازے کی دونوں چوکھٹوں کو پکڑ کر فرمایا اے بنو عبدالمطلب! جب تم لوگوں کو کوئی پریشانی، سختی یا تنگدستی پیش آئے تو یہ کلمات کہا کرو",""]]],["q",[["ٱللَّهُ ٱللَّهُ رَبُّنَا لَا نُشْرِكُ بِهِ شَيْئًا","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],["، ",""],["ٱللَّٰه","a"],[" ہمارا رب ہے، ہم اس کے ساتھ کسی چیز کو شریک نہیں کرتے۔\"",""],[" (5)","s"]]]],"f":[["(5)","Tabraani in his Awsat and Kabeer; Haythami (Vol.10 Pg.137) has said that in its chain is Saalih bin Abdullah Abu Yahya who is weak. Ibn Jareer has also reported a similar narration from him with the addition of 'laa shareeka lah', as quoted in Kanzul Ummaal (Vol.1 Pg.300)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضورؐ پریشانی کے وقت یہ کلمات پڑھا کرتے تھے",""]]],["q",[["لَا إِلَٰهَ إِلَّا ٱللَّهُ ٱلْعَظِيمُ ٱلْحَلِيمُ لَا إِلَٰهَ إِلَّا ٱللَّهُ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ لَا إِلَٰهَ إِلَّا ٱللَّهُ رَبُّ ٱلسَّمَوَاتِ وَرَبُّ ٱلْأَرْضِ وَرَبُّ ٱلْعَرْشِ ٱلْكَرِيمِ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں جو عظیم اور حلیم ہے۔ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں جو عرش عظیم کا رب ہے۔ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں جو آسمانوں اور زمین کا رب ہے اور عرش کریم کا رب ہے۔\"",""],[" (6)","s"]]]],"f":[["(6)","Bukhaari and Muslim, as quoted in Tuhfatuz Zaakireen (Pg.193)."]]},{"b":[["n",[["حضرت ثوبانؓ","b"],[" فرماتے ہیں جب حضورؐ کسی چیز سے خوف محسوس کرتے تو فرماتے",""]]],["q",[["ٱللَّهُ ٱللَّهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],["، ",""],["ٱللَّٰه","a"],[" میرا رب ہے، میں اس کے ساتھ کسی چیز کو شریک نہیں کرتا۔\"",""],[" (7)","s"]]]],"f":[["(7)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.300)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" نے فرمایا جو بندہ بھی سات مرتبہ یہ دعا پڑھے گا، چاہے وہ سچے دل سے پڑھے یا جھوٹے دل سے، ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے غم اور پریشانی کو ضرور دور کر دیں گے، وہ دعا یہ ہے",""]]],["q",[["حَسْبِيَ ٱللَّهُ لَا إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" مجھے کافی ہے، اس کے سوا کوئی معبود نہیں، میں نے اسی پر بھروسہ کیا اور وہ عظیم عرش کا رب ہے۔\"",""],[" (8)","s"]]]],"f":[["(8)","Haakim, as quoted in Kanzul Ummaal (Vol.1 Pg.300)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں جسے کوئی فکر، غم یا پریشانی پیش آئے یا اسے کسی بادشاہ سے خوف ہو اور وہ ان کلمات کے ذریعہ سے دعا کرے گا تو اس کی دعا ضرور قبول ہوگی",""]]],["q",[["أَسْأَلُكَ بِلَا إِلَٰهَ إِلَّا أَنْتَ رَبُّ ٱلسَّمَوَاتِ ٱلسَّبْعِ وَرَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ، وَأَسْأَلُكَ بِلَا إِلَٰهَ إِلَّا أَنْتَ رَبُّ ٱلسَّمَوَاتِ ٱلسَّبْعِ وَرَبُّ ٱلْعَرْشِ ٱلْكَرِيمِ، وَأَسْأَلُكَ بِلَا إِلَٰهَ إِلَّا أَنْتَ رَبُّ ٱلسَّمَوَاتِ ٱلسَّبْعِ وَٱلْأَرَضِينَ ٱلسَّبْعِ وَمَا فِيهِنَّ، إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","a"]]],["p",[["ترجمہ: \"میں تجھ سے اس بات کے واسطے سے سوال کرتا ہوں کہ تیرے سوا کوئی معبود نہیں، اے ساتوں آسمانوں کے اور عظیم عرش کے رب! اور میں تجھ سے اس بات کے واسطے سے سوال کرتا ہوں کہ تیرے سوا کوئی معبود نہیں، اے ساتوں آسمانوں کے اور کریم عرش کے رب! اور میں تجھ سے اس بات کے واسطے سے سوال کرتا ہوں کہ تیرے سوا کوئی معبود نہیں، اے ساتوں آسمانوں کے، ساتوں زمینوں کے اور ان تمام چیزوں کے رب جو ان میں ہیں! بیشک تو ہر چیز پر قادر ہے۔\" پھر تم ",""],["ٱللَّٰه","a"],[" سے اپنی ضرورت مانگو۔",""],[" (9)","s"]]]],"f":[["(9)","Bukhaari in Adabul Mufrad (Pg.105)."]]}]},"150":{"lead":[],"stories":[{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں حضورؐ نے مجھے ظالم بادشاہ کے پاس اور ہر طرح کے خوف کے وقت پڑھنے کے لیے یہ کلمات سکھائے",""]]],["q",[["لَا إِلَٰهَ إِلَّا ٱللَّهُ ٱلْحَلِيمُ ٱلْكَرِيمُ سُبْحَانَ ٱللَّهِ رَبِّ ٱلسَّمَوَاتِ ٱلسَّبْعِ وَرَبِّ ٱلْعَرْشِ ٱلْعَظِيمِ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَالَمِينَ، إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ عِبَادِكَ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں جو حلیم اور کریم ہے۔ وہ ",""],["ٱللَّٰه","a"],[" پاک ہے جو ساتوں آسمانوں کا اور عظیم عرش کا رب ہے۔ تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جو تمام جہانوں کا رب ہے۔ میں تیرے بندوں کے شر سے تیری پناہ چاہتا ہوں۔\"",""],[" (1)","s"]]]],"f":[["(1)","Kharaa'iti in Makaarimul Akhlaaq, as quoted in Kanzul Ummaal (Vol.1 Pg.299)."]]},{"b":[["n",[["حضرت ابورافعؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن جعفرؓ نے (مجبور ہو کر) حجاج بن یوسف سے اپنی بیٹی کی شادی کی اور بیٹی سے کہا جب وہ تمہارے پاس اندر آئے تو تم یہ دعا پڑھنا",""]]],["q",[["لَا إِلَٰهَ إِلَّا ٱللَّهُ ٱلْحَلِيمُ ٱلْكَرِيمُ سُبْحَانَ ٱللَّهِ رَبِّ ٱلْعَرْشِ ٱلْعَظِيمِ وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَالَمِينَ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں جو حلیم اور کریم ہے۔ ",""],["ٱللَّٰه","a"],[" پاک ہے جو عظیم عرش کا رب ہے اور تمام تعریفیں ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جو تمام جہانوں کا رب ہے۔\" حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے کہا جب حضورؐ کو کوئی سخت امر پیش آتا تو آپؐ یہ دعا پڑھتے۔ راوی کہتے ہیں (حضرت عبد",""],["ٱللَّٰه","a"],["ؓ کی بیٹی نے یہ دعا پڑھی جس کی وجہ سے) حجاج اس کے قریب نہ آ سکا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.300)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں جب تم کسی بارعب بادشاہ کے پاس جاؤ اور تمہیں ڈر ہو کہ وہ تمہارے ساتھ زیادتی کرے گا تو تم تین مرتبہ یہ دعا پڑھو",""]]],["q",[["ٱللَّهُ أَكْبَرُ ٱللَّهُ أَكْبَرُ ٱللَّهُ أَعَزُّ مِنْ خَلْقِهِ جَمِيعًا، ٱللَّهُ أَعَزُّ مِمَّا أَخَافُ وَأَحْذَرُ، أَعُوذُ بِٱللَّهِ ٱلَّذِي لَا إِلَٰهَ إِلَّا هُوَ ٱلْمُمْسِكِ ٱلسَّمَوَاتِ ٱلسَّبْعِ أَنْ يَقَعْنَ عَلَى ٱلْأَرْضِ إِلَّا بِإِذْنِهِ مِنْ شَرِّ عَبْدِكَ فُلَانٍ وَجُنُودِهِ وَأَتْبَاعِهِ وَأَشْيَاعِهِ مِنَ ٱلْجِنِّ وَٱلْإِنْسِ، ٱللَّهُمَّ كُنْ لِي جَارًا مِنْ شَرِّهِمْ، جَلَّ ثَنَاؤُكَ وَعَزَّ جَارُكَ وَتَبَارَكَ ٱسْمُكَ وَلَا إِلَٰهَ غَيْرُكَ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" سب سے بڑا ہے، ",""],["ٱللَّٰه","a"],[" سب سے بڑا ہے، ",""],["ٱللَّٰه","a"],[" اپنی ساری مخلوق سے زیادہ عزت و غلبہ والا ہے، ",""],["ٱللَّٰه","a"],[" ان سب سے زیادہ عزت و غلبہ والا ہے جن سے میں بچنا چاہتا ہوں۔ میں اس ",""],["ٱللَّٰه","a"],[" کی پناہ چاہتا ہوں جس کے سوا کوئی معبود نہیں اور جس نے اپنے حکم سے ساتوں آسمانوں کو زمین پر گرنے سے روک رکھا ہے، تیرے فلاں بندے کے شر اور اس کے لشکروں اور اس کے پیچھے چلنے والوں اور اس کی بات ماننے والوں کے شر سے، چاہے وہ جنات ہوں یا انسان۔ اے ",""],["ٱللَّٰه","a"],["! تو میرے لیے ان سب کے شر سے پناہ بن جا۔ تیری ثنا بہت بڑی ہے اور تیری پناہ لینے والا غالب ہوتا ہے اور تیرا نام بابرکت ہے اور تیرے سوا کوئی معبود نہیں۔\"",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.300). Tabraani has reported a similar narration from Ibn Abbas with slight differences in the wording; its narrators are authentic as confirmed by Haythami (Vol.10 Pg.137). Bukhaari has also reported a similar narration from Ibn Abbas in Adabul Mufrad (Pg.103)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں جب تمہیں کسی حاکم کے غیظ و غضب اور زیادتی کا خوف ہو تو یہ دعا پڑھو",""]]],["q",[["ٱللَّهُمَّ رَبَّ ٱلسَّمَوَاتِ ٱلسَّبْعِ وَرَبَّ ٱلْعَرْشِ ٱلْعَظِيمِ كُنْ لِي جَارًا مِنْ فُلَانٍ وَأَحْزَابِهِ وَأَشْيَاعِهِ مِنَ ٱلْجِنِّ وَٱلْإِنْسِ أَنْ يَفْرُطُوا عَلَيَّ أَوْ أَنْ يَطْغَوْا، عَزَّ جَارُكَ وَجَلَّ ثَنَاؤُكَ وَلَا إِلَٰهَ غَيْرُكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! جو ساتوں آسمانوں اور عرش عظیم کا رب ہے تو میرے لیے فلاں کے شر سے اور اس کی مددگار جماعتوں اور اس کی ماننے والے جنات اور انسانوں کے شر سے پناہ بن جا تاکہ وہ مجھ پر ظلم اور زیادتی نہ کر سکیں۔ تیری پناہ لینے والا باعزت ہوتا ہے اور تیری ثناء بہت بڑی ہے اور تیرے سوا کوئی معبود نہیں ہے۔\" جب تم یہ دعا پڑھو گے تو اس ظالم حاکم کی طرف سے تمہیں کوئی ناگواری پیش نہیں آئے گی۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abi Shaybah and Ibn Jareer, as quoted in Kanzul Ummaal (Vol.1 Pg.300). Bukhaari has also reported it in Adabul Mufrad (Pg.104) from Ibn Mas'ood as a mawqoof narration with the same meaning in shorter form."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا جب تم میں سے کسی کو ظالم بادشاہ کا خوف ہو تو وہ یہ دعا پڑھے اور پھر پچھلی دعا ذکر کی، البتہ اس روایت میں یہ الفاظ ہیں",""]]],["q",[["كُنْ لِي جَارًا مِنْ شَرِّ فُلَانِ بْنِ فُلَانٍ يَعْنِي ٱلَّذِي يُرِيدُ وَشَرِّ ٱلْجِنِّ وَٱلْإِنْسِ وَأَتْبَاعِهِمْ أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ، عَزَّ جَارُكَ وَجَلَّ ثَنَاؤُكَ وَلَا إِلَٰهَ غَيْرُكَ","a"]]],["p",[["ترجمہ: \"تو میرے لیے فلاں بن فلاں کے شر سے (یہاں اس ظالم بادشاہ کا نام لے) اور جنات اور انسانوں کے ان کے پیچھے چلنے والوں کے شر سے پناہ بن جا تاکہ ان میں سے کوئی بھی مجھ پر زیادتی نہ کر سکے۔ تیری پناہ لینے والا غالب ہوتا ہے اور تیری ثناء بہت بڑی ہے اور تیرے سوا کوئی معبود نہیں۔\"",""],[" (5)","s"]]]],"f":[["(5)","Tabraani; Haythami (Vol.10 Pg.137) has said that in its chain is Junaadah bin Salm whom Ibn Hibbaan has declared reliable and others have declared weak, while the remaining narrators are those of authentic Ahaadeeth."]]}]},"151":{"lead":[],"stories":[{"b":[["n",[["حضرت ابووائلؒ","b"],[" فرماتے ہیں ایک مکاتب غلام (مکاتب اس غلام کو کہتے ہیں جسے اس کے آقا نے کہا ہو کہ اگر تم اتنا مال اتنے عرصہ میں ادا کر دو گے تو تم آزاد ہو جاؤ گے) نے حضرت علیؓ کی خدمت میں آ کر عرض کیا کہ میں کتابت میں مقررہ شدہ مال ادا کرنے سے عاجز ہو گیا ہوں، آپ اس بارے میں میری مدد فرمائیں۔ حضرت علیؓ نے فرمایا کیا میں تمہیں وہ کلمات نہ سکھاؤں جو حضورؐ نے مجھے سکھائے تھے؟ اگر تم پر (یمن کے) صیر پہاڑ کے برابر بھی قرض ہو تو بھی ",""],["ٱللَّٰه","a"],[" تمہارا قرض ادا کرا دے گا۔ تم یہ دعا پڑھا کرو",""]]],["q",[["ٱللَّهُمَّ ٱكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! مجھے اپنا حلال رزق دے کر حرام سے بچا دے اور اپنے فضل و کرم سے مجھے اپنے ماسوا سے بے نیاز کر دے۔\"",""],[" (1)","s"]]]],"f":[["(1)","Tirmidhi (Vol.2 Pg.195), who said that it is a hasan ghareeb hadith."]]},{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں حضورؐ ایک دن مسجد میں تشریف لائے تو اچانک آپؐ کی نظر ایک انصاری شخص پر پڑی جنہیں ابوامامہ کہا جاتا تھا۔ حضورؐ نے فرمایا اے ابوامامہ! کیا بات ہے تم آج مسجد میں نماز کے وقت کے علاوہ دوسرے وقت میں بیٹھے ہوئے ہو؟ انہوں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! غموں اور قرضوں نے مجھے گھیر لیا ہے۔ حضورؐ نے فرمایا کیا میں تمہیں ایسا کلام نہ سکھاؤں کہ جب تم اسے کہو گے تو ",""],["ٱللَّٰه","a"],[" تمہارا غم دور کر دیں گے اور قرض اتروا دیں گے۔ انہوں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! ضرور سکھا دیں۔ حضورؐ نے فرمایا صبح اور شام یہ دعا پڑھا کرو",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلْهَمِّ وَٱلْحَزَنِ وَأَعُوذُ بِكَ مِنَ ٱلْعَجْزِ وَٱلْكَسَلِ وَأَعُوذُ بِكَ مِنَ ٱلْجُبْنِ وَٱلْبُخْلِ وَأَعُوذُ بِكَ مِنْ غَلَبَةِ ٱلدَّيْنِ وَقَهْرِ ٱلرِّجَالِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں ہر فکر و غم سے تیری پناہ چاہتا ہوں اور عاجز ہو جانے اور سستی سے تیری پناہ چاہتا ہوں اور بزدلی اور کنجوسی سے تیری پناہ چاہتا ہوں اور قرضہ کے غلبہ اور لوگوں کے میرے اوپر دباؤ سے تیری پناہ چاہتا ہوں۔\" حضرت ابوامامہؓ فرماتے ہیں میں نے ایسا کیا تو ",""],["ٱللَّٰه","a"],[" نے میرے غم بھی دور کر دیے اور میرا قرضہ بھی سارا ادا کرا دیا۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Dawood (Vol.2 Pg.270)."]]},{"b":[["n",[["ایک دفعہ جمعہ کے دن حضورؐ نے ",""],["حضرت معاذ بن جبلؓ","b"],[" کو نہ دیکھا۔ جب حضورؐ نماز سے فارغ ہو گئے تو حضرت معاذؓ کے پاس تشریف لے گئے اور فرمایا اے معاذ! کیا بات ہے آج تم (جمعہ کی نماز میں) نظر نہیں آئے؟ انہوں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! ایک یہودی کا مجھ پر ایک اوقیہ سونا ہے، میں گھر سے آپ کی خدمت میں حاضری کے لیے چل پڑا لیکن راستہ میں وہ یہودی مل گیا جس کی وجہ سے دیر ہو گئی۔ حضورؐ نے فرمایا اے معاذ! کیا میں تمہیں ایسی دعا نہ سکھا دوں کہ اگر (یمن کے) صیر پہاڑ جتنا بھی تم پر قرض ہو اور تم یہ دعا پڑھو تو ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہارا قرضہ ضرور ادا کرا دیں گے؟ اے معاذ! تم یہ دعا کیا کرو",""]]],["q",[["ٱللَّهُمَّ مَالِكَ ٱلْمُلْكِ تُؤْتِي ٱلْمُلْكَ مَنْ تَشَاءُ وَتَنْزِعُ ٱلْمُلْكَ مِمَّنْ تَشَاءُ وَتُعِزُّ مَنْ تَشَاءُ وَتُذِلُّ مَنْ تَشَاءُ بِيَدِكَ ٱلْخَيْرُ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ، تُولِجُ ٱللَّيْلَ فِي ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِي ٱللَّيْلِ وَتُخْرِجُ ٱلْحَيَّ مِنَ ٱلْمَيِّتِ وَتُخْرِجُ ٱلْمَيِّتَ مِنَ ٱلْحَيِّ وَتَرْزُقُ مَنْ تَشَاءُ بِغَيْرِ حِسَابٍ، رَحْمَٰنَ ٱلدُّنْيَا وَٱلْآخِرَةِ وَرَحِيمَهُمَا تُعْطِيهِمَا مَنْ تَشَاءُ وَتَمْنَعُ مِنْهُمَا مَنْ تَشَاءُ، ٱرْحَمْنِي رَحْمَةً تُغْنِينِي بِهَا عَنْ رَحْمَةِ مَنْ سِوَاكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اے تمام ملک کے مالک! تو جس کو چاہے ملک دے دیتا ہے اور جس سے چاہے ملک چھین لیتا ہے اور تو جسے چاہے عزت دیتا ہے اور جسے چاہے ذلت دیتا ہے۔ ہر بھلائی تیرے ہی اختیار میں ہے، بلاشبہ تو ہر چیز پر پوری قدرت رکھنے والا ہے۔ تو رات کو دن میں داخل کرتا ہے اور دن کو رات میں داخل کر دیتا ہے (کبھی دن بڑا ہوتا ہے اور کبھی رات) اور تو زندہ کو مردہ سے نکال لیتا ہے اور مردے کو زندہ سے نکال لیتا ہے (پرندہ سے انڈا نکال لیتا ہے اور انڈے سے پرندہ) اور تو جسے چاہتا ہے اسے بے حساب روزی دیتا ہے۔ اے دنیا و آخرت کے رحمٰن! اے دنیا اور آخرت کے رحیم! تو دنیا اور آخرت جسے چاہے دے دیتا ہے اور جس سے چاہے روک لیتا ہے۔ تو مجھ پر ایسی خاص رحمت نازل فرما جس کے بعد مجھے تیرے سوا کسی کی ضرورت نہ رہے۔\"",""],[" (3)","s"]]]],"f":[["(3)","Tabraani; Haythami (Vol.10 Pg.186) has said that in its chain is Nasr bin Marzooq whom I do not know, while the rest of its narrators are reliable, except that Sa'eed bin Musayyab did not hear from Mu'aadh."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں حضورؐ نے حضرت معاذؓ کو فرمایا کیا میں تمہیں ایسی دعا نہ سکھا دوں کہ اگر احد پہاڑ جتنا بھی تم پر قرضہ ہو تو بھی ",""],["ٱللَّٰه","a"],[" تعالیٰ ضرور ادا کر دے گا؟ اے معاذ! تم یہ دعا پڑھو",""]]],["q",[["ٱللَّهُمَّ مَالِكَ ٱلْمُلْكِ پچھلی جیسی دعا ذکر فرمائی، البتہ اس میں \"تولج اللیل\" سے آخر تک کا ذکر نہیں ہے اور اس میں یہ الفاظ ہیں \"رحمٰن الدنیا والآخرۃ تعطیھما من تشاء وتمنع منھما من تشاء\"، آگے پچھلی حدیث جیسی دعا ذکر کی۔","a"],[" (4)","s"]]]],"f":[["(4)","Tabraani in his Sagheer; Haythami (Vol.10 Pg.186) has said that its narrators are reliable."]]}]},"152":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں ایک مرتبہ ہم لوگ حضورؐ کے پاس بیٹھے ہوئے تھے کہ اتنے میں حضرت علی بن ابی طالبؓ نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا میرے ماں باپ آپ پر قربان ہوں یہ قرآن تو میرے سینے سے نکل گیا۔ مجھے تو ایسے لگ رہا ہے کہ میں قرآن پر قابو نہیں پا سکتا، اسے یاد نہیں رکھ سکتا۔ حضورؐ نے ان سے فرمایا کیا میں تمہیں ایسے چند کلمات نہ سکھا دوں جن سے تمہیں بھی فائدہ ہو اور جسے تم یہ کلمات سکھاؤ گے اسے بھی فائدہ ہوگا اور جو کچھ تم سیکھو گے وہ تمہارے سینے میں باقی رہے گا؟ حضرت علیؓ نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! جی ہاں مجھے یہ کلمات ضرور سکھا دیں۔ حضورؐ نے فرمایا جب جمعہ کی رات آئے تو اگر تم رات کے آخری تہائی حصے میں اٹھ سکو (تو بہت اچھا ہے) کیونکہ یہ ایسا وقت ہے جس میں فرشتے حاضر ہوتے ہیں اور اس میں دعا قبول ہوتی ہے اور میرے بھائی حضرت یعقوبؑ نے اپنے بیٹوں سے کہا تھا",""]]],["q",[["سَوْفَ أَسْتَغْفِرُ لَكُمْ رَبِّيٓ","a"]]],["p",[["ترجمہ: \"عنقریب تمہارے لیے اپنے رب سے دعائے مغفرت کروں گا۔\" (سورت یوسف آیت ۹۸) حضرت یعقوبؑ کی مراد بھی جمعہ کی رات تھی۔ اگر تم آخری تہائی رات میں نہ اٹھ سکو تو پھر درمیان رات میں اٹھو، اگر تم یہ بھی نہ کر سکو تو پھر شروع رات میں اٹھو اور چار رکعت نماز پڑھو۔ پہلی رکعت میں سورت فاتحہ اور سورت یٰسین، دوسری رکعت میں سورت فاتحہ اور سورت حم دخان، تیسری رکعت میں سورت فاتحہ اور سورت الم تنزیل سجدہ اور چوتھی رکعت میں سورت فاتحہ اور سورت تبارک الذی پڑھو۔ اور جب التحیات سے فارغ ہو جاؤ تو خوب اچھی طرح حمد و ثناء بیان کرو اور پھر خوب اچھی طرح مجھ پر اور سارے نبیوں پر درود پڑھو، پھر تمام مومن مردوں اور عورتوں کے لیے اور جو بھائی تم سے پہلے ایمان کے ساتھ گزر چکے ان کے لیے دعائے مغفرت کرو، پھر آخر میں یہ دعا پڑھو",""]]],["q",[["ٱللَّهُمَّ ٱرْحَمْنِي بِتَرْكِ ٱلْمَعَاصِي أَبَدًا مَا أَبْقَيْتَنِي وَٱرْحَمْنِي أَنْ أَتَكَلَّفَ مَا لَا يَعْنِينِي وَٱرْزُقْنِي حُسْنَ ٱلنَّظَرِ فِيمَا يُرْضِيكَ عَنِّي، ٱللَّهُمَّ بَدِيعَ ٱلسَّمَوَاتِ وَٱلْأَرْضِ ذَا ٱلْجَلَالِ وَٱلْإِكْرَامِ وَٱلْعِزَّةِ ٱلَّتِي لَا تُرَامُ أَسْأَلُكَ يَا ٱللَّهُ يَا رَحْمَٰنُ بِجَلَالِكَ وَنُورِ وَجْهِكَ أَنْ تُلْزِمَ قَلْبِي حِفْظَ كِتَابِكَ كَمَا عَلَّمْتَنِي وَٱرْزُقْنِي أَنْ أَتْلُوَهُ عَلَى ٱلنَّحْوِ ٱلَّذِي يُرْضِيكَ عَنِّي، ٱللَّهُمَّ بَدِيعَ ٱلسَّمَوَاتِ وَٱلْأَرْضِ ذَا ٱلْجَلَالِ وَٱلْإِكْرَامِ وَٱلْعِزَّةِ ٱلَّتِي لَا تُرَامُ أَسْأَلُكَ يَا ٱللَّهُ يَا رَحْمَٰنُ بِجَلَالِكَ وَنُورِ وَجْهِكَ أَنْ تُنَوِّرَ بِكِتَابِكَ بَصَرِي وَأَنْ تُطْلِقَ بِهِ لِسَانِي وَأَنْ تُفَرِّجَ بِهِ عَنْ قَلْبِي وَأَنْ تَشْرَحَ بِهِ صَدْرِي وَأَنْ تَغْسِلَ بِهِ بَدَنِي فَإِنَّهُ لَا يُعِينُنِي عَلَى ٱلْحَقِّ غَيْرُكَ وَلَا يُؤْتِيهِ إِلَّا أَنْتَ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِٱللَّهِ ٱلْعَلِيِّ ٱلْعَظِيمِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! مجھ پر مہربانی فرما کہ جب تک زندہ رہوں گناہوں سے بچتا رہوں اور مجھ پر مہربانی فرما کہ جو کام میرے مطلب اور فائدے کے نہ ہوں میں ان میں نہ پڑوں اور مجھے اس بات کی توفیق دے کہ میں ان کاموں کی اچھی طرح فکر کروں جن سے تو مجھ سے راضی ہو جائے۔ اے ",""],["ٱللَّٰه","a"],["! آسمانوں اور زمین کے بے نمونہ پیدا کرنے والے! اے عظمت و جلال والے! اے اکرام و احسان والے! اور ایسی عزت والے جس کے حاصل ہونے کا کسی کو وہم و گمان بھی نہیں ہو سکتا! اے ",""],["ٱللَّٰه","a"],["! اے رحمٰن! میں تیری عظمت و جلال کا اور تیری ذات کے نور کا واسطہ دے کر تجھ سے سوال کرتا ہوں کہ جیسے تو نے مجھے اپنی کتاب کا علم عنایت فرمایا ہے ایسے ہی میرے دل کو اس کا یاد رکھنا نصیب فرما اور مجھے اس کی اس طرح تلاوت کرنے کی توفیق عطا فرما جس سے تو مجھ سے راضی ہو جائے۔ اے ",""],["ٱللَّٰه","a"],["! آسمانوں اور زمین کے بے نمونہ پیدا کرنے والے! اے عظمت و جلال والے! اے اکرام و احسان والے! اور ایسی عزت والے جس کے حاصل ہونے کا کسی کو وہم و گمان بھی نہیں ہو سکتا! اے ",""],["ٱللَّٰه","a"],["! اے رحمٰن! میں تیری عظمت و جلال کا اور تیری ذات کے نور کا واسطہ دے کر تجھ سے سوال کرتا ہوں کہ تو اپنی کتاب کی برکت سے میری نگاہ کو روشن کر دے اور اس کو میری زبان پر جاری کر دے اور اس کی برکت سے میرے دل کے غم کو دور کر دے اور میرا سینہ کھول دے اور اس کی برکت سے میرے بدن کو (گناہوں سے) دھو دے کیونکہ حق بات پر تیرے سوا اور کوئی میری مدد نہیں کر سکتا اور تیرے سوا اور کوئی میری آرزو پوری نہیں کر سکتا اور برائیوں سے بچنے کی طاقت اور نیکی کرنے کی قوت صرف ",""],["ٱللَّٰه","a"],[" سے ہی ملتی ہے جو کہ بزرگ و برتر ہے۔\" اے ابوالحسن! تم تین جمعے یا پانچ جمعے یا سات جمعے تک ایسا کرو، ",""],["ٱللَّٰه","a"],[" کے حکم سے تمہاری دعا ضرور قبول ہوگی۔ اس ذات کی قسم جس نے مجھے حق دے کر بھیجا ہے! آج تک کبھی کسی مومن کی یہ دعا رد نہیں ہوئی۔ حضرت ابن عباسؓ کہتے ہیں حضرت علیؓ کو پانچ یا سات ہی جمعے گزرے ہوں گے کہ وہ حضورؐ کی مجلس میں حاضر ہوئے اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! پہلے میں تقریباً چار آیتیں پڑھتا تھا اور وہ بھی مجھے یاد نہ ہوتی تھیں اور اب تقریباً چالیس آیتیں پڑھتا ہوں اور ایسی از بر ہو جاتی ہیں کہ جب پڑھتا ہوں تو ایسے لگتا ہے کہ گویا ",""],["ٱللَّٰه","a"],[" کی کتاب میری آنکھوں کے سامنے کھلی رکھی ہے۔ اور پہلے میں حدیث سنتا تھا اور جب اس کو دوبارہ کہتا تھا تو ذہن سے نکل جاتی تھی اور اب بہت سی حدیثیں سنتا ہوں اور جب دوسروں سے نقل کرتا ہوں تو ایک لفظ بھی نہیں چھوٹتا۔ اس پر حضورؐ نے ان سے فرمایا اے ابوالحسن! رب کعبہ کی قسم! تم مومن ہو۔",""],[" (1)","s"]]]],"f":[["(1)","Tirmidhi (Vol.2 Pg.196), who said that it is a hasan ghareeb hadith."]]}]},"153":{"lead":[],"stories":[{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں مجھے یہ بات پہنچی ہے کہ حضرت ابوبکرؓ اپنی دعا میں فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ ٱلَّذِي هُوَ خَيْرٌ فِي عَاقِبَةِ أَمْرِي، ٱللَّهُمَّ ٱجْعَلْ مَا تُعْطِينِي مِنَ ٱلْخَيْرِ رِضْوَانَكَ وَٱلدَّرَجَاتِ ٱلْعُلَىٰ فِي جَنَّاتِ ٱلنَّعِيمِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے اپنے ہر کام کے انجام میں خیر کا سوال کرتا ہوں، اے ",""],["ٱللَّٰه","a"],["! تو مجھے جس خیر کی توفیق عطا فرمائے اسے اپنی رضا کا اور نعمتوں والی جنتوں میں اونچے درجات کے حاصل ہونے کا ذریعہ بنا۔\"",""],[" (1)","s"]]]],"f":[["(1)","Ahmad in his Zuhd."]]},{"b":[["n",[["حضرت معاویہ بن قرہؒ","b"],[" کہتے ہیں حضرت ابوبکر صدیقؓ اپنی دعا میں فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ ٱجْعَلْ خَيْرَ عُمُرِي آخِرَهُ وَخَيْرَ عَمَلِي خَوَاتِمَهُ وَخَيْرَ أَيَّامِي يَوْمَ أَلْقَاكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میری عمر کا سب سے بہترین حصہ وہ بنا جو اس کا آخر ہو اور میرا سب سے بہترین عمل وہ بنا جو خاتمہ والا ہو اور میرا سب سے بہترین دن وہ بنا جو تیری ملاقات کا دن ہو۔\"",""],[" (2)","s"]]]],"f":[["(2)","Sa'eed bin Mansoor and others, as quoted in Kanzul Ummaal (Vol.1 Pg.303)."]]},{"b":[["n",[["حضرت عبدالعزیز بن سلمہ ماجشونؒ","b"],[" کہتے ہیں مجھے ایک ایسے صاحب نے بیان کیا جنہیں میں سچا سمجھتا ہوں کہ حضرت ابوبکر صدیقؓ اپنی دعا میں فرمایا کرتے تھے",""]]],["q",[["أَسْأَلُكَ تَمَامَ ٱلنِّعْمَةِ فِي ٱلْأَشْيَاءِ كُلِّهَا وَٱلشُّكْرَ لَكَ عَلَيْهَا حَتَّىٰ تَرْضَىٰ وَبَعْدَ ٱلرِّضَا وَٱلْخِيَرَةَ فِي جَمِيعِ مَا يَكُونُ فِيهِ ٱلْخِيَرَةُ بِجَمِيعِ مَيْسُورِ ٱلْأُمُورِ كُلِّهَا لَا بِمَعْسُورِهَا يَا كَرِيمُ","a"]]],["p",[["ترجمہ: \"میں تجھ سے سوال کرتا ہوں کہ تمام چیزوں میں تو نعمت پوری فرما دے اور ان چیزوں پر اتنا شکر ادا کرنے کی توفیق مانگتا ہوں کہ جس سے تو راضی ہو جائے اور اس کے بعد یہ درخواست کرتا ہوں کہ جتنی چیزوں میں کسی ایک جانب کے اختیار کرنے کی صورت ہوتی ہے ان میں میں آسان صورت اختیار کروں اور مشکل اختیار نہ کروں، اے کریم!\"",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abi Dunya."]]},{"b":[["n",[["حضرت ابویزید مدائنیؒ","b"],[" کہتے ہیں حضرت ابوبکرؓ کی ایک دعا یہ بھی تھی",""]]],["q",[["ٱللَّهُمَّ هَبْ لِي إِيمَانًا وَيَقِينًا وَمُعَافَاةً وَنِيَّةً","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! مجھے ایمان و یقین، عافیت اور سچی نیت نصیب فرما۔\"",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abi Dunya also, as quoted in Kanzul Ummaal (Vol.1 Pg.303)."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" فرماتے ہیں",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ تَأْخُذَنِي عَلَىٰ غِرَّةٍ أَوْ تَذَرَنِي فِي غَفْلَةٍ أَوْ تَجْعَلَنِي مِنَ ٱلْغَافِلِينَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں اس بات سے تیری پناہ مانگتا ہوں کہ تو اچانک بے خبری میں میری پکڑ کرے یا مجھے غفلت میں پڑا رہنے دے یا مجھے غافل لوگوں میں سے بنا دے۔\"",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abi Shaybah and Abu Nu'aym in his Hilyah."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں حضرت عمرؓ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ ٱجْعَلْ عَمَلِي صَالِحًا وَٱجْعَلْهُ لَكَ خَالِصًا وَلَا تَجْعَلْ لِأَحَدٍ فِيهِ شَيْئًا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میرے عمل کو نیک بنا اور اسے خالص اپنے لیے بنا اور اس میں کسی اور کا ذرہ بھر بھی حصہ نہ ہونے دے۔\"",""],[" (6)","s"]]]],"f":[["(6)","Ahmad in his Zuhd."]]},{"b":[["n",[["حضرت عمرو بن میمونؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ اپنی دعا میں یہ بھی کہا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ تَوَفَّنِي مَعَ ٱلْأَبْرَارِ وَلَا تُخَلِّفْنِي فِي ٱلْأَشْرَارِ وَقِنِي عَذَابَ ٱلنَّارِ وَأَلْحِقْنِي بِٱلْأَخْيَارِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تو مجھے نیک لوگوں کے ساتھ موت دے اور مجھے برے لوگوں میں سے نہ بنا اور مجھے جہنم کے عذاب سے بچا اور مجھے نیک اور بھلے لوگوں کے ساتھ شامل فرما۔\"",""],[" (7)","s"]]]],"f":[["(7)","Ibn Sa'd and Bukhaari in Adab."]]},{"b":[["n",[["حضرت ابوالعالیہؒ","b"],[" کہتے ہیں میں اکثر حضرت عمر بن خطابؓ کو یہ کہتے ہوئے سنتا",""]]],["q",[["ٱللَّهُمَّ عَافِنَا وَٱعْفُ عَنَّا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ہمیں عافیت نصیب فرما اور ہمیں معاف فرما۔\"",""],[" (8)","s"]]]],"f":[["(8)","Ahmad in his Zuhd, as quoted in Kanzul Ummaal (Vol.1 Pg.303)."]]},{"b":[["n",[["حضرت حفصہؓ","b"],[" فرماتی ہیں میں نے اپنے والد (حضرت عمرؓ) کو یہ کہتے ہوئے سنا",""]]],["q",[["ٱللَّهُمَّ ٱرْزُقْنِي قَتْلًا فِي سَبِيلِكَ وَوَفَاةً فِي بَلَدِ نَبِيِّكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! مجھے اپنے راستے کی شہادت اور اپنے نبیؐ کے شہر کی موت نصیب فرما۔\" میں نے کہا آپ کو یہ دونوں باتیں کیسے حاصل ہو سکتی ہیں؟ حضرت عمرؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" جہاں چاہے اپنے فیصلے کو وجود دے سکتا ہے۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Sa'd and Abu Nu'aym in his Hilyah."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" نے یوں دعا کی",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لِي ظُلْمِي وَكُفْرِي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میرے ظلم اور میرے کفر کو معاف فرما۔\" ایک آدمی نے کہا ظلم کا لفظ تو ٹھیک ہے لیکن کفر کا کیا مطلب؟ حضرت عمرؓ نے فرمایا (قرآن میں ہے)",""]]],["q",[["إِنَّ ٱلْإِنسَٰنَ لَظَلُومٌ كَفَّارٌ","a"]]],["p",[["ترجمہ: \"سچ یہ ہے کہ آدمی بہت ہی بے انصاف اور بڑا ہی ناشکرا ہے۔\" (یعنی کفر سے ناشکری مراد ہے)",""],[" (10)","s"]]]],"f":[["(10)","Ibn Abi Haatim."]]},{"b":[["n",[["حضرت ابوعثمان نہدیؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ بیت ",""],["ٱللَّٰه","a"],[" کا طواف کر رہے تھے، میں نے انہیں یہ کہتے ہوئے سنا",""]]],["q",[["ٱللَّهُمَّ إِنْ كُنْتَ كَتَبْتَنِي فِي ٱلسَّعَادَةِ فَأَثْبِتْنِي فِيهَا وَإِنْ كُنْتَ كَتَبْتَنِي فِي ٱلشِّقَاوَةِ فَٱمْحُنِي مِنْهَا وَأَثْبِتْنِي فِي ٱلسَّعَادَةِ فَإِنَّكَ تَمْحُو مَا تَشَاءُ وَتُثْبِتُ وَعِنْدَكَ أُمُّ ٱلْكِتَابِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اگر تو نے میرا نام خوش قسمت انسانوں میں لکھا ہے تو میرا نام ان میں لکھا رہنے دے اور اگر میرا نام بدقسمت لوگوں میں لکھا ہوا ہے تو اس میں سے مٹا کر خوش قسمت لوگوں میں لکھ دے کیونکہ تو جو چاہے مٹا سکتا ہے اور جو چاہے باقی رکھ سکتا ہے اور تیرے پاس لوح محفوظ ہے۔\"",""],[" (11)","s"]]]],"f":[["(11)","Abdullah Laalka'i, as quoted in Kanzul Ummaal (Vol.1 Pg.303). Abd bin Humayd, Ibn Jareer and Ibn Mundhir have reported it in abridged form, as quoted in Kanzul Ummaal (Vol.1 Pg.304)."]]},{"b":[["n",[["حضرت یزیدؒ","b"],[" کہتے ہیں میں نے حضرت عمر بن خطابؓ کو آدھی رات کے وقت رمادہ قحط کے زمانہ میں حضورؐ کی مسجد میں نماز پڑھتے ہوئے دیکھا، وہ یہ دعا کر رہے تھے",""]]],["q",[["ٱللَّهُمَّ لَا تُهْلِكْنَا بِٱلسِّنِينَ وَٱرْفَعْ عَنَّا هَٰذَا ٱلْبَلَاءَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ہمیں قحط سے ہلاک نہ فرما اور ہم سے یہ مصیبت دور فرما۔\" اور وہ یہ دعا بار بار کرتے رہے۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Sa'd (Vol.3 Pg.321)."]]},{"b":[["n",[["حضرت یزیدؒ","b"],[" کہتے ہیں رمادہ قحط کے زمانہ میں میں نے حضرت عمر بن خطابؓ کی چادر دیکھی جس پر سولہ پیوند لگے ہوئے تھے اور آپ کی چادر پانچ ہاتھ اور ایک بالشت لمبی تھی اور آپ یہ دعا کر رہے تھے",""]]],["q",[["ٱللَّهُمَّ لَا تَجْعَلْ هَلَكَةَ أُمَّةِ مُحَمَّدٍ عَلَىٰ يَدَيَّ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! حضرت محمدؐ کی امت کی ہلاکت میرے زمانے میں نہ کر۔\"",""],[" (13)","s"]]]],"f":[["(13)","Ibn Sa'd (Vol.3 Pg.294)."]]},{"b":[["n",[["حضرت اسلمؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ نے فرمایا",""]]],["q",[["ٱللَّهُمَّ لَا تَجْعَلْ قَتْلِي بِيَدِ رَجُلٍ صَلَّىٰ لَكَ رَكْعَةً أَوْ سَجْدَةً وَاحِدَةً يُحَاجُّنِي بِهَا عِنْدَكَ يَوْمَ ٱلْقِيَامَةِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میرا قتل ایسے شخص کے ہاتھوں نہ کرنا جس نے ایک رکعت ہی پڑھی ہو یا ایک سجدہ کیا ہو اور وہ اس کی وجہ سے قیامت کے دن مجھ سے جھگڑا کرے۔\" (یعنی میری شہادت مسلمان کے ہاتھوں نہ ہو۔)",""],[" (14)","s"]]]],"f":[["(14)","Bukhaari, Maalik, Ibn Raahway and Abu Nu'aym in his Hilyah, who graded it authentic, from Zayd bin Aslam, as quoted in Muntakhab Kanzul Ummaal (Vol.3 Pg.131)."]]},{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت عمر بن خطابؓ نے کنکریوں کی ایک ڈھیری بنائی، پھر اس پر اپنے کپڑے کا کنارہ ڈال کر اس پر سر رکھ کر لیٹ گئے، پھر آسمان کی طرف اپنے ہاتھ اٹھا کر یہ دعا کی",""]]],["q",[["ٱللَّهُمَّ كَبُرَتْ سِنِّي وَضَعُفَتْ قُوَّتِي وَٱنْتَشَرَتْ رَعِيَّتِي فَٱقْبِضْنِي إِلَيْكَ غَيْرَ مُضَيِّعٍ وَلَا مُفَرِّطٍ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میری عمر زیادہ ہو گئی اور میرے قویٰ کمزور ہو گئے اور میری رعایا پھیل گئی، لہٰذا اب تو مجھے اپنی طرف اس طرح اٹھا لے کہ نہ کسی کے حق ضائع کرنے والا ہوں اور نہ کسی کے حق میں کمی کرنے والا ہوں۔\"",""],[" (15)","s"]]]],"f":[["(15)","Abu Nu'aym in his Hilyah (Vol.1 Pg.54)."]]},{"b":[["n",[["حضرت اسود بن ہلال محاربیؒ","b"],[" کہتے ہیں جب حضرت عمر بن خطابؓ خلیفہ بنے تو انہوں نے منبر پر کھڑے ہو کر ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اے لوگو! غور سے سنو! میں دعا کروں گا تم سب اس پر آمین کہنا",""]]],["q",[["ٱللَّهُمَّ إِنِّي غَلِيظٌ فَلَيِّنِّي وَشَحِيحٌ فَسَخِّنِي وَضَعِيفٌ فَقَوِّنِي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں سخت ہوں مجھے نرم کر دے، کنجوس ہوں مجھے سخی بنا دے، کمزور ہوں مجھے قوی کر دے۔\"",""],[" (16)","s"]]]],"f":[["(16)","Abu Nu'aym in his Hilyah also."]]},{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں حضرت عمرؓ جب نماز جنازہ پڑھاتے تو فرماتے تیرا یہ بندہ دنیا سے رہائی پا گیا اور دنیا والوں کے لیے چھوڑ کر چلا گیا اور اب وہ تیرا محتاج ہے، تجھے اس کی کوئی ضرورت نہیں۔ وہ اس بات کی گواہی دیا کرتا تھا کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں اور حضرت محمدؐ تیرے بندے اور رسول ہیں۔ اے ",""],["ٱللَّٰه","a"],["! اس کی مغفرت فرما، اس سے درگزر فرما اور اسے اس کے نبی کے پاس پہنچا دے۔",""],[" (17)","s"]]]],"f":[["(17)","Abu Ya'la with a sound chain, as quoted in Kanzul Ummaal (Vol.8 Pg.113)."]]},{"b":[["n",[["حضرت کثیر بن مدرکؒ","b"],[" کہتے ہیں جب قبر پر مٹی ڈال دی جاتی تو حضرت عمرؓ فرماتے",""]]],["q",[["ٱللَّهُمَّ أَسْلَمَهُ إِلَيْكَ ٱلْأَهْلُ وَٱلْمَالُ وَٱلْعَشِيرَةُ وَذَنْبٌ عَظِيمٌ فَٱغْفِرْ لَهُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اہل و عیال، مال اور خاندان والوں نے اسے تیرے سپرد کر دیا ہے اور اس کے گناہ بھی بڑے بڑے ہیں، اس کی مغفرت فرما۔\"",""],[" (18)","s"]]]],"f":[["(18)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.8 Pg.119)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ جَهْدِ ٱلْبَلَاءِ وَدَرَكِ ٱلشَّقَاءِ وَشَمَاتَةِ ٱلْأَعْدَاءِ وَأَعُوذُ بِكَ مِنَ ٱلسِّجْنِ وَٱلْقَيْدِ وَٱلسَّوْطِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! بلا و مصیبت کی سختی اور بدقسمتی کے پکڑ لینے سے اور دشمنوں کے خوش ہونے سے تیری پناہ چاہتا ہوں اور جیل، بیڑی اور کوڑے سے تیری پناہ چاہتا ہوں۔\"",""],[" (19)","s"]]]],"f":[["(19)","Yusuf Qaadi, as quoted in Kanzul Ummaal (Vol.1 Pg.304)."]]},{"b":[["n",[["حضرت ثوریؒ","b"],[" کہتے ہیں مجھے یہ خبر پہنچی ہے کہ حضرت علی بن ابی طالبؓ یہ دعا کیا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنَّ ذُنُوبِي لَا تَضُرُّكَ وَإِنَّ رَحْمَتَكَ إِيَّايَ لَا تَنْقُصُكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میرے گناہ تیرا کوئی نقصان نہیں کر سکتے اور تو مجھ پر رحم فرمائے تو اس سے تیرے خزانوں میں کوئی کمی نہیں آئے گی۔\"",""],[" (20)","s"]]]],"f":[["(20)","Dinawari, as quoted in Kanzul Ummaal (Vol.1 Pg.305)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" جب نیا چاند دیکھا کرتے تو فرمایا کرتے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَٰذَا ٱلشَّهْرِ وَفَتْحَهُ وَنَصْرَهُ وَبَرَكَتَهُ وَرِزْقَهُ وَنُورَهُ وَطُهْرَهُ وَهُدَاهُ وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا فِيهِ وَشَرِّ مَا بَعْدَهُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے اس مہینے کی خیر اور اس کی فتح، نصرت، برکت، رزق، نور، طہارت اور ہدایت مانگتا ہوں اور اس کے شر سے اور جو کچھ اس میں ہے اس کے شر سے اور جو کچھ اس کے بعد ہے اس کے شر سے تیری پناہ چاہتا ہوں۔\"",""],[" (21)","s"]]]],"f":[["(21)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.4 Pg.326)."]]},{"b":[["n",[["حضرت عمر بن سعید نخعیؒ","b"],[" کہتے ہیں میں نے حضرت علی بن ابی طالبؓ کے پیچھے ابن مکفف کی نماز جنازہ پڑھی۔ حضرت علیؓ نے چار تکبیریں کہیں اور ایک طرف سلام پھیرا، پھر انہوں نے ابن مکفف کو قبر میں اتارا اور پھر فرمایا اے ",""],["ٱللَّٰه","a"],["! یہ تیرا بندہ ہے اور تیرے بندے کا بیٹا ہے، تیرا مہمان بنا ہے اور تو بہترین میزبان ہے۔ اے ",""],["ٱللَّٰه","a"],["! جس قبر میں یہ داخل ہوا ہے اسے وسیع فرما دے اور اس کے گناہ معاف فرما دے، ہم تو اس کے بارے میں خیر ہی جانتے ہیں لیکن تو ہم سے زیادہ جانتا ہے اور یہ کلمہ شہادت \"اشھد ان ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" وان محمدا رسول ",""],["ٱللَّٰه","a"],["\" پڑھا کرتا تھا۔",""],[" (22)","s"]]]],"f":[["(22)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.8 Pg.119)."]]},{"b":[["n",[["حضرت ابوہیاج اسدیؒ","b"],[" کہتے ہیں میں بیت ",""],["ٱللَّٰه","a"],[" کا طواف کر رہا تھا اتنے میں میں نے ایک آدمی دیکھا جو صرف یہ دعا مانگ رہا تھا",""]]],["q",[["ٱللَّهُمَّ قِنِي شُحَّ نَفْسِي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! مجھے میرے نفس کے بخل سے بچا دے۔\" اور کچھ نہیں مانگ رہا تھا۔ میں نے اس سے صرف یہی دعا کرنے کی وجہ پوچھی۔ اس نے کہا جب مجھے میرے نفس کے شر سے بچا دیا جائے گا تو میں نہ چوری کروں گا، نہ زنا کروں گا اور نہ کوئی اور برا کام کروں گا۔ میں نے ان کے بارے میں لوگوں سے پوچھا کہ یہ کون ہیں؟ تو لوگوں نے بتایا کہ یہ حضرت عبدالرحمٰن بن عوفؓ ہیں۔",""],[" (23)","s"]]]],"f":[["(23)","Ibn Jareer, as quoted in Tafseer Ibn Katheer (Vol.3 Pg.339)."]]},{"b":[["n",[["حضرت ابوعبیدہؒ","b"],[" کہتے ہیں (میرے والد) حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ سے پوچھا گیا کہ جس رات حضورؐ نے آپ سے فرمایا تھا کہ مانگو جو مانگو گے تمہیں دیا جائے گا اس رات آپ نے کیا دعا مانگی تھی؟ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا میں نے یہ دعا مانگی تھی",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا لَا يَرْتَدُّ وَنَعِيمًا لَا يَنْفَدُ وَمُرَافَقَةَ نَبِيِّكَ مُحَمَّدٍ صَلَّى ٱللَّهُ عَلَيْهِ وَسَلَّمَ فِي أَعْلَىٰ دَرَجَةِ ٱلْجَنَّةِ جَنَّةِ ٱلْخُلْدِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے ایسا ایمان مانگتا ہوں جو باقی رہے اور زائل نہ ہو اور ایسی نعمت مانگتا ہوں جو کبھی ختم نہ ہو اور ہمیشہ رہنے کی جنت کے اعلیٰ درجے میں تیرے نبی کریمؐ کی رفاقت مانگتا ہوں۔\"",""],[" (24)","s"]]]],"f":[["(24)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.307). Ibn Asaakir has also reported it from Kumayl from Umar with additional details about the salaah and du'aa, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.236)."]]},{"b":[["n",[["حضرت ابوعبیدہؒ","b"],[" کہتے ہیں میرے والد صاحب نے فرمایا ایک رات میں نماز پڑھ رہا تھا کہ اتنے میں نبی کریمؐ، حضرت ابوبکرؓ اور حضرت عمرؓ میرے پاس سے گزرے۔ حضورؐ نے فرمایا مانگو جو مانگو گے وہ تمہیں دیا جائے گا۔ حضرت عمرؓ کہتے ہیں میں نے بعد میں جا کر حضرت عبد",""],["ٱللَّٰه","a"],["ؓ سے پوچھا کہ کیا دعا مانگی تھی؟ انہوں نے کہا میری ایک دعا ہے جو میں کبھی نہیں چھوڑتا اور وہ یہ ہے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ إِيمَانًا لَا يَبِيدُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے ہلاک نہ ہونے والا ایمان مانگتا ہوں۔\" پھر آگے پچھلی جیسی دعا ذکر کی ہے اور یہ الفاظ بھی ذکر کیے ہیں",""]]],["q",[["وَقُرَّةَ عَيْنٍ لَا تَنْقَطِعُ","a"]]],["p",[["ترجمہ: \"اور ختم نہ ہونے والی آنکھوں کی ٹھنڈک مانگتا ہوں۔\" ابونعیم کی دوسری روایت میں یہ ہے کہ حضرت ابوبکرؓ نے واپس آ کر حضرت عبد",""],["ٱللَّٰه","a"],["ؓ سے کہا جو دعا تم مانگ رہے تھے اس کا ذرا مجھے بھی سناؤ۔ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے کہا پہلے میں نے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء اور عظمت بیان کی پھر میں نے یہ کہا",""]]],["q",[["لَا إِلَٰهَ إِلَّا أَنْتَ وَعْدُكَ حَقٌّ وَلِقَاؤُكَ حَقٌّ وَٱلْجَنَّةُ حَقٌّ وَٱلنَّارُ حَقٌّ وَرُسُلُكَ حَقٌّ وَكِتَابُكَ حَقٌّ وَٱلنَّبِيُّونَ حَقٌّ وَمُحَمَّدٌ صَلَّى ٱللَّهُ عَلَيْهِ وَسَلَّمَ حَقٌّ","a"]]],["p",[["ترجمہ: \"تیرے سوا کوئی معبود نہیں، تیرا وعدہ حق ہے، تیری ملاقات حق ہے، جنت حق ہے، دوزخ حق ہے، تیرے رسول حق ہیں، تیری کتاب حق ہے، سارے نبی برحق ہیں، محمدؐ برحق ہیں۔\"",""],[" (25)","s"],[" (26)","s"]]]],"f":[["(25)","Abu Nu'aym in his Hilyah (Vol.1 Pg.127)."],["(26)","Abu Nu'aym has said (Vol.1 Pg.138) that Sa'eed bin Abil Hasaam has narrated it from Shareek and has placed Sa'eed bin Musayyab between Awn and Abdullah, and then he has traced it through his chain."]]},{"b":[["n",[["حضرت شقیقؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],["ؓ یہ دعائیں کثرت سے کیا کرتے تھے",""]]],["q",[["رَبَّنَا أَصْلِحْ بَيْنَنَا وَأَهْدِنَا سُبُلَ ٱلسَّلَامِ وَنَجِّنَا مِنَ ٱلظُّلُمَاتِ إِلَى ٱلنُّورِ وَٱصْرِفْ عَنَّا ٱلْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَبَارِكْ لَنَا فِي أَسْمَاعِنَا وَأَبْصَارِنَا وَقُلُوبِنَا وَأَزْوَاجِنَا وَذُرِّيَّاتِنَا وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ ٱلتَّوَّابُ ٱلرَّحِيمُ وَٱجْعَلْنَا شَاكِرِينَ لِنِعْمَتِكَ مُثْنِينَ بِهَا قَائِلِينَ بِهَا وَأَتْمِمْهَا عَلَيْنَا","a"]]],["p",[["ترجمہ: \"اے ہمارے رب! ہمارے آپس کے تعلقات خوشگوار بنا دے اور ہمیں اسلام کے راستے دکھا اور ہمیں تاریکیوں سے نجات دے کر روشنی میں لا اور ہم کو ظاہری و باطنی بدکاریوں سے دور رکھ اور ہمارے کانوں کو، ہماری آنکھوں کو، ہمارے دلوں کو اور ہمارے بیوی بچوں کو ہمارے حق میں باعث برکت بنا دے اور ہماری توبہ قبول فرما۔ بیشک تو ہی بڑا توبہ قبول کرنے والا مہربان ہے اور ہمیں اپنی نعمتوں کا شکر گزار اور ان کا ثناخواں اور لوگوں کے سامنے انہیں بیان کرنے والا بنا دے اور ان (نعمتوں) کو ہم پر پورا فرما دے۔\"",""],[" (27)","s"]]]],"f":[["(27)","Bukhaari in Adabul Mufrad (Pg.93)."]]},{"b":[["n",[["حضرت ابوالاحوصؒ","b"],[" کہتے ہیں میں نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ کو یہ دعا مانگتے ہوئے سنا",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ ٱلنِّعْمَةَ ٱلسَّابِغَةَ بِنِعْمَتِكَ ٱلَّتِي أَنْعَمْتَ بِهَا وَبَلَائِكَ ٱلَّذِي ٱبْتَلَيْتَنِي وَبِفَضْلِكَ ٱلَّذِي أَفْضَلْتَ عَلَيَّ أَنْ تُدْخِلَنِي ٱلْجَنَّةَ، ٱللَّهُمَّ أَدْخِلْنِي ٱلْجَنَّةَ بِفَضْلِكَ وَمَنِّكَ وَرَحْمَتِكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے اس نعمت کاملہ کے واسطے سے جو تو نے مجھ پر کی ہے سوال کرتا ہوں کہ تو مجھے جنت میں داخل کر دے۔ اے ",""],["ٱللَّٰه","a"],["! تو اپنے فضل، احسان اور رحمت سے مجھے جنت میں داخل کر دے۔\"",""],[" (28)","s"]]]],"f":[["(28)","Tabraani; Haythami (Vol.10 Pg.185) has said that its narrators are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت ابوقلابہؒ","b"],[" کہتے ہیں حضرت ابن مسعودؓ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنْ كُنْتَ كَتَبْتَنِي فِي أَهْلِ ٱلشِّقَاءِ فَٱمْحُنِي وَأَثْبِتْنِي فِي أَهْلِ ٱلسَّعَادَةِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اگر تو نے میرا نام بدبختی والوں میں لکھا ہوا ہے تو وہاں سے میرا نام مٹا کر خوش قسمت لوگوں میں لکھ دے۔\"",""],[" (29)","s"]]]],"f":[["(29)","Tabraani also; Haythami has said that its narrators are those of authentic Ahaadeeth except that Abu Qilaabah did not meet Ibn Mas'ood."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عکیمؒ","b"],[" کہتے ہیں حضرت ابن مسعودؓ یہ دعا مانگا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ زِدْنِي إِيمَانًا وَيَقِينًا وَفَهْمًا وَعِلْمًا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میرے ایمان و یقین، سمجھ اور علم کو بڑھا دے۔\"",""],[" (30)","s"]]]],"f":[["(30)","Tabraani also; Haythami has said that its chain is jayyid."]]},{"b":[["n",[["حضرت ابووائلؒ","b"],[" کہتے ہیں ایک دن میں نماز فجر سے فارغ ہو کر ابن مسعودؓ کی خدمت میں گیا۔ ہم نے ان سے اندر آنے کی اجازت مانگی۔ انہوں نے فرمایا اندر آ جاؤ۔ ہم نے اپنے دل میں کہا ہم کچھ دیر انتظار کر لیتے ہیں شاید گھر والوں میں سے کسی کا ان سے کوئی کام ہو (تو وہ اپنا کام پورا کر لیں)۔ اتنے میں حضرت ابن مسعودؓ تسبیح پڑھتے ہوئے ہمارے پاس آئے اور فرمایا شاید تم لوگوں نے گمان کیا ہوگا کہ عبد",""],["ٱللَّٰه","a"],[" کے (یعنی میرے) گھر والے اس وقت غفلت میں ہوں گے۔ پھر فرمایا اے باندی! دیکھو سورج نکل آیا ہے؟ اس نے کہا نہیں۔ پھر جب اس کو تیسری مرتبہ کہا دیکھو سورج نکل آیا ہے؟ تو اس نے کہا جی ہاں۔ اس پر انہوں نے کہا",""]]],["q",[["ٱلْحَمْدُ لِلَّهِ ٱلَّذِي وَهَبَنَا هَٰذَا ٱلْيَوْمَ وَأَقَالَنَا فِيهِ عَثَرَاتِنَا أَحْسِبُهُ قَالَ وَلَمْ يُعَذِّبْنَا بِٱلنَّارِ","a"]]],["p",[["ترجمہ: \"تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے ہمیں یہ دن عطا فرمایا اور اس دن میں ہماری تمام لغزشیں معاف فرما دیں (جبکہ ہمیں لغزشوں کے باوجود زندہ رکھا ہے)۔\" راوی کہتے ہیں میرا خیال یہ ہے کہ انہوں نے یہ بھی فرمایا تھا کہ اس نے ہمیں (لغزشوں کی وجہ سے) آگ کا عذاب نہیں دیا۔",""],[" (31)","s"]]]],"f":[["(31)","Tabraani also; Haythami (Vol.10 Pg.118) has said that its narrators are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت سلیم بن حنظلہؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" ابن مسعودؓ بازار کے دروازے کے پاس آئے اور یہ دعا پڑھی",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِهَا وَخَيْرِ أَهْلِهَا وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ أَهْلِهَا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے اس بازار کی خیر اور بازار والوں کی خیر مانگتا ہوں اور اس بازار کے شر اور بازار والوں کے شر سے تیری پناہ چاہتا ہوں۔\"",""],[" (32)","s"]]]],"f":[["(32)","Tabraani as a mawqoof narration; Haythami (Vol.10 Pg.129) has said that its narrators are those of authentic Ahaadeeth except Saleem bin Handhalah who is reliable."]]},{"b":[["n",[["حضرت قتادہؒ","b"],[" کہتے ہیں حضرت ابن مسعودؓ جب کسی بستی میں داخل ہونے کا ارادہ فرماتے تو یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ رَبَّ ٱلسَّمَوَاتِ وَمَا أَظْلَلْنَ وَرَبَّ ٱلشَّيَاطِينِ وَمَا أَضْلَلْنَ وَرَبَّ ٱلرِّيَاحِ وَمَا ذَرَيْنَ، أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا فِيهَا وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيهَا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! جو کہ تمام آسمانوں کا اور جن پر آسمانوں نے سایہ ڈالا ہے ان تمام چیزوں کا رب ہے، جو کہ شیطانوں کا اور جن کو شیطانوں نے گمراہ کیا ہے ان سب کا رب ہے اور جو کہ ہواؤں کا اور ان تمام چیزوں کا رب ہے جنہیں ہواؤں نے اڑایا ہے، میں تجھ سے اس بستی کی خیر اور جو کچھ اس بستی میں ہے اس سب کی خیر مانگتا ہوں اور اس کے شر سے اور جو کچھ اس بستی میں ہے اس کے شر سے تیری پناہ چاہتا ہوں۔\"",""],[" (33)","s"]]]],"f":[["(33)","Tabraani also; Haythami (Vol.10 Pg.135) has said that its narrators are those of authentic Ahaadeeth except that Qataadah did not meet Ibn Mas'ood."]]},{"b":[["n",[["حضرت ثور بن یزیدؒ","b"],[" کہتے ہیں حضرت معاذ بن جبلؓ جب رات کو تہجد کے لیے اٹھتے تو یہ دعا کرتے",""]]],["q",[["ٱللَّهُمَّ قَدْ نَامَتِ ٱلْعُيُونُ وَغَارَتِ ٱلنُّجُومُ وَأَنْتَ حَيٌّ قَيُّومٌ، ٱللَّهُمَّ طَلَبِي لِلْجَنَّةِ بَطِيءٌ وَهَرَبِي مِنَ ٱلنَّارِ ضَعِيفٌ، ٱللَّهُمَّ ٱجْعَلْ لِي عِنْدَكَ هُدًى تَرُدُّهُ إِلَيَّ يَوْمَ ٱلْقِيَامَةِ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! آنکھیں سو چکی ہیں اور ستارے غروب ہو گئے ہیں اور تو ہمیشہ زندہ رہنے والا اور ساری کائنات کو قائم رکھنے والا ہے۔ اے ",""],["ٱللَّٰه","a"],["! میرے اندر جنت کی طلب بہت سست ہے اور مجھ میں دوزخ کی آگ سے بھاگنے کا جذبہ بالکل کمزور ہے۔ اے ",""],["ٱللَّٰه","a"],["! مجھے اپنے پاس سے ایسی ہدایت عطا فرما جو قیامت تک چلتی رہے، بیشک تو وعدہ خلافی نہیں کرتا۔\"",""],[" (34)","s"]]]],"f":[["(34)","Abu Nu'aym in his Hilyah (Vol.1 Pg.233). Tabraani has also reported it but its chain is broken."]]},{"b":[["n",[["بنو نجار کی ایک عورت کہتی ہیں مسجد کے اردگرد کے گھروں میں میرا گھر سب سے اونچا تھا۔ ",""],["حضرت بلالؓ","b"],[" روزانہ صبح کو فجر کی اذان میرے گھر کی چھت پر دیا کرتے تھے۔ سحری کے وقت آ کر چھت پر بیٹھ کر صبح صادق کا انتظار کرتے۔ جب صبح صادق نظر آتی تو انگڑائی لیتے پھر یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ أَحْمَدُكَ وَأَسْتَعِينُكَ عَلَىٰ قُرَيْشٍ أَنْ يُقِيمُوا دِينَكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تیری تعریف کرتا ہوں اور قریش کے لیے تجھ سے مدد مانگتا ہوں تاکہ وہ تیرے دین کو قائم کریں۔\" پھر وہ اذان دیتے۔ مجھے بالکل یاد نہیں کہ کسی رات حضرت بلالؓ نے یہ دعائیہ کلمات (اذان سے پہلے) چھوڑے ہوں۔",""],[" (35)","s"]]]],"f":[["(35)","Ibn Is'haaq through Urwah, and Abu Dawood has reported it from Urwah's narration alone, as quoted in Al Bidaayah wan Nihaayah (Vol.3 Pg.233)."]]},{"b":[["n",[["حضرت بلالؓ","b"],[" کی بیوی ",""],["حضرت ہندؓ","b"],[" کہتی ہیں حضرت بلالؓ جب بستر پر لیٹتے تو یہ دعا کرتے",""]]],["q",[["ٱللَّهُمَّ تَجَاوَزْ عَنْ سَيِّئَاتِي وَٱعْذِرْنِي بِعِلَّاتِي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میری برائیوں سے درگزر فرما اور میری بیماریوں کی وجہ سے مجھے معذور قرار دے۔\"",""],[" (36)","s"]]]],"f":[["(36)","Tabraani; Haythami (Vol.10 Pg.125) has said that I do not know Hind, while the remaining narrators are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت زید بن ثابتؓ","b"],[" جب بستر پر لیٹتے تو یہ دعا کرتے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ غِنَى ٱلْأَهْلِ وَٱلْمَوْلَىٰ وَأَعُوذُ بِكَ أَنْ تَدْعُوَ عَلَيَّ رَحِمٌ قَطَعْتُهَا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے اہل و عیال کے اور تمام متعلقین کے غنا کو مانگتا ہوں اور میں اس بات سے تیری پناہ چاہتا ہوں کہ میں رشتے توڑوں اور وہ رشتہ میرے لیے بددعا کرے۔\"",""],[" (37)","s"]]]],"f":[["(37)","Tabraani; Haythami (Vol.10 Pg.125) has said that its chain is jayyid."]]},{"b":[["n",[["حضرت عروہؒ","b"],[" کہتے ہیں حضرت سعد بن عبادہؓ یہ دعا کیا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ هَبْ لِي حَمْدًا وَهَبْ لِي مَجْدًا لَا مَجْدَ إِلَّا بِفِعَالٍ وَلَا فِعَالَ إِلَّا بِمَالٍ، ٱللَّهُمَّ لَا يُصْلِحُنِي ٱلْقَلِيلُ وَلَا أُصْلِحُ عَلَيْهِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! مجھے تعریف عطا فرما اور مجھے بزرگی عطا فرما اور بزرگی کسی بڑے کام کے ذریعہ سے ہی حاصل ہو سکتی ہے اور کوئی بڑا کام مال کے ذریعہ سے ہی ہوا کرتا ہے۔ اے ",""],["ٱللَّٰه","a"],["! تھوڑا مال میرے حالات درست نہیں کر سکتا اور نہ ہی تھوڑے مال سے میں درست رہ سکتا ہوں (لہٰذا تو اپنی شان کے مطابق اپنے خزانوں میں سے عطا فرما)۔\"",""],[" (38)","s"]]]],"f":[["(38)","Ibn Sa'd (Vol.3 Pg.614)."]]},{"b":[["n",[["حضرت بلال بن سعدؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ تَفَرُّقِ ٱلْقَلْبِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں دل کے بکھر جانے سے تیری پناہ چاہتا ہوں۔\" کسی نے پوچھا دل کے بکھر جانے سے کیا مراد ہے؟ فرمایا اس سے مراد یہ ہے کہ ",""],["ٱللَّٰه","a"],[" کی طرف سے میرے لیے ہر وادی میں کچھ مال رکھ دیا جائے (اور مجھے ہر وادی میں جا کر اپنے مقدر کا مال جمع کرنا پڑے)۔",""],[" (39)","s"]]]],"f":[["(39)","Abu Nu'aym in his Hilyah (Vol.1 Pg.219)."]]},{"b":[["n",[["حضرت اسماعیل بن عبید","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ تَوَفَّنِي مَعَ ٱلْأَبْرَارِ وَلَا تُبْقِنِي مَعَ ٱلْأَشْرَارِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! مجھے نیک لوگوں کے ساتھ موت دے اور مجھے برے لوگوں کے ساتھ باقی نہ رکھ۔\"",""]]]],"f":[]},{"b":[["n",[["حضرت لقمان بن عامرؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ لَا تَبْتَلِنِي بِعَمَلِ سُوءٍ فَأُدْعَىٰ بِهِ رَجُلَ سُوءٍ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! مجھے کسی برے عمل میں مبتلا نہ فرما ورنہ مجھے برا آدمی کہہ کر پکارا جائے گا۔\"",""],[" (40)","s"]]]],"f":[["(40)","Abu Nu'aym also (Vol.1 Pg.220)."]]},{"b":[["n",[["حضرت حسان بن عطیہؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ تَلْعَنَنِي قُلُوبُ ٱلْعُلَمَاءِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں اس بات سے تیری پناہ چاہتا ہوں کہ علماء کے دل مجھ پر لعنت کریں۔\" کسی نے پوچھا ان کے دل آپ کو کیسے لعنت کریں گے؟ فرمایا ان کے دل مجھے ناپسند کرنے لگیں۔",""],[" (41)","s"]]]],"f":[["(41)","Abu Nu'aym also (Vol.1 Pg.223)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن یزید بن ربیعہ دمشقیؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ نے فرمایا کہ ایک مرتبہ میں شروع رات میں مسجد گیا، وہاں میرا گزر ایک آدمی پر ہوا جو سجدے میں یہ کہہ رہا تھا",""]]],["q",[["ٱللَّهُمَّ إِنِّي خَائِفٌ مُسْتَجِيرٌ فَأَجِرْنِي مِنْ عَذَابِكَ وَسَائِلٌ فَقِيرٌ فَٱرْزُقْنِي مِنْ فَضْلِكَ لَا مُذْنِبٌ فَأَعْتَذِرُ وَلَا ذُو قُوَّةٍ فَأَنْتَصِرُ وَلَٰكِنْ مُذْنِبٌ مُسْتَغْفِرٌ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں ڈرنے والا اور پناہ مانگنے والا ہوں لہٰذا مجھے اپنے عذاب سے پناہ دے اور مانگنے والا اور فقیر ہوں لہٰذا اپنے فضل سے روزی عطا فرما اور جو گناہ مجھ سے ہوئے ہیں ان کے بارے میں میرے پاس کوئی عذر نہیں جسے میں تیرے سامنے پیش کر سکوں اور نہ میں ایسا طاقتور ہوں کہ تجھ سے خود کو بچا سکوں بلکہ میں تو سراپا گنہگار ہوں اور تجھ سے مغفرت کا طلبگار ہوں۔\" راوی کہتے ہیں حضرت ابوالدرداءؓ کو یہ دعائیہ کلمات بہت پسند آئے اور وہ اپنے ساتھیوں کو یہ کلمات سکھانے لگے۔",""],[" (42)","s"]]]],"f":[["(42)","Abu Nu'aym in his Hilyah (Vol.1 Pg.224)."]]},{"b":[["n",[["حضرت ثمامہ بن حزنؒ","b"],[" کہتے ہیں میں نے ایک بڑے میاں کو بلند آواز سے یہ کہتے ہوئے سنا",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلشَّرِّ لَا يُخَالِطُهُ شَيْءٌ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں اس شر سے تیری پناہ مانگتا ہوں جس کے ساتھ کچھ بھی خیر ملا ہوا نہ ہو یعنی خالص شر ہو۔\" میں نے پوچھا یہ بڑے میاں کون ہیں؟ لوگوں نے بتایا حضرت ابوالدرداءؓ ہیں۔",""],[" (43)","s"]]]],"f":[["(43)","Bukhaari in Adabul Mufrad (Pg.99)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" فرماتے تھے اے ",""],["ٱللَّٰه","a"],["! میں اس بات سے تیری پناہ چاہتا ہوں کہ تو میرے بھائی عبد",""],["ٱللَّٰه","a"],[" بن رواحہ کے سامنے میرا ایسا کوئی عمل پیش کرے جس سے وہ شرمندہ ہوں (حضرت ابن رواحہ ان کے جاہلیت میں بھائی تھے اور ان کی دعوت پر مسلمان ہوئے تھے)۔",""],[" (44)","s"]]]],"f":[["(44)","Haakim, as quoted in Kanzul Ummaal (Vol.1 Pg.306)."]]},{"b":[["n",[["حضرت نافعؒ","b"],[" کہتے ہیں حضرت ابن عمرؓ صفا پر یہ دعا کیا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ ٱعْصِمْنِي بِدِينِكَ وَطَوَاعِيَتِكَ وَطَوَاعِيَةِ رَسُولِكَ، ٱللَّهُمَّ جَنِّبْنِي حُدُودَكَ، ٱللَّهُمَّ ٱجْعَلْنِي مِمَّنْ يُحِبُّكَ وَيُحِبُّ مَلَائِكَتَكَ وَيُحِبُّ رُسُلَكَ وَيُحِبُّ عِبَادَكَ ٱلصَّالِحِينَ، ٱللَّهُمَّ حَبِّبْنِي إِلَيْكَ وَإِلَىٰ مَلَائِكَتِكَ وَإِلَىٰ رُسُلِكَ وَإِلَىٰ عِبَادِكَ ٱلصَّالِحِينَ، ٱللَّهُمَّ يَسِّرْنِي لِلْيُسْرَىٰ وَجَنِّبْنِي ٱلْعُسْرَىٰ وَٱغْفِرْ لِي فِي ٱلْآخِرَةِ وَٱلْأُولَىٰ وَٱجْعَلْنِي مِنْ أَئِمَّةِ ٱلْمُتَّقِينَ، ٱللَّهُمَّ إِنَّكَ قُلْتَ ٱدْعُونِي أَسْتَجِبْ لَكُمْ وَإِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ، ٱللَّهُمَّ إِذْ هَدَيْتَنِي لِلْإِسْلَامِ فَلَا تَنْزِعْنِي مِنْهُ وَلَا تَنْزِعْهُ مِنِّي حَتَّىٰ تَقْبِضَنِي وَأَنَا عَلَيْهِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اپنے دین کے ذریعہ سے اور اپنی اور اپنے رسول کی اطاعت کے ذریعہ سے میری حفاظت فرما۔ اے ",""],["ٱللَّٰه","a"],["! مجھے اپنے حرام کردہ کاموں سے بچا۔ اے ",""],["ٱللَّٰه","a"],["! مجھ کو ان لوگوں میں بنا دے جو تجھ سے اور تیرے فرشتوں سے اور تیرے رسولوں سے اور تیرے نیک بندوں سے محبت کرتے ہیں۔ اے ",""],["ٱللَّٰه","a"],["! مجھے اپنا اور اپنے فرشتوں کا اور اپنے رسولوں کا اور اپنے نیک بندوں کا محبوب بنا دے۔ اے ",""],["ٱللَّٰه","a"],["! مجھے نیکی کی توفیق عطا فرما اور برائی سے محفوظ فرما اور دنیا و آخرت میں میری مغفرت فرما اور مجھے متقیوں کا امام بنا۔ اے ",""],["ٱللَّٰه","a"],["! تو نے (قرآن میں) فرمایا ہے مجھے پکارو میں تمہاری درخواست قبول کروں گا اور تو وعدے کے خلاف نہیں کرتا۔ اے ",""],["ٱللَّٰه","a"],["! جب تو نے مجھے اسلام کی ہدایت دے دی ہے تو مجھے اسلام سے نہ نکال اور نہ اسلام کو مجھ سے چھین بلکہ جب تو میری روح قبض کرے تو میں اسلام پر ہوں۔\" حضرت ابن عمرؓ صفا مروہ پر اور عرفات و مزدلفہ میں اور منیٰ کے دو جمروں کے درمیان اور طواف میں اپنی لمبی دعا کے ساتھ یہ دعا بھی مانگتے تھے۔",""],[" (45)","s"]]]],"f":[["(45)","Abu Nu'aym in his Hilyah (Vol.1 Pg.308)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن سبرہؒ","b"],[" کہتے ہیں حضرت ابن عمرؓ صبح کے وقت یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ ٱجْعَلْنِي مِنْ أَعْظَمِ عِبَادِكَ عِنْدَكَ نَصِيبًا فِي كُلِّ خَيْرٍ تَقْسِمُهُ ٱلْغَدَاةَ وَنُورًا تَهْدِي بِهِ وَرَحْمَةً تَنْشُرُهَا وَرِزْقًا تَبْسُطُهُ وَضُرًّا تَكْشِفُهُ وَبَلَاءً تَرْفَعُهُ وَفِتْنَةً تَصْرِفُهَا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! مجھے اپنے ان بندوں میں سے بنا کہ آج صبح تو جتنی خیریں تقسیم کرے ان میں تیرے نزدیک سب سے زیادہ حصہ ہو اور جس نور سے تو ہدایت دیتا ہے اور جس رحمت کو تو پھیلاتا ہے اور جس رزق کو تو وسعت دیتا ہے اور جس تکلیف کو تو دور کرتا ہے اور جس آزمائش کو تو ہٹاتا ہے اور جس فتنے کو تو پھیر دیتا ہے سب چیزیں انہیں سب سے زیادہ حاصل ہوں۔\"",""],[" (46)","s"]]]],"f":[["(46)","Abu Nu'aym in his Hilyah (Vol.1 Pg.302). Tabraani has reported a similar narration from him; Haythami (Vol.10 Pg.182) has said that its narrators are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت سعید بن جبیرؒ","b"],[" کہتے ہیں حضرت ابن عباسؓ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ بِنُورِ وَجْهِكَ ٱلَّذِي أَشْرَقَتْ لَهُ ٱلسَّمَوَاتُ وَٱلْأَرْضُ أَنْ تَجْعَلَنِي فِي حِرْزِكَ وَحِفْظِكَ وَجِوَارِكَ وَتَحْتَ كَنَفِكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تیری ذات کے اس نور کے واسطے سے جس کی وجہ سے سارے آسمان اور زمین روشن ہو گئے تجھ سے اس بات کا سوال کرتا ہوں کہ تو مجھے اپنے حفظ و امان میں، اپنی پناہ میں اور اپنے سایہ کے نیچے لے لے۔\"",""],[" (47)","s"]]]],"f":[["(47)","Bazzaar; Haythami has said that its narrators are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت سعیدؒ","b"],[" کہتے ہیں حضرت ابن عباسؓ فرمایا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ قَنِّعْنِي وَبَارِكْ لِي فِيهِ وَٱخْلُفْ عَلَيَّ كُلَّ غَائِبَةٍ بِخَيْرٍ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تو نے مجھے جو کچھ دیا ہے اس پر مجھے قناعت نصیب فرما اور اس میں برکت نصیب فرما اور میری جتنی چیزیں اس وقت یہاں موجود نہیں ہیں بلکہ غائب ہیں ان سب چیزوں میں تو خیر کے ساتھ میرا خلیفہ بن جا اور انہیں اچھی طرح سنبھال لے۔\"",""],[" (48)","s"]]]],"f":[["(48)","Bukhaari in Adabul Mufrad (Pg.101)."]]},{"b":[["n",[["حضرت طاؤسؒ","b"],[" کہتے ہیں میں نے حضرت ابن عباسؓ کو یہ فرماتے ہوئے سنا",""]]],["q",[["ٱللَّهُمَّ تَقَبَّلْ شَفَاعَةَ مُحَمَّدٍ ٱلْكُبْرَىٰ وَٱرْفَعْ دَرَجَتَهُ ٱلْعُلْيَا وَأَعْطِهِ سُؤْلَهُ فِي ٱلْآخِرَةِ وَٱلْأُولَىٰ كَمَا آتَيْتَ إِبْرَاهِيمَ وَمُوسَىٰ عَلَيْهِمَا ٱلسَّلَامُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! محمدؐ کی شفاعت کبریٰ قبول فرما اور ان کے بلند درجے کو اور اونچا فرما اور انہوں نے آپ سے جو کچھ مانگا ہے وہ سب کچھ انہیں دنیا و آخرت میں عطا فرما جیسے تو نے حضرت ابراہیمؑ اور حضرت موسیٰؑ علیہ السلام کو عطا فرمایا تھا۔\"",""],[" (49)","s"]]]],"f":[["(49)","Ismaa'eel Qaadi, as quoted by Ibn Katheer in his Tafseer (Vol.3 Pg.513), who said that its chain is jayyid, strong and authentic."]]},{"b":[["n",[["حضرت ام الدرداءؓ","b"],[" فرماتی ہیں حضرت فضالہ بن عبیدؓ یہ دعا کیا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ ٱلرِّضَا بِٱلْقَضَاءِ وَٱلْقَدَرِ وَبَرْدَ ٱلْعَيْشِ بَعْدَ ٱلْمَوْتِ وَلَذَّةَ ٱلنَّظَرِ إِلَىٰ وَجْهِكَ وَٱلشَّوْقَ إِلَىٰ لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَلَا فِتْنَةٍ مُضِلَّةٍ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے اس بات کا سوال کرتا ہوں کہ میں تیری ہر تقدیر اور فیصلے پر راضی رہا کروں اور موت کے بعد مجھے عمدہ زندگی نصیب ہو اور تیرے دیدار کی لذت حاصل ہو اور مجھے تیری ملاقات کا شوق نصیب ہو اور تکلیف دہ مصیبت اور گمراہ کن فتنہ سے میری حفاظت ہو۔\" حضرت فضالہؓ کہتے تھے حضورؐ یہ تمام دعائیں مانگا کرتے تھے۔",""],[" (50)","s"]]]],"f":[["(50)","Tabraani; Haythami (Vol.10 Pg.177) has said that Tabraani has reported it in his Awsat and Kabeer and that the narrators of both are reliable."]]},{"b":[["n",[["حضرت مقبریؒ","b"],[" کہتے ہیں مروان حضرت ابوہریرہؓ کے مرض الوفات میں ان کے پاس گیا اور اس نے کہا اے ابوہریرہ! ",""],["ٱللَّٰه","a"],[" آپ کو شفا عطا فرمائے۔ انہوں نے فرمایا",""]]],["q",[["ٱللَّهُمَّ إِنِّي أُحِبُّ لِقَاءَكَ فَأَحِبَّ لِقَائِي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تیری ملاقات کو محبوب رکھتا ہوں تو میری ملاقات کو محبوب بنا لے۔\" چنانچہ وہاں سے چل کر مروان ابھی اصحاب القطا مقام تک نہیں پہنچا تھا کہ پیچھے حضرت ابوہریرہؓ کا انتقال ہو گیا۔",""],[" (51)","s"]]]],"f":[["(51)","Ibn Sa'd (Vol.3 Pg.339)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن ہشامؒ","b"],[" کہتے ہیں حضورؐ کے صحابہؓ سال یا مہینہ کے شروع ہونے پر یہ دعا پڑھا کرتے تھے",""]]],["q",[["ٱللَّهُمَّ أَدْخِلْهُ عَلَيْنَا بِٱلْأَمْنِ وَٱلْإِيمَانِ وَٱلسَّلَامَةِ وَٱلْإِسْلَامِ وَرِضْوَانٍ مِنَ ٱلرَّحْمَٰنِ وَجِوَارٍ مِنَ ٱلشَّيْطَانِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اس سال یا مہینے کو امن، ایمان، سلامتی، اسلام، رحمان کی رضا اور شیطان سے پناہ کے ساتھ ہم پر داخل فرما۔\"",""],[" (52)","s"]]]],"f":[["(52)","Tabraani in his Awsat; Haythami (Vol.10 Pg.139) has said that its chain is hasan. In the margin it is noted from Ibn Hajar that Rishdeen bin Sa'd, who is weak, is in its chain."]]},{"b":[["n",[["حضرت ابوامامہ بن سہلؒ","b"],[" کہتے ہیں میں نے حضرت ابوہریرہؓ سے پوچھا صحابہؓ جب کسی بستی کے پاس پہنچتے یا اس میں داخل ہوتے تو یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ ٱجْعَلْ لَنَا فِيهَا رِزْقًا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اس بستی میں ہمارے لیے رزق مقدر فرما۔\" وہ یہ دعا کس ڈر سے پڑھا کرتے تھے؟ حضرت ابوہریرہؓ نے فرمایا بستی کے والی کے ظلم کا اور بارش نہ ہونے کا ڈر رہتا تھا۔",""],[" (53)","s"]]]],"f":[["(53)","Bazzaar; Haythami (Vol.10 Pg.135) has said that its narrators are those of authentic Ahaadeeth except Qays bin Saalim who is reliable."]]},{"b":[["n",[["حضرت ثابتؒ","b"],[" کہتے ہیں حضرت انسؓ جب اپنے بھائی کے لیے دعا کرتے تو یہ کہتے ",""],["ٱللَّٰه","a"],[" اس پر ان نیک لوگوں والی رحمتیں نازل فرمائے جو ظالم اور بدکار نہیں جو رات بھر عبادت کرتے ہیں اور دن کو روزہ رکھتے ہیں۔",""],[" (54)","s"]]]],"f":[["(54)","Bukhaari in Adabul Mufrad (Pg.93)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن زبیرؓ","b"],[" جب بادل گرجنے کی آواز سنتے تو بات کرنا چھوڑ دیتے اور یہ پڑھتے",""]]],["q",[["سُبْحَانَ ٱلَّذِي يُسَبِّحُ ٱلرَّعْدُ بِحَمْدِهِ وَٱلْمَلَائِكَةُ مِنْ خِيفَتِهِ","a"]]],["p",[["ترجمہ: \"وہ ذات پاک ہے جس کے خوف سے رعد فرشتہ اور دوسرے فرشتے اس کی حمد کے ساتھ پاکی بیان کرتے ہیں۔\" پھر فرماتے یہ زمین والوں کے لیے ",""],["ٱللَّٰه","a"],[" کی طرف سے دھمکی ہے۔",""],[" (55)","s"]]]],"f":[["(55)","Bukhaari in Adabul Mufrad (Pg.106). Maalik has also reported a similar narration from Ibn Zubayr, as quoted in Mishkaat, except that it does not mention the part from his words 'then he would say' to the end."]]}]},"154":{"lead":[],"stories":[{"b":[["n",[["حضرت محمدؒ، حضرت طلحہؒ، حضرت مہلبؒ، حضرت عمروؒ اور حضرت سعیدؒ","b"],[" کہتے ہیں حضرت سماک بن مخرمہؓ، حضرت سماک بن عبیدؓ اور حضرت سماک بن خرشہؓ حضرت عمرؓ کے پاس وفد بن کر آئے۔ حضرت عمرؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" آپ لوگوں میں برکت عطا فرمائے۔ اے ",""],["ٱللَّٰه","a"],["! ان کے ذریعہ سے اسلام کو بلند فرما اور ان کے ذریعہ سے اسلام کو مضبوط فرما۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Asaakir from Sayf bin Umar, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.131)."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن کعب بن مالکؒ","b"],[" کہتے ہیں جب میرے والد (حضرت کعب بن مالکؓ) کی بینائی چلی گئی تو میں ان کا رہبر ہوا کرتا تھا۔ جب میں ان کے ساتھ جمعہ کے لیے جاتا اور وہ اذان سنتے تو حضرت ابوامامہ اسعد بن زرارہؓ کے لیے استغفار کرتے اور ان کے لیے دعا کرتے۔ میں نے ان سے پوچھا ابا جان! کیا بات ہے آپ جب اذان سنتے ہیں تو ابوامامہؓ کے لیے استغفار کرتے ہیں اور ان کے لیے دعائے خیر اور دعائے رحمت کرتے ہیں؟ انہوں نے فرمایا اے میرے بیٹے! انہوں نے حضورؐ کے آنے سے پہلے ہمیں سب سے پہلے جمعہ پڑھایا تھا اور یہ جمعہ انہوں نے \"بقیع الخضمات\" بستی میں بنو بیاضہ قبیلہ کے پتھریلے میدان کے اس حصہ میں پڑھایا تھا جہاں عبیت قبیلہ کو شکست ہوئی تھی۔ میں نے پوچھا اس دن آپ لوگ کتنے تھے؟ فرمایا ہم چالیس آدمی تھے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abi Shaybah, Tabraani and Abu Nu'aym in his Ma'rifah, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.136)."]]},{"b":[["n",[["بنو بکر بن وائل کے ایک صاحب کہتے ہیں میں بحستان میں ",""],["حضرت بریدہ اسلمیؓ","b"],[" کے ساتھ تھا۔ میں حضرت علیؓ، حضرت عثمانؓ، حضرت طلحہؓ اور حضرت زبیرؓ کے بارے میں ان کی رائے معلوم کرنے کے لیے ان سب حضرات کے کچھ عیب بیان کرنے لگا۔ اس پر حضرت بریدہؓ نے قبلہ کی طرف منہ کر کے ہاتھ اٹھا کر یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! عثمانؓ کی مغفرت فرما اور علی بن ابی طالبؓ کی مغفرت فرما اور طلحہ بن عبید",""],["ٱللَّٰه","a"],["ؓ کی مغفرت فرما اور زبیر بن عوامؓ کی مغفرت فرما۔ پھر میری طرف متوجہ ہو کر فرمایا تمہارا باپ نہ رہے! کیا تم مجھے قتل کرنا چاہتے ہو؟ میں نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! میں آپ کو قتل کرنا نہیں چاہتا بلکہ ان حضرات کے بارے میں آپ کی رائے معلوم کرنا چاہتا ہوں۔ انہوں نے فرمایا ان لوگوں نے ",""],["ٱللَّٰه","a"],[" کے کرم سے شروع اسلام میں بڑے کارنامے سرانجام دیے ہیں (اور ان سے کچھ لغزشیں اختلاف وغیرہ بھی ہوئے ہیں)۔ اب ",""],["ٱللَّٰه","a"],[" کی مرضی ہے چاہے تو ان کے کارناموں کی وجہ سے ان کی چھوٹی موٹی لغزشیں معاف فرما دے اور چاہے تو انہیں عذاب دے۔ ان کا حساب تو ",""],["ٱللَّٰه","a"],[" کے ذمہ ہے (ہمارے ذمہ نہیں ہے)۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Sa'd (Vol.3 Pg.223)."]]}]}}});
